// Banque de questions. o = objectif évalué ; c = index de la bonne réponse, ou tableau d’index
// pour une question à réponses multiples. x (facultatif) : justification de chaque proposition,
// affichée après la réponse (Vrai/Faux proposition par proposition).
const QUESTIONS = [
  // ===================== Domaine 1 — Structure de la matière (42) =====================
  // 1.1 Atome
  { d: 1, o: "1.1", q: "Combien de neutrons possède le noyau \\(\\ce{^{56}_{26}Fe}\\) ?", a: ["26", "30", "56", "82"], c: 1, e: "Nombre de neutrons N = A − Z = 56 − 26 = 30. 56 est le nombre de masse (nucléons), 26 le nombre de protons." },
  { d: 1, o: "1.1", q: "Combien d’électrons possède l’ion \\(\\ce{^{27}_{13}Al^{3+}}\\) ?", a: ["13", "10", "16", "27"], c: 1, e: "L’atome neutre possède 13 électrons (autant que de protons). L’ion 3+ en a perdu 3 : 13 − 3 = 10 électrons. Piège : ajouter les électrons (16) au lieu de les retirer." },
  { d: 1, o: "1.1", q: "Quelle est la composition de l’ion sulfure \\(\\ce{^{32}_{16}S^{2-}}\\) ?", a: ["16 protons, 16 neutrons, 18 électrons", "16 protons, 16 neutrons, 14 électrons", "18 protons, 14 neutrons, 18 électrons", "16 protons, 18 neutrons, 16 électrons"], c: 0, e: "Z = 16 protons ; N = 32 − 16 = 16 neutrons ; l’anion 2− a gagné 2 électrons : 16 + 2 = 18 électrons. Le nombre de protons ne change jamais lors de la formation d’un ion." },
  { d: 1, o: "1.1", q: "Parmi ces paires, laquelle est formée de deux isotopes ?", a: ["\\(\\ce{^{12}_{6}C}\\) et \\(\\ce{^{14}_{6}C}\\)", "\\(\\ce{^{14}_{6}C}\\) et \\(\\ce{^{14}_{7}N}\\)", "\\(\\ce{^{40}_{19}K}\\) et \\(\\ce{^{40}_{20}Ca}\\)", "\\(\\ce{O2}\\) et \\(\\ce{O3}\\)"], c: 0, e: "Des isotopes ont le même Z (même élément) et des A différents : c’est le cas de ¹²C et ¹⁴C (Z = 6). Les paires ¹⁴C/¹⁴N et ⁴⁰K/⁴⁰Ca ont le même A mais des Z différents : ce sont des éléments différents. O₂ et O₃ sont deux molécules (formes allotropiques) du même élément." },
  { d: 1, o: "1.1", q: "En médecine nucléaire, l’iode 131 sert à traiter certaines hyperthyroïdies ; l’iode naturel est l’iode 127 (Z = 53). Quelle affirmation est exacte ?", a: ["Les deux ont 53 protons, l’iode 131 possède 4 neutrons de plus", "L’iode 131 possède 4 protons de plus que l’iode 127", "Leurs propriétés chimiques diffèrent, ce qui permet à la thyroïde de fixer sélectivement l’iode 131", "L’iode 131 est un ion de l’iode 127"], c: 0, e: "Ce sont deux isotopes : même Z = 53, donc même élément et même chimie ; ils diffèrent par le nombre de neutrons (78 contre 74). La thyroïde fixe l’iode quel que soit l’isotope, c’est justement pourquoi l’iode 131 radioactif s’y concentre." },
  { d: 1, o: "1.1", q: "Pourquoi peut-on assimiler la masse d’un atome à celle de son noyau ?", a: ["Parce qu’un électron est environ 1 836 fois plus léger qu’un proton", "Parce que les électrons n’ont pas de masse", "Parce que le noyau occupe presque tout le volume de l’atome", "Parce que la masse des neutrons compense celle des électrons"], c: 0, e: "La masse de l’électron (9,1 × 10⁻³¹ kg) est environ 1 836 fois plus faible que celle du proton : elle est négligeable, mais pas nulle. Le noyau concentre la masse, pas le volume : il est environ 100 000 fois plus petit que l’atome." },
  { d: 1, o: "1.1", q: "Le bore naturel contient 19,9 % de \\(\\ce{^{10}B}\\) (10,01 u) et 80,1 % de \\(\\ce{^{11}B}\\) (11,01 u). Quelle est sa masse atomique ?", a: ["10,81 u", "10,51 u", "10,20 u", "11,01 u"], c: 0, e: "Moyenne pondérée par les abondances : \\(0{,}199 \\times 10{,}01 + 0{,}801 \\times 11{,}01 = 1{,}99 + 8{,}82 = 10{,}81\\) u. Vérification de cohérence : le résultat est plus proche de 11 car ¹¹B est majoritaire. 10,51 correspond à une moyenne non pondérée." },
  { d: 1, o: "1.1", q: "Que représente la masse molaire atomique du carbone, 12,0 g·mol⁻¹ ?", a: ["La masse d’une mole d’atomes de carbone, soit environ \\(6{,}02 \\times 10^{23}\\) atomes", "La masse d’un seul atome de carbone, exprimée en grammes", "Le nombre de nucléons d’un atome de carbone 13", "La masse de 12 atomes de carbone"], c: 0, e: "La masse molaire est la masse d’une mole d’entités (N_A ≈ 6,02 × 10²³). Un atome de carbone pèse environ 12 u, soit 2 × 10⁻²³ g, et non 12 g." },
  { d: 1, o: "1.1", q: "Concernant l’atome \\(\\ce{^{40}_{20}Ca}\\) et l’ion \\(\\ce{Ca^2+}\\), quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["L’ion \\(\\ce{Ca^2+}\\) possède 18 électrons", "L’ion \\(\\ce{Ca^2+}\\) possède 22 protons", "L’atome et l’ion possèdent chacun 20 neutrons", "L’ion \\(\\ce{Ca^2+}\\) est un anion", "Le nombre de masse de l’ion est 38"], c: [0, 2], x: ["20 électrons − 2 = 18.", "Le nombre de protons reste Z = 20 : on ne retire que des électrons.", "N = 40 − 20 = 20, inchangé lors de l’ionisation.", "Une charge positive caractérise un cation.", "A compte les nucléons ; perdre des électrons ne change pas A (40)."], e: "Former un ion ne modifie que le nombre d’électrons : Z et A restent identiques." },
  { d: 1, o: "1.1", q: "Parmi ces propositions sur les constituants de l’atome, lesquelles sont exactes ? (Choisissez 3 réponses)", a: ["Le proton et le neutron ont des masses très voisines", "La charge de l’électron vaut \\(-1{,}602 \\times 10^{-19}\\) C", "Le neutron porte une charge positive", "Le rayon d’un atome est de l’ordre de 100 000 fois celui de son noyau", "Les électrons se trouvent dans le noyau"], c: [0, 1, 3], x: ["1,673 × 10⁻²⁷ kg et 1,675 × 10⁻²⁷ kg.", "C’est la charge élémentaire, affectée du signe −.", "Le neutron est neutre ; c’est le proton qui est positif.", "10⁻¹⁰ m / 10⁻¹⁵ m = 10⁵ : l’atome est essentiellement vide.", "Le noyau contient protons et neutrons ; les électrons forment le nuage électronique."], e: "Noyau = protons (+) et neutrons (0), de masses voisines ; électrons (−) très légers, autour du noyau." },
  { d: 1, o: "1.1", q: "Qu’est-ce qui définit un élément chimique ?", a: ["Son nombre de masse A", "Son numéro atomique Z", "Son nombre de neutrons", "Son nombre d’électrons"], c: 1, e: "Le numéro atomique Z (nombre de protons) définit l’élément : tous les atomes et ions de Z = 6 sont du carbone. A et N varient selon l’isotope, le nombre d’électrons selon la charge." },
  { d: 1, o: "1.1", q: "Le carbone 14 (\\(\\ce{^{14}_{6}C}\\)) est utilisé pour la datation. Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Il possède 8 neutrons", "C’est un isotope du carbone 12", "Il possède 14 protons", "Ses propriétés chimiques diffèrent de celles du carbone 12", "Son numéro atomique Z vaut 14"], c: [0, 1], x: ["N = 14 − 6 = 8.", "Même Z = 6, A différent : isotopes.", "Il a 6 protons ; 14 est le nombre de nucléons.", "Même nombre d’électrons, même chimie : c’est pour cela qu’il est incorporé comme le ¹²C par les êtres vivants.", "Z = 6 ; 14 est A."], e: "¹⁴C : Z = 6, A = 14, N = 8. Isotope radioactif du carbone, chimiquement identique au ¹²C." },
  { d: 1, o: "1.1", q: "Quelle espèce possède le même nombre d’électrons que l’atome de néon (Z = 10) ?", a: ["\\(\\ce{Mg^2+}\\) (Z = 12)", "\\(\\ce{Cl-}\\) (Z = 17)", "\\(\\ce{K+}\\) (Z = 19)", "\\(\\ce{Li+}\\) (Z = 3)"], c: 0, e: "Mg²⁺ : 12 − 2 = 10 électrons, comme Ne. Cl⁻ et K⁺ en ont 18 (comme Ar), Li⁺ en a 2 (comme He)." },
  { d: 1, o: "1.1", q: "Combien de protons contient au total une molécule d’eau \\(\\ce{H2O}\\) (Z(H) = 1 ; Z(O) = 8) ?", a: ["10", "18", "9", "8"], c: 0, e: "2 × 1 + 8 = 10 protons (et 10 électrons, la molécule étant neutre). 18 correspond à la masse molaire (en g·mol⁻¹), pas au nombre de protons." },
  { d: 1, o: "1.1", q: "Le chlore naturel a une masse molaire de 35,5 g·mol⁻¹. Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Cette valeur non entière s’explique par le mélange de deux isotopes, ³⁵Cl et ³⁷Cl", "L’isotope ³⁵Cl est le plus abondant", "Un atome de chlore pèse 35,5 g", "Chaque atome de chlore contient 18,5 neutrons", "Les isotopes 35 et 37 diffèrent par leur nombre de protons"], c: [0, 1], x: ["Masse atomique = moyenne pondérée des isotopes.", "35,5 est plus proche de 35 que de 37 : ³⁵Cl ≈ 76 %.", "35,5 g est la masse d’une mole d’atomes.", "Un atome a un nombre entier de neutrons : 18 (³⁵Cl) ou 20 (³⁷Cl).", "Isotopes : même Z = 17, neutrons différents."], e: "La masse molaire d’un élément est une moyenne sur ses isotopes, pondérée par leurs abondances naturelles." },

  // 1.2 Configuration électronique
  { d: 1, o: "1.2", q: "Quelle est la configuration électronique de l’azote (Z = 7) à l’état fondamental ?", a: ["\\(\\mathrm{1s^2\\,2s^2\\,2p^3}\\)", "\\(\\mathrm{1s^2\\,2s^2\\,2p^5}\\)", "\\(\\mathrm{1s^2\\,2p^5}\\)", "\\(\\mathrm{1s^2\\,2s^1\\,2p^4}\\)"], c: 0, e: "7 électrons dans l’ordre 1s, 2s, 2p : 2 + 2 + 3. La 2s se remplit avant la 2p. 1s² 2s² 2p⁵ correspond au fluor (Z = 9)." },
  { d: 1, o: "1.2", q: "D’après la règle de Klechkowski, quelle sous-couche se remplit juste après la 4s ?", a: ["3d", "4p", "4d", "3p"], c: 0, e: "Ordre par n + ℓ croissant : 4s (4 + 0 = 4), puis 3d (3 + 2 = 5, n plus petit que 4p qui a aussi n + ℓ = 5), puis 4p." },
  { d: 1, o: "1.2", q: "Combien d’électrons au maximum peut contenir la couche électronique n = 3 ?", a: ["18", "8", "9", "32"], c: 0, e: "Une couche n contient n² orbitales, donc au plus 2n² électrons : 2 × 9 = 18 (3s : 2, 3p : 6, 3d : 10). 8 correspond à la règle de l’octet, 9 au nombre d’orbitales." },
  { d: 1, o: "1.2", q: "Combien d’orbitales atomiques comporte une sous-couche d ?", a: ["5", "3", "7", "10"], c: 0, e: "Pour d, ℓ = 2 et m_ℓ prend 2ℓ + 1 = 5 valeurs (−2 à +2) : 5 orbitales, donc 10 électrons au maximum. Piège : 10 est le nombre d’électrons, pas d’orbitales." },
  { d: 1, o: "1.2", q: "Quelle est la configuration électronique de l’ion \\(\\ce{Fe^2+}\\) (Z(Fe) = 26) ?", a: ["\\(\\mathrm{[Ar]\\,3d^6}\\)", "\\(\\mathrm{[Ar]\\,3d^4\\,4s^2}\\)", "\\(\\mathrm{[Ar]\\,3d^8}\\)", "\\(\\mathrm{[Ar]\\,3d^6\\,4s^2}\\)"], c: 0, e: "Fe : [Ar] 3d⁶ 4s². Lors de l’ionisation, on retire d’abord les électrons de n le plus élevé, ici les deux 4s : Fe²⁺ = [Ar] 3d⁶. [Ar] 3d⁶ 4s² est l’atome neutre." },
  { d: 1, o: "1.2", q: "Combien d’électrons célibataires possède l’atome d’oxygène (Z = 8) à l’état fondamental ?", a: ["0", "1", "2", "3"], c: 2, e: "O : 1s² 2s² 2p⁴. D’après Hund, les 4 électrons 2p occupent les 3 orbitales p : une orbitale doublement occupée et deux orbitales à un électron → 2 électrons célibataires." },
  { d: 1, o: "1.2", q: "Que dit le principe d’exclusion de Pauli ?", a: ["Deux électrons d’un même atome ne peuvent pas avoir leurs quatre nombres quantiques identiques", "Les sous-couches se remplissent par valeurs croissantes de n + ℓ", "Dans des orbitales de même énergie, les électrons se placent d’abord avec des spins parallèles", "Les couches se remplissent strictement par n croissant"], c: 0, e: "Pauli limite chaque orbitale à 2 électrons de spins opposés. La deuxième proposition est la règle de Klechkowski, la troisième celle de Hund ; la dernière est fausse (la 4s se remplit avant la 3d)." },
  { d: 1, o: "1.2", q: "Quelle est la configuration électronique du cuivre (Z = 29) à l’état fondamental ?", a: ["\\(\\mathrm{[Ar]\\,3d^{10}\\,4s^1}\\)", "\\(\\mathrm{[Ar]\\,3d^9\\,4s^2}\\)", "\\(\\mathrm{[Ar]\\,3d^{11}}\\)", "\\(\\mathrm{[Kr]\\,4s^1}\\)"], c: 0, e: "Le cuivre est une exception à Klechkowski : une sous-couche 3d pleine (3d¹⁰) est plus stable, d’où [Ar] 3d¹⁰ 4s¹ au lieu de 3d⁹ 4s². Une sous-couche d ne peut pas contenir 11 électrons." },
  { d: 1, o: "1.2", q: "Combien d’électrons de valence possède le chlore (Z = 17) ?", a: ["7", "5", "17", "1"], c: 0, e: "Cl : [Ne] 3s² 3p⁵. La couche de valence (n = 3) contient 2 + 5 = 7 électrons : il lui en manque un pour l’octet, d’où l’ion Cl⁻." },
  { d: 1, o: "1.2", q: "Concernant les couches, sous-couches et orbitales atomiques, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Pour n = 2, ℓ peut valoir 0 ou 1", "Une sous-couche p comporte 3 orbitales", "La couche n = 1 possède une sous-couche p", "\\(m_\\ell\\) prend les valeurs entières de 0 à n", "Une orbitale peut contenir 3 électrons si leurs spins diffèrent"], c: [0, 1], x: ["0 ≤ ℓ ≤ n − 1 : ℓ = 0 (2s) ou 1 (2p).", "ℓ = 1 → m_ℓ = −1, 0, +1 : 3 orbitales.", "Pour n = 1, seul ℓ = 0 est possible : uniquement 1s.", "m_ℓ va de −ℓ à +ℓ.", "Pauli : 2 électrons au maximum par orbitale (deux valeurs de spin seulement)."], e: "Rappels : 0 ≤ ℓ ≤ n − 1 ; −ℓ ≤ m_ℓ ≤ +ℓ ; 2 électrons par orbitale." },
  { d: 1, o: "1.2", q: "Un élément a pour configuration \\(\\mathrm{1s^2\\,2s^2\\,2p^6\\,3s^2\\,3p^6\\,4s^2}\\). Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Il s’agit du calcium (Z = 20)", "Il possède 2 électrons de valence", "Il appartient à la période 3", "Il forme facilement l’ion \\(\\ce{X^2-}\\)", "Sa sous-couche 3d est remplie"], c: [0, 1], x: ["2 + 2 + 6 + 2 + 6 + 2 = 20 électrons.", "Couche n = 4 : 4s², groupe 2.", "Le n le plus élevé est 4 : période 4.", "Il perd ses 2 électrons 4s pour former Ca²⁺.", "La 3d est vide (elle se remplit après la 4s)."], e: "Compter les électrons donne Z ; le n maximal donne la période ; la couche de valence donne le groupe et la charge de l’ion usuel." },
  { d: 1, o: "1.2", q: "Quelles configurations électroniques à l’état fondamental sont correctes ? (Choisissez 3 réponses)", a: ["Na (Z = 11) : \\(\\mathrm{[Ne]\\,3s^1}\\)", "K (Z = 19) : \\(\\mathrm{[Ar]\\,3d^1}\\)", "Cr (Z = 24) : \\(\\mathrm{[Ar]\\,3d^5\\,4s^1}\\)", "\\(\\ce{Cl-}\\) (Z = 17) : \\(\\mathrm{[Ne]\\,3s^2\\,3p^6}\\)", "\\(\\ce{O^2-}\\) (Z = 8) : \\(\\mathrm{1s^2\\,2s^2\\,2p^4}\\)"], c: [0, 2, 3], x: ["10 + 1 = 11 électrons.", "La 4s se remplit avant la 3d : K = [Ar] 4s¹.", "Exception : 3d demi-remplie plus stable.", "18 électrons, comme l’argon.", "O²⁻ a 10 électrons : 1s² 2s² 2p⁶ ; 2p⁴ est l’atome neutre."], e: "Penser aux exceptions Cr et Cu, à l’ordre 4s avant 3d et à la charge des ions." },
  { d: 1, o: "1.2", q: "Dans le sang, le fer circule lié à la transferrine sous forme \\(\\ce{Fe^3+}\\) (Z(Fe) = 26). Combien d’électrons 3d possède cet ion ?", a: ["5", "6", "3", "8"], c: 0, e: "Fe : [Ar] 3d⁶ 4s². Pour Fe³⁺, on retire les 2 électrons 4s puis 1 électron 3d : [Ar] 3d⁵. Piège : retirer les 3 électrons de la 3d (→ 3d³)." },

  // 1.3 Classification périodique
  { d: 1, o: "1.3", q: "Où se situe le soufre (Z = 16) dans le tableau périodique ?", a: ["Période 3, groupe 16", "Période 2, groupe 16", "Période 3, groupe 14", "Période 4, groupe 6"], c: 0, e: "S : [Ne] 3s² 3p⁴. n maximal = 3 → période 3 ; 6 électrons de valence dans le bloc p → groupe 16 (comme l’oxygène)." },
  { d: 1, o: "1.3", q: "Parmi ces éléments, lequel est le plus électronégatif ?", a: ["Fluor", "Oxygène", "Chlore", "Césium"], c: 0, e: "Le fluor est l’élément le plus électronégatif (3,98 sur l’échelle de Pauling), devant l’oxygène (3,44) et le chlore (3,16). Le césium, alcalin lourd, est l’un des moins électronégatifs." },
  { d: 1, o: "1.3", q: "Parmi ces éléments de la période 3, lequel a le plus grand rayon atomique ?", a: ["Na", "Mg", "Cl", "Ar"], c: 0, e: "Sur une période, le rayon diminue de gauche à droite (la charge du noyau augmente à n constant). Le sodium, à gauche, a le plus grand rayon." },
  { d: 1, o: "1.3", q: "Parmi ces éléments, lequel a la plus grande première énergie d’ionisation ?", a: ["Ne", "Li", "Na", "K"], c: 0, e: "L’énergie d’ionisation est maximale pour les gaz nobles (couche pleine, très stable) et minimale pour les alcalins, avec une diminution de haut en bas (Li > Na > K)." },
  { d: 1, o: "1.3", q: "Un élément a pour énergies d’ionisation successives 738, 1 451 puis 7 733 kJ·mol⁻¹. À quel groupe appartient-il ?", a: ["Groupe 2", "Groupe 1", "Groupe 13", "Groupe 17"], c: 0, e: "Le saut brutal se produit entre la 2ᵉ et la 3ᵉ ionisation : on arrache alors un électron d’une couche interne. L’élément a donc 2 électrons de valence : groupe 2 (c’est le magnésium). Lecture de tableau : repérer le rapport le plus grand entre deux valeurs successives." },
  { d: 1, o: "1.3", q: "Quel est l’ordre correct d’électronégativité décroissante ?", a: ["O > N > C > H", "N > O > C > H", "C > O > N > H", "H > C > N > O"], c: 0, e: "Sur la période 2, l’électronégativité augmente de gauche à droite : C (2,55) < N (3,04) < O (3,44). L’hydrogène (2,20) est moins électronégatif que le carbone." },
  { d: 1, o: "1.3", q: "Parmi ces espèces isoélectroniques (10 électrons), laquelle a le plus grand rayon ?", a: ["\\(\\ce{O^2-}\\)", "\\(\\ce{F-}\\)", "\\(\\ce{Na+}\\)", "\\(\\ce{Mg^2+}\\)"], c: 0, e: "À nombre d’électrons égal, plus Z est petit, moins les électrons sont attirés et plus l’espèce est grosse : O²⁻ (Z = 8) > F⁻ > Na⁺ > Mg²⁺ (Z = 12)." },
  { d: 1, o: "1.3", q: "Le chlore, le brome et l’iode appartiennent à quelle famille ?", a: ["Les halogènes (groupe 17)", "Les alcalins (groupe 1)", "Les gaz nobles (groupe 18)", "Les alcalino-terreux (groupe 2)"], c: 0, e: "Groupe 17 : F, Cl, Br, I. Ils ont 7 électrons de valence (ns² np⁵) et forment facilement des anions X⁻." },
  { d: 1, o: "1.3", q: "À propos de l’organisation du tableau périodique, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Les éléments sont rangés par numéro atomique croissant", "Les éléments des blocs s et p d’un même groupe ont le même nombre d’électrons de valence", "Les éléments d’une même période ont des propriétés chimiques voisines", "Les métaux de transition forment le bloc p", "Les gaz nobles occupent le groupe 1"], c: [0, 1], x: ["C’est le principe de la classification actuelle.", "D’où des propriétés chimiques voisines au sein d’un groupe.", "Ce sont les éléments d’un même groupe (colonne) qui se ressemblent.", "Les métaux de transition forment le bloc d (groupes 3 à 12).", "Gaz nobles : groupe 18. Le groupe 1 contient H et les alcalins."], e: "Lignes = périodes (valeur de n) ; colonnes = groupes (même configuration de valence, même chimie)." },
  { d: 1, o: "1.3", q: "Sur l’évolution des propriétés périodiques, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Le rayon atomique diminue de gauche à droite sur une période", "L’énergie d’ionisation diminue de haut en bas dans un groupe", "L’électronégativité augmente de haut en bas dans un groupe", "Un cation est plus petit que l’atome neutre dont il provient", "Le potassium a une énergie d’ionisation plus élevée que le sodium"], c: [0, 1, 3], x: ["La charge nucléaire augmente à n constant.", "L’électron de valence est plus loin du noyau.", "Elle diminue de haut en bas (et augmente vers le fluor).", "Il a perdu des électrons ; les restants sont plus attirés.", "K est sous Na : son électron 4s est plus facile à arracher."], e: "Rayon et énergie d’ionisation varient en sens inverse ; l’électronégativité suit l’énergie d’ionisation (maximale en haut à droite)." },
  { d: 1, o: "1.3", q: "On compare le sodium (Z = 11) et le chlore (Z = 17), tous deux dans la période 3. Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Le chlore a un rayon atomique plus petit que le sodium", "Le sodium a une énergie d’ionisation plus élevée que le chlore", "Le chlore est plus électronégatif que le sodium", "Ils ont le même nombre d’électrons de valence", "Le sodium forme facilement l’anion \\(\\ce{Na-}\\)"], c: [0, 2], x: ["Le rayon diminue de gauche à droite.", "C’est l’inverse : l’énergie d’ionisation augmente vers la droite.", "χ(Cl) = 3,16 contre 0,93 pour Na.", "Na en a 1, Cl en a 7.", "Na perd facilement son électron 3s : il forme Na⁺."], e: "Na, à gauche : gros, peu électronégatif, forme Na⁺. Cl, à droite : petit, électronégatif, forme Cl⁻." },
  { d: 1, o: "1.3", q: "Le lithium est utilisé en psychiatrie sous forme de sels contenant l’ion \\(\\ce{Li+}\\). Pourquoi le lithium forme-t-il facilement cet ion ?", a: ["C’est un alcalin : un seul électron de valence (2s¹) et une faible énergie d’ionisation", "C’est l’élément le plus électronégatif de sa période", "C’est un gaz noble qui perd facilement un électron", "Il possède 7 électrons de valence"], c: 0, e: "Li : 1s² 2s¹. En perdant son unique électron de valence, il acquiert la configuration de l’hélium ; sa première énergie d’ionisation est faible. Les alcalins sont au contraire peu électronégatifs." },
  { d: 1, o: "1.3", q: "Quelle est la définition de l’électronégativité ?", a: ["L’aptitude d’un atome à attirer vers lui les électrons d’une liaison qu’il forme", "L’énergie nécessaire pour arracher un électron à un atome gazeux", "L’énergie libérée quand un atome gazeux capte un électron", "La charge portée par un ion monoatomique"], c: 0, e: "L’électronégativité est une grandeur relative (échelle de Pauling, sans unité) qui concerne un atome engagé dans une liaison. La deuxième proposition définit l’énergie d’ionisation." },
  { d: 1, o: "1.3", q: "Quelle équation correspond à la première énergie d’ionisation du sodium ?", a: ["\\(\\ce{Na(g) -> Na+(g) + e-}\\)", "\\(\\ce{Na(s) -> Na+(aq) + e-}\\)", "\\(\\ce{Na(g) + e- -> Na-(g)}\\)", "\\(\\ce{Na+(g) -> Na^2+(g) + e-}\\)"], c: 0, e: "L’énergie d’ionisation se définit pour l’atome isolé à l’état gazeux, qui perd un électron. La dernière équation correspond à la deuxième ionisation ; la troisième est une capture d’électron." },

  // ===================== Domaine 2 — Liaisons et géométrie (42) =====================
  // 2.1 Liaisons
  { d: 2, o: "2.1", q: "Quel type de liaison unit le sodium et le chlore dans le chlorure de sodium solide ?", a: ["Liaison ionique", "Liaison covalente apolaire", "Liaison métallique", "Liaison hydrogène"], c: 0, e: "Na (χ = 0,93) cède un électron à Cl (χ = 3,16) : Δχ ≈ 2,2, les ions Na⁺ et Cl⁻ s’attirent électrostatiquement dans un cristal ionique." },
  { d: 2, o: "2.1", q: "Quelle molécule contient une liaison covalente apolaire ?", a: ["\\(\\ce{Cl2}\\)", "\\(\\ce{HCl}\\)", "\\(\\ce{H2O}\\)", "\\(\\ce{NaCl}\\)"], c: 0, e: "Une liaison entre deux atomes identiques (Δχ = 0) est apolaire. H–Cl et O–H sont polarisées ; NaCl est ionique." },
  { d: 2, o: "2.1", q: "Dans la liaison O–H de l’eau, où se situe la charge partielle négative δ− ?", a: ["Sur l’oxygène", "Sur l’hydrogène", "Au milieu de la liaison", "Il n’y a pas de charge partielle"], c: 0, e: "L’oxygène (3,44) est plus électronégatif que l’hydrogène (2,20) : il attire le doublet liant et porte δ−, l’hydrogène porte δ+." },
  { d: 2, o: "2.1", q: "Quelle propriété des métaux s’explique directement par la liaison métallique ?", a: ["Leur conductivité électrique, due aux électrons de valence délocalisés", "La dureté du diamant", "La solubilité du chlorure de sodium dans l’eau", "L’existence de molécules diatomiques \\(\\ce{Fe2}\\)"], c: 0, e: "Dans un métal, les électrons de valence sont mis en commun et délocalisés entre les cations : ils se déplacent facilement, d’où la conduction électrique et thermique. Le diamant est un solide covalent ; NaCl est ionique." },
  { d: 2, o: "2.1", q: "Avec χ(H) = 2,20, χ(F) = 3,98, χ(Cl) = 3,16, χ(Br) = 2,96 et χ(I) = 2,66, quelle liaison est la plus polarisée ?", a: ["H–F", "H–Cl", "H–Br", "H–I"], c: 0, e: "Δχ : H–F 1,78 ; H–Cl 0,96 ; H–Br 0,76 ; H–I 0,46. La polarité d’une liaison augmente avec Δχ." },
  { d: 2, o: "2.1", q: "Quelles liaisons sont des liaisons covalentes polarisées ? (Choisissez 2 réponses)", a: ["C–O dans le méthanol", "N–H dans l’ammoniac", "Cl–Cl dans le dichlore", "Na⁺/Cl⁻ dans le sel de cuisine", "C–C dans l’éthane"], c: [0, 1], x: ["Δχ = 3,44 − 2,55 = 0,89 : polarisée.", "Δχ = 3,04 − 2,20 = 0,84 : polarisée.", "Atomes identiques : apolaire.", "Δχ ≈ 2,2 : liaison ionique.", "Atomes identiques : apolaire."], e: "Covalente polarisée : Δχ non nulle mais modérée (grossièrement entre 0,4 et 1,7)." },
  { d: 2, o: "2.1", q: "Concernant les différents types de liaisons, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Une liaison covalente résulte de la mise en commun d’un doublet d’électrons", "Dans un cristal de NaCl, il n’existe pas de molécule NaCl individualisée", "Une liaison ionique se forme typiquement entre deux non-métaux d’électronégativités identiques", "Les métaux conduisent l’électricité grâce à leurs électrons délocalisés", "Une liaison double comporte quatre doublets liants"], c: [0, 1, 3], x: ["Chaque atome apporte en général un électron au doublet liant.", "Le cristal est un empilement d’ions ; « NaCl » est une formule statistique.", "C’est la définition d’une liaison covalente apolaire ; l’ionique suppose une grande Δχ (métal + non-métal).", "C’est la « mer d’électrons » de la liaison métallique.", "Une double liaison = 2 doublets liants (σ + π)."], e: "Covalente : partage ; ionique : transfert puis attraction ; métallique : électrons délocalisés." },
  { d: 2, o: "2.1", q: "Le fluorure de sodium NaF est ajouté à certains dentifrices. Avec χ(Na) = 0,93 et χ(F) = 3,98, quel type de liaison présente-t-il ?", a: ["Ionique", "Covalente apolaire", "Covalente faiblement polarisée", "Métallique"], c: 0, e: "Δχ = 3,98 − 0,93 = 3,05, très supérieure à 1,7 : liaison ionique entre Na⁺ et F⁻." },
  { d: 2, o: "2.1", q: "Dans la liaison C–Cl d’un chloroalcane (χ(C) = 2,55 ; χ(Cl) = 3,16), quel atome porte la charge partielle δ+ ?", a: ["Le carbone", "Le chlore", "Aucun, la liaison est apolaire", "Les deux atomes portent δ+"], c: 0, e: "Le chlore, plus électronégatif, attire le doublet : Cl porte δ−, C porte δ+. C’est ce carbone δ+ qui est attaqué par les nucléophiles." },
  { d: 2, o: "2.1", q: "Avec χ(H) = 2,20, χ(C) = 2,55, χ(N) = 3,04 et χ(O) = 3,44, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["La liaison O–H est plus polarisée que la liaison N–H", "La liaison C–H est très peu polarisée", "Dans la liaison C=O, le carbone porte une charge partielle δ−", "La liaison N–H est plus polarisée que la liaison O–H", "La liaison C–N est apolaire car C et N sont deux non-métaux"], c: [0, 1], x: ["Δχ(O–H) = 1,24 > Δχ(N–H) = 0,84.", "Δχ = 0,35 : on la considère comme quasi apolaire.", "O est plus électronégatif : C porte δ+, O porte δ−.", "C’est l’inverse (0,84 < 1,24).", "Δχ = 0,49 : liaison polarisée ; être deux non-métaux ne suffit pas à être apolaire."], e: "On compare les Δχ ; la charge δ− va toujours à l’atome le plus électronégatif." },
  { d: 2, o: "2.1", q: "Quelle affirmation sur l’électronégativité et la polarité des liaisons est exacte ?", a: ["Plus la différence d’électronégativité est grande, plus la liaison est polarisée", "Une liaison entre deux atomes identiques est ionique", "La charge partielle δ+ est portée par l’atome le plus électronégatif", "La polarité d’une liaison dépend surtout de la masse des atomes"], c: 0, e: "La polarité est liée à Δχ : nulle → apolaire, modérée → polarisée, grande → ionique. δ− sur l’atome le plus électronégatif. La masse n’intervient pas." },

  // 2.2 Représentation des molécules
  { d: 2, o: "2.2", q: "Dans la représentation de Lewis de l’eau, combien l’oxygène porte-t-il de doublets liants et non liants ?", a: ["2 liants et 2 non liants", "2 liants et 1 non liant", "2 liants et 0 non liant", "4 liants et 0 non liant"], c: 0, e: "8 électrons de valence (6 pour O + 2 × 1 pour H) = 4 doublets : 2 liants O–H et 2 non liants sur O, qui respecte l’octet." },
  { d: 2, o: "2.2", q: "Quelle est la charge formelle de l’azote dans l’ion ammonium \\(\\ce{NH4+}\\) ?", a: ["+1", "0", "−1", "+4"], c: 0, e: "CF = 5 (électrons de valence de N) − 0 (non liants) − 4 (liaisons) = +1. La charge de l’ion est portée par l’azote." },
  { d: 2, o: "2.2", q: "Quelle est la représentation de Lewis correcte du dioxyde de carbone ?", a: ["O=C=O, avec deux doublets non liants sur chaque oxygène", "O–C–O, avec trois doublets non liants sur chaque oxygène", "O=C=O, avec un doublet non liant sur le carbone", "O≡C–O, sans doublet non liant"], c: 0, e: "16 électrons de valence (4 + 2 × 6) = 8 doublets : 4 liants (deux doubles liaisons) et 4 non liants (2 par O). Chaque atome a son octet ; le carbone n’a pas de doublet non liant." },
  { d: 2, o: "2.2", q: "Quelle est la formule brute de l’éthanol, de formule semi-développée \\(\\ce{CH3-CH2-OH}\\) ?", a: ["\\(\\ce{C2H6O}\\)", "\\(\\ce{C2H5O}\\)", "\\(\\ce{C2H4O}\\)", "\\(\\ce{CH3O}\\)"], c: 0, e: "On compte : 2 C, 3 + 2 + 1 = 6 H, 1 O → C₂H₆O. Ne pas oublier l’hydrogène du groupe OH." },
  { d: 2, o: "2.2", q: "À propos de la formule brute \\(\\ce{C2H6O}\\), quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Elle peut correspondre à l’éthanol", "Elle peut correspondre au méthoxyméthane", "Elle correspond à une seule molécule possible", "Elle indique l’enchaînement des atomes", "C’est une formule semi-développée"], c: [0, 1], x: ["CH₃–CH₂–OH.", "CH₃–O–CH₃.", "Deux isomères au moins correspondent à cette formule.", "Une formule brute ne donne que la nature et le nombre des atomes.", "Une formule semi-développée montre les liaisons entre atomes lourds."], e: "Une formule brute ne suffit pas à identifier une molécule : il faut une formule développée ou semi-développée." },
  { d: 2, o: "2.2", q: "Quelle est la représentation de Lewis du diazote \\(\\ce{N2}\\) ?", a: ["Une triple liaison et un doublet non liant sur chaque azote", "Une double liaison et deux doublets non liants sur chaque azote", "Une simple liaison et trois doublets non liants sur chaque azote", "Une triple liaison sans doublet non liant"], c: 0, e: "10 électrons de valence = 5 doublets : 3 liants (triple liaison) et 2 non liants (un par N). Chaque N est entouré de 8 électrons." },
  { d: 2, o: "2.2", q: "À propos des représentations de Lewis, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Dans \\(\\ce{BF3}\\), le bore n’est entouré que de 6 électrons", "L’ion hydroxyde \\(\\ce{HO-}\\) compte 8 électrons de valence au total", "Dans \\(\\ce{NH3}\\), l’azote ne porte aucun doublet non liant", "L’hydrogène s’entoure de 8 électrons", "La molécule \\(\\ce{Cl2}\\) porte 3 doublets non liants au total"], c: [0, 1], x: ["Lacune électronique : exception à l’octet.", "6 (O) + 1 (H) + 1 (charge −) = 8.", "Il porte un doublet non liant (5 électrons de valence, 3 liaisons).", "Règle du duet : 2 électrons.", "3 doublets non liants sur chaque Cl, soit 6 au total."], e: "Toujours compter les électrons de valence en tenant compte de la charge, puis vérifier octet (duet pour H)." },
  { d: 2, o: "2.2", q: "Dans une formule semi-développée, quelles liaisons ne sont pas représentées ?", a: ["Les liaisons avec les atomes d’hydrogène", "Les liaisons carbone-carbone", "Les liaisons doubles", "Les liaisons avec les hétéroatomes (O, N)"], c: 0, e: "La formule semi-développée (CH₃–CH₂–OH) montre toutes les liaisons sauf celles qui engagent les hydrogènes ; la formule développée les montre toutes." },

  // 2.3 Géométrie moléculaire
  { d: 2, o: "2.3", q: "Quelle est la géométrie du méthane \\(\\ce{CH4}\\) ?", a: ["Tétraédrique, angles de 109,5°", "Plane carrée, angles de 90°", "Trigonale plane, angles de 120°", "Pyramidale, angles de 107°"], c: 0, e: "CH₄ est de type AX₄ (4 doublets liants, aucun non liant) : les 4 domaines s’orientent vers les sommets d’un tétraèdre, angles de 109,5°." },
  { d: 2, o: "2.3", q: "Quelle est la forme de la molécule d’ammoniac \\(\\ce{NH3}\\) ?", a: ["Pyramide trigonale", "Trigonale plane", "Tétraédrique", "Coudée"], c: 0, e: "NH₃ est AX₃E : 4 domaines répartis en tétraèdre, mais un sommet est occupé par le doublet non liant. La forme (position des atomes) est une pyramide à base triangulaire." },
  { d: 2, o: "2.3", q: "Quelle est la valeur approximative de l’angle H–O–H dans l’eau ?", a: ["104,5°", "109,5°", "120°", "180°"], c: 0, e: "H₂O est AX₂E₂ : répartition tétraédrique des 4 domaines, mais les deux doublets non liants, plus répulsifs, referment l’angle de 109,5° à environ 104,5°." },
  { d: 2, o: "2.3", q: "Selon le modèle VSEPR, de quel type est la molécule \\(\\ce{CO2}\\) (O=C=O) et quelle est sa géométrie ?", a: ["AX₂, linéaire", "AX₄, tétraédrique", "AX₂E₂, coudée", "AX₂E, coudée"], c: 0, e: "Chaque double liaison compte pour un seul domaine et le carbone ne porte pas de doublet non liant : AX₂, linéaire, 180°." },
  { d: 2, o: "2.3", q: "Quelle est la géométrie du trifluorure de bore \\(\\ce{BF3}\\) ?", a: ["Trigonale plane, 120°", "Pyramide trigonale, 107°", "Tétraédrique, 109,5°", "Linéaire, 180°"], c: 0, e: "Le bore n’a que 3 doublets liants et aucun doublet non liant : AX₃, trigonale plane. Contrairement à NH₃, pas de doublet non liant pour former une pyramide." },
  { d: 2, o: "2.3", q: "Comment se classent les angles de liaison de \\(\\ce{CH4}\\), \\(\\ce{NH3}\\) et \\(\\ce{H2O}\\) ?", a: ["CH₄ > NH₃ > H₂O", "H₂O > NH₃ > CH₄", "NH₃ > CH₄ > H₂O", "Ils sont tous égaux à 109,5°"], c: 0, e: "Même répartition tétraédrique (4 domaines), mais 0, 1 puis 2 doublets non liants : chaque doublet non liant referme davantage les angles (109,5° > 107° > 104,5°)." },
  { d: 2, o: "2.3", q: "Parmi ces molécules, laquelle est polaire ?", a: ["\\(\\ce{H2O}\\)", "\\(\\ce{CO2}\\)", "\\(\\ce{CH4}\\)", "\\(\\ce{BF3}\\)"], c: 0, e: "H₂O est coudée : les moments dipolaires des deux liaisons O–H ne s’annulent pas. Les trois autres molécules ont une géométrie symétrique qui annule les moments." },
  { d: 2, o: "2.3", q: "Quelle molécule est apolaire bien que ses liaisons soient polarisées ?", a: ["\\(\\ce{CO2}\\)", "\\(\\ce{H2O}\\)", "\\(\\ce{NH3}\\)", "\\(\\ce{HCl}\\)"], c: 0, e: "Dans CO₂, linéaire et symétrique, les deux moments C=O sont égaux et opposés : leur somme vectorielle est nulle." },
  { d: 2, o: "2.3", q: "Quelle est la géométrie de l’hexafluorure de soufre \\(\\ce{SF6}\\) ?", a: ["Octaédrique, angles de 90°", "Bipyramide trigonale, angles de 90° et 120°", "Hexagonale plane, angles de 60°", "Tétraédrique, angles de 109,5°"], c: 0, e: "SF₆ est AX₆ : 6 domaines dirigés vers les sommets d’un octaèdre, angles de 90°. Le soufre (période 3) peut dépasser l’octet." },
  { d: 2, o: "2.3", q: "À propos de la molécule d’eau, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Elle est de type AX₂E₂", "Sa forme est coudée", "Elle est linéaire car elle ne contient que deux liaisons", "Son angle H–O–H vaut 120°", "Elle est apolaire"], c: [0, 1], x: ["2 doublets liants, 2 doublets non liants sur O.", "Les deux doublets non liants imposent une forme coudée.", "Les doublets non liants comptent : 4 domaines, pas 2.", "Il vaut environ 104,5°.", "Coudée, elle a un moment dipolaire non nul : elle est polaire."], e: "Oublier les doublets non liants est l’erreur classique du modèle VSEPR." },
  { d: 2, o: "2.3", q: "Quelles molécules sont polaires ? (Choisissez 2 réponses)", a: ["\\(\\ce{NH3}\\)", "\\(\\ce{CHCl3}\\)", "\\(\\ce{CCl4}\\)", "\\(\\ce{CO2}\\)", "\\(\\ce{BF3}\\)"], c: [0, 1], x: ["Pyramide : moments non compensés.", "Un H remplace un Cl : la symétrie est rompue.", "Tétraèdre régulier : moments C–Cl compensés.", "Linéaire symétrique : moments opposés.", "Trigonale plane symétrique : moments compensés."], e: "Une molécule est polaire si la somme vectorielle des moments dipolaires de ses liaisons est non nulle ; tout dépend de la géométrie." },
  { d: 2, o: "2.3", q: "À propos du modèle VSEPR, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Une liaison double compte comme un seul domaine électronique", "Un doublet non liant repousse plus fortement qu’un doublet liant", "Une molécule AX₃E est trigonale plane", "Dans NH₃, les 4 domaines électroniques sont répartis de façon tétraédrique", "Le modèle ignore les doublets non liants"], c: [0, 1, 3], x: ["C’est pourquoi CO₂ est AX₂.", "Il occupe plus d’espace et referme les angles.", "AX₃E est une pyramide trigonale (NH₃).", "Répartition tétraédrique, forme pyramidale.", "Au contraire, ils sont essentiels (notés E)."], e: "VSEPR : on compte les domaines (X + E) pour la répartition, puis on nomme la forme d’après les seuls atomes." },
  { d: 2, o: "2.3", q: "Dans \\(\\ce{SO2}\\), le soufre central porte deux liaisons doubles S=O et un doublet non liant. Quelle est la forme de la molécule ?", a: ["Coudée, angle proche de 120°", "Linéaire, 180°", "Trigonale plane, 120° exactement", "Tétraédrique, 109,5°"], c: 0, e: "SO₂ est AX₂E : 3 domaines en répartition trigonale, dont un doublet non liant → forme coudée, angle un peu inférieur à 120° (≈ 119°). À la différence de CO₂, le doublet non liant empêche la linéarité." },

  // 2.4 Interactions
  { d: 2, o: "2.4", q: "Parmi ces composés, lequel peut former des liaisons hydrogène entre ses propres molécules ?", a: ["Le méthanol \\(\\ce{CH3OH}\\)", "Le méthane \\(\\ce{CH4}\\)", "Le méthoxyméthane \\(\\ce{CH3OCH3}\\)", "Le chlorométhane \\(\\ce{CH3Cl}\\)"], c: 0, e: "Il faut un H lié à O, N ou F (donneur) et un doublet sur O, N ou F (accepteur). Le méthanol a les deux. L’éther n’a pas de H lié à O : il peut accepter une liaison H (de l’eau) mais pas en donner." },
  { d: 2, o: "2.4", q: "L’éthanol bout à 78 °C et le méthoxyméthane à −24 °C, alors qu’ils ont la même formule brute. Pourquoi ?", a: ["L’éthanol forme des liaisons hydrogène entre ses molécules", "Le méthoxyméthane a une masse molaire plus faible", "L’éthanol est un composé ionique", "Le méthoxyméthane est plus polaire"], c: 0, e: "Même masse molaire (46 g·mol⁻¹), mais le groupe OH de l’éthanol établit des liaisons hydrogène intermoléculaires, qu’il faut rompre pour vaporiser le liquide." },
  { d: 2, o: "2.4", q: "Quelles interactions expliquent que le diiode \\(\\ce{I2}\\) soit solide à température ambiante ?", a: ["Les forces de London, importantes pour cette grosse molécule très polarisable", "Des liaisons hydrogène entre molécules de diiode", "Des interactions ioniques entre \\(\\ce{I+}\\) et \\(\\ce{I-}\\)", "Des liaisons covalentes entre molécules voisines"], c: 0, e: "I₂ est apolaire : seules les forces de London (dipôles instantanés-induits) interviennent. Elles augmentent avec la taille du nuage électronique : F₂ et Cl₂ gazeux, Br₂ liquide, I₂ solide." },
  { d: 2, o: "2.4", q: "Entre deux molécules de chlorure d’hydrogène HCl, quelle interaction s’ajoute aux forces de London ?", a: ["Une interaction dipôle-dipôle (Keesom)", "Une liaison hydrogène", "Une liaison ionique", "Une liaison métallique"], c: 0, e: "HCl est polaire (dipôle permanent) : interactions de Keesom entre dipôles permanents. Cl n’est pas assez petit et électronégatif pour des liaisons hydrogène notables (seuls F, O, N)." },
  { d: 2, o: "2.4", q: "Combien de liaisons hydrogène relient une paire guanine-cytosine dans l’ADN ?", a: ["3", "2", "1", "4"], c: 0, e: "G–C : 3 liaisons hydrogène ; A–T : 2. C’est pourquoi un ADN riche en G–C est plus stable (température de fusion plus élevée)." },
  { d: 2, o: "2.4", q: "L’eau bout à 100 °C alors que le sulfure d’hydrogène \\(\\ce{H2S}\\), plus lourd, bout vers −60 °C. Quelle est l’explication ?", a: ["Les liaisons hydrogène entre molécules d’eau", "La liaison covalente O–H est plus forte que S–H", "L’eau est une molécule apolaire", "\\(\\ce{H2S}\\) forme des liaisons ioniques"], c: 0, e: "L’ébullition rompt des interactions entre molécules, pas les liaisons covalentes internes. L’oxygène, petit et très électronégatif, permet des liaisons hydrogène ; le soufre non." },
  { d: 2, o: "2.4", q: "À propos de la liaison hydrogène, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Elle nécessite un atome H lié à F, O ou N", "Son énergie est de l’ordre de 10 à 40 kJ·mol⁻¹", "Elle est plus forte qu’une liaison covalente", "Un H lié à un carbone forme facilement des liaisons hydrogène", "Elle ne peut pas exister au sein d’une même molécule"], c: [0, 1], x: ["Condition sur le donneur.", "Intermédiaire entre Van der Waals et covalente.", "Une liaison covalente fait plusieurs centaines de kJ·mol⁻¹.", "C n’est pas assez électronégatif.", "Il existe des liaisons hydrogène intramoléculaires (hélice α par exemple)."], e: "Donneur : H–F, H–O, H–N ; accepteur : doublet non liant de F, O ou N." },
  { d: 2, o: "2.4", q: "À propos des interactions entre molécules, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Les forces de London augmentent avec la taille des molécules", "Les interactions ioniques sont plus fortes que les forces de Van der Waals", "Les interactions de Keesom existent entre molécules apolaires", "Plus les interactions intermoléculaires sont fortes, plus la température d’ébullition est élevée", "Les forces de Van der Waals sont des liaisons covalentes faibles"], c: [0, 1, 3], x: ["La polarisabilité augmente avec le nuage électronique.", "Charges entières contre dipôles : ordre de grandeur supérieur.", "Keesom = dipôles permanents : molécules polaires uniquement.", "Il faut plus d’énergie pour séparer les molécules.", "Ce sont des interactions électrostatiques entre dipôles, sans partage d’électrons."], e: "Ordre habituel : covalente > ionique > liaison hydrogène > Van der Waals." },
  { d: 2, o: "2.4", q: "On veut dissoudre un triglycéride, molécule très apolaire. Quel solvant est le plus adapté ?", a: ["L’hexane", "L’eau", "Une solution de chlorure de sodium", "De l’acide chlorhydrique dilué"], c: 0, e: "« Qui se ressemble s’assemble » : un composé apolaire se dissout dans un solvant apolaire (hexane), avec lequel il établit des forces de London. L’eau et les solutions aqueuses sont polaires." },
  { d: 2, o: "2.4", q: "Dans une protéine, comment qualifie-t-on l’interaction entre le groupe \\(\\ce{-COO-}\\) d’un aspartate et le groupe \\(\\ce{-NH3+}\\) d’une lysine ?", a: ["Une interaction ionique (pont salin)", "Une liaison covalente", "Une force de London", "Une liaison peptidique"], c: 0, e: "Deux charges opposées s’attirent : c’est une interaction ionique, appelée pont salin dans les protéines. Elle participe à la structure tertiaire." },

  // ===================== Domaine 3 — Stœchiométrie (42) =====================
  // 3.1 Mole
  { d: 3, o: "3.1", q: "Quelle quantité de matière d’eau contiennent 36 g d’eau (M = 18 g·mol⁻¹) ?", a: ["2,0 mol", "0,50 mol", "648 mol", "18 mol"], c: 0, e: "\\(n = m/M = 36 / 18 = 2{,}0\\) mol. 0,50 mol correspond à M/m (formule inversée), 648 au produit m × M." },
  { d: 3, o: "3.1", q: "Combien de molécules contient un échantillon de 0,50 mol de dioxygène ? (\\(N_A = 6{,}02 \\times 10^{23}\\) mol⁻¹)", a: ["\\(3{,}0 \\times 10^{23}\\)", "\\(1{,}2 \\times 10^{24}\\)", "\\(6{,}0 \\times 10^{23}\\)", "\\(8{,}3 \\times 10^{-25}\\)"], c: 0, e: "\\(N = n \\times N_A = 0{,}50 \\times 6{,}02 \\times 10^{23} \\approx 3{,}0 \\times 10^{23}\\) molécules. 1,2 × 10²⁴ est le nombre d’atomes d’oxygène contenus dans 1 mol de O₂ ; 8,3 × 10⁻²⁵ vient d’une division n / N_A, qui n’a pas de sens." },
  { d: 3, o: "3.1", q: "Quelle est la masse molaire du glucose \\(\\ce{C6H12O6}\\) ? (C = 12 ; H = 1 ; O = 16 g·mol⁻¹)", a: ["180 g·mol⁻¹", "29 g·mol⁻¹", "168 g·mol⁻¹", "342 g·mol⁻¹"], c: 0, e: "\\(6 \\times 12 + 12 \\times 1 + 6 \\times 16 = 72 + 12 + 96 = 180\\) g·mol⁻¹. 29 est la somme 12 + 1 + 16 sans les indices ; 342 est la masse molaire du saccharose." },
  { d: 3, o: "3.1", q: "Le sérum physiologique contient 9,0 g·L⁻¹ de NaCl (M = 58,5 g·mol⁻¹). Quelle est sa concentration molaire ?", a: ["0,154 mol·L⁻¹", "1,54 mol·L⁻¹", "6,5 mol·L⁻¹", "526 mol·L⁻¹"], c: 0, e: "\\(C = C_m / M = 9{,}0 / 58{,}5 \\approx 0{,}154\\) mol·L⁻¹ (soit 154 mmol·L⁻¹). 6,5 correspond à M/C_m, 526 à C_m × M." },
  { d: 3, o: "3.1", q: "On dissout 0,020 mol de soluté dans de l’eau pour obtenir 250 mL de solution. Quelle est la concentration molaire ?", a: ["0,080 mol·L⁻¹", "0,0050 mol·L⁻¹", "12,5 mol·L⁻¹", "\\(8{,}0 \\times 10^{-5}\\) mol·L⁻¹"], c: 0, e: "\\(C = n/V = 0{,}020 / 0{,}250 = 0{,}080\\) mol·L⁻¹. Piège : diviser par 250 au lieu de 0,250 L (8,0 × 10⁻⁵) ou multiplier n par V (0,0050)." },
  { d: 3, o: "3.1", q: "Quelle est la concentration massique d’une solution de glucose à 0,10 mol·L⁻¹ (M = 180 g·mol⁻¹) ?", a: ["18 g·L⁻¹", "1 800 g·L⁻¹", "0,00056 g·L⁻¹", "1,8 g·L⁻¹"], c: 0, e: "\\(C_m = C \\times M = 0{,}10 \\times 180 = 18\\) g·L⁻¹." },
  { d: 3, o: "3.1", q: "À propos de la mole et du nombre d’Avogadro, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["\\(N_A\\) vaut environ \\(6{,}022 \\times 10^{23}\\) mol⁻¹", "Une mole de n’importe quelle espèce contient le même nombre d’entités", "Une mole de \\(\\ce{H2}\\) et une mole de \\(\\ce{O2}\\) ont la même masse", "\\(N_A\\) est le nombre d’atomes contenus dans 1 g de carbone 12", "\\(N_A\\) dépend de la température"], c: [0, 1], x: ["Valeur exacte depuis 2019 : 6,022 140 76 × 10²³ mol⁻¹.", "C’est la définition même de la mole.", "Même nombre de molécules mais masses différentes : 2 g et 32 g.", "C’est le nombre d’atomes dans 12 g de carbone 12.", "C’est une constante fondamentale."], e: "La mole compte des entités ; la masse molaire convertit ce nombre en masse." },
  { d: 3, o: "3.1", q: "Un patient reçoit en perfusion 500 mL de soluté glucosé à 5 % (50 g·L⁻¹). Quelle masse de glucose reçoit-il ?", a: ["25 g", "50 g", "2,5 g", "250 g"], c: 0, e: "\\(m = C_m \\times V = 50 \\times 0{,}500 = 25\\) g. Vérification de cohérence : un demi-litre contient la moitié de 50 g." },
  { d: 3, o: "3.1", q: "Une solution de chlorure de potassium KCl (M = 74,6 g·mol⁻¹) a une concentration massique de 7,46 g·L⁻¹. Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Sa concentration molaire est 0,100 mol·L⁻¹", "100 mL de cette solution contiennent 0,746 g de KCl", "Sa concentration molaire est 7,46 mol·L⁻¹", "1 L de solution contient 0,100 g de KCl", "La concentration en ions chlorure est 0,200 mol·L⁻¹"], c: [0, 1], x: ["7,46 / 74,6 = 0,100 mol·L⁻¹.", "7,46 × 0,100 = 0,746 g.", "Confusion entre concentration massique et molaire.", "1 L contient 7,46 g (0,100 mol).", "KCl libère un seul Cl⁻ : [Cl⁻] = 0,100 mol·L⁻¹."], e: "Relation clé : \\(C_m = C \\times M\\)." },
  { d: 3, o: "3.1", q: "Quelle quantité d’ions sodium contient un échantillon de 5,85 g de NaCl (M = 58,5 g·mol⁻¹) ?", a: ["0,100 mol", "0,200 mol", "10,0 mol", "0,0585 mol"], c: 0, e: "n(NaCl) = 5,85 / 58,5 = 0,100 mol ; chaque unité NaCl apporte un Na⁺ : 0,100 mol de Na⁺." },
  { d: 3, o: "3.1", q: "Quelle est la masse molaire du carbonate de calcium \\(\\ce{CaCO3}\\) ? (Ca = 40,1 ; C = 12,0 ; O = 16,0 g·mol⁻¹)", a: ["100,1 g·mol⁻¹", "68,1 g·mol⁻¹", "84,1 g·mol⁻¹", "116,1 g·mol⁻¹"], c: 0, e: "\\(40{,}1 + 12{,}0 + 3 \\times 16{,}0 = 100{,}1\\) g·mol⁻¹. 68,1 oublie l’indice 3 de l’oxygène." },

  // 3.2 Réactions chimiques
  { d: 3, o: "3.2", q: "Quel coefficient faut-il placer devant \\(\\ce{O2}\\) pour équilibrer \\(\\ce{C3H8 + ? O2 -> 3 CO2 + 4 H2O}\\) ?", a: ["5", "3", "7", "10"], c: 0, e: "Oxygène à droite : 3 × 2 + 4 × 1 = 10 atomes, donc 10 / 2 = 5 O₂. Le carbone (3) et l’hydrogène (8) sont déjà équilibrés." },
  { d: 3, o: "3.2", q: "Quels coefficients équilibrent \\(\\ce{a Al + b O2 -> c Al2O3}\\) ?", a: ["a = 4, b = 3, c = 2", "a = 2, b = 3, c = 1", "a = 2, b = 1, c = 1", "a = 4, b = 6, c = 2"], c: 0, e: "O : 2b = 3c → b = 3, c = 2 (plus petits entiers) ; Al : a = 2c = 4. Vérification : 4 Al et 6 O de chaque côté." },
  { d: 3, o: "3.2", q: "Pour \\(\\ce{N2 + 3 H2 -> 2 NH3}\\), on part de 2 mol de \\(\\ce{N2}\\) et 3 mol de \\(\\ce{H2}\\). Quel est le réactif limitant et quelle quantité d’ammoniac peut-on former au maximum ?", a: ["\\(\\ce{H2}\\) ; 2 mol de \\(\\ce{NH3}\\)", "\\(\\ce{N2}\\) ; 4 mol de \\(\\ce{NH3}\\)", "\\(\\ce{H2}\\) ; 6 mol de \\(\\ce{NH3}\\)", "\\(\\ce{N2}\\) ; 2 mol de \\(\\ce{NH3}\\)"], c: 0, e: "n₀/coefficient : N₂ 2/1 = 2 ; H₂ 3/3 = 1. H₂ est limitant, x_max = 1 mol, d’où 2 × 1 = 2 mol de NH₃. Piège : N₂ n’est pas limitant bien que sa quantité soit la plus petite." },
  { d: 3, o: "3.2", q: "Quelle quantité de dioxygène faut-il pour brûler complètement 2 mol de méthane selon \\(\\ce{CH4 + 2 O2 -> CO2 + 2 H2O}\\) ?", a: ["4 mol", "2 mol", "1 mol", "8 mol"], c: 0, e: "Les coefficients sont des rapports de moles : 1 mol de CH₄ consomme 2 mol de O₂, donc 2 mol en consomment 4." },
  { d: 3, o: "3.2", q: "Quelle masse de \\(\\ce{CO2}\\) (M = 44 g·mol⁻¹) produit la combustion complète de 16 g de méthane (M = 16 g·mol⁻¹) ?", a: ["44 g", "16 g", "22 g", "88 g"], c: 0, e: "n(CH₄) = 16 / 16 = 1,0 mol → 1,0 mol de CO₂ (coefficients 1 : 1) → m = 1,0 × 44 = 44 g. La masse n’est pas conservée espèce par espèce, seulement au total." },
  { d: 3, o: "3.2", q: "Lors d’une synthèse d’aspirine (M = 180 g·mol⁻¹), le réactif limitant permet d’obtenir au maximum 0,10 mol de produit. On récupère 14,4 g d’aspirine pure. Quel est le rendement ?", a: ["80 %", "72 %", "14,4 %", "125 %"], c: 0, e: "n obtenue = 14,4 / 180 = 0,080 mol ; η = 0,080 / 0,10 = 0,80, soit 80 %. Un rendement supérieur à 100 % signalerait une erreur (produit humide ou impur)." },
  { d: 3, o: "3.2", q: "Pour \\(\\ce{2 H2 + O2 -> 2 H2O}\\), on part de 4 mol de \\(\\ce{H2}\\) et 3 mol de \\(\\ce{O2}\\). Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["\\(\\ce{H2}\\) est le réactif limitant", "Il se forme 4 mol d’eau", "\\(\\ce{O2}\\) est le réactif limitant", "Il reste 1 mol de \\(\\ce{H2}\\) en fin de réaction", "Il reste 2 mol de \\(\\ce{O2}\\) en fin de réaction"], c: [0, 1], x: ["4/2 = 2 < 3/1 = 3 : x_max = 2 mol.", "2 × x_max = 4 mol.", "O₂ est en excès.", "Le réactif limitant est entièrement consommé : il n’en reste pas.", "Il en reste 3 − 2 = 1 mol."], e: "x_max = min(4/2 ; 3/1) = 2 mol ; on consomme 4 mol de H₂ et 2 mol de O₂." },
  { d: 3, o: "3.2", q: "À propos des coefficients stœchiométriques, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Ils indiquent les proportions des réactifs et produits en quantités de matière", "Ils assurent la conservation des éléments et des charges", "Ils indiquent les proportions en masse", "On peut modifier les indices des formules pour équilibrer une équation", "La somme des coefficients des réactifs est toujours égale à celle des produits"], c: [0, 1], x: ["Rapports de moles.", "C’est le but de l’équilibrage.", "Les masses dépendent aussi des masses molaires.", "Changer un indice change la molécule (H₂O ≠ H₂O₂).", "Exemple : CH₄ + 2 O₂ → CO₂ + 2 H₂O : 3 contre 3, mais N₂ + 3 H₂ → 2 NH₃ : 4 contre 2."], e: "On équilibre avec les coefficients, jamais avec les indices." },
  { d: 3, o: "3.2", q: "Pour \\(\\ce{Fe + S -> FeS}\\), on mélange 0,20 mol de fer et 0,15 mol de soufre. Que reste-t-il en fin de réaction ?", a: ["0,05 mol de fer", "0,05 mol de soufre", "0,15 mol de fer", "Rien, le mélange est stœchiométrique"], c: 0, e: "Coefficients 1 : 1 : S (0,15) est limitant, on consomme 0,15 mol de Fe et il reste 0,20 − 0,15 = 0,05 mol de fer, le réactif en excès." },
  { d: 3, o: "3.2", q: "L’oxydation complète du glucose s’écrit \\(\\ce{C6H12O6 + 6 O2 -> 6 CO2 + 6 H2O}\\). Quelle quantité de \\(\\ce{CO2}\\) produit l’oxydation de 0,50 mol de glucose ?", a: ["3,0 mol", "0,50 mol", "6,0 mol", "0,083 mol"], c: 0, e: "1 mol de glucose donne 6 mol de CO₂ : 0,50 × 6 = 3,0 mol." },
  { d: 3, o: "3.2", q: "Une estérification menée avec 1,0 mol d’acide et 1,0 mol d’alcool fournit 0,67 mol d’ester. Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Le rendement est de 67 %", "Le rendement d’une réaction ne peut pas dépasser 100 %", "L’ajout d’un catalyseur porterait le rendement à 100 %", "Le rendement se calcule par rapport au réactif en excès", "Ce rendement de 67 % prouve des pertes lors de la purification"], c: [0, 1], x: ["0,67 / 1,0 = 67 %.", "On ne peut pas obtenir plus que le maximum théorique.", "Un catalyseur accélère mais ne change pas l’état d’équilibre.", "On le calcule par rapport au réactif limitant.", "L’estérification est limitée par un équilibre : 67 % est la valeur attendue même sans perte."], e: "Rendement = quantité obtenue / quantité maximale calculée à partir du réactif limitant." },
  { d: 3, o: "3.2", q: "Pour \\(\\ce{2 NaOH + H2SO4 -> Na2SO4 + 2 H2O}\\), quelle quantité de soude faut-il pour réagir exactement avec 0,015 mol d’acide sulfurique ?", a: ["0,030 mol", "0,015 mol", "0,0075 mol", "0,060 mol"], c: 0, e: "Mélange stœchiométrique : n(NaOH)/2 = n(H₂SO₄)/1, donc n(NaOH) = 2 × 0,015 = 0,030 mol." },

  // 3.3 Solutions
  { d: 3, o: "3.3", q: "On prélève 5,0 mL d’une solution à 2,0 mol·L⁻¹ que l’on dilue dans une fiole jaugée de 100,0 mL. Quelle est la concentration de la solution obtenue ?", a: ["0,10 mol·L⁻¹", "0,40 mol·L⁻¹", "40 mol·L⁻¹", "0,010 mol·L⁻¹"], c: 0, e: "\\(C_1 = C_0 V_0 / V_1 = 2{,}0 \\times 5{,}0 / 100{,}0 = 0{,}10\\) mol·L⁻¹ (facteur de dilution 20)." },
  { d: 3, o: "3.3", q: "Quel volume d’une solution mère à 1,0 mol·L⁻¹ faut-il prélever pour préparer 250 mL d’une solution à 0,10 mol·L⁻¹ ?", a: ["25 mL", "2,5 mL", "250 mL", "10 mL"], c: 0, e: "\\(V_0 = C_1 V_1 / C_0 = 0{,}10 \\times 250 / 1{,}0 = 25\\) mL, puis on complète à 250 mL." },
  { d: 3, o: "3.3", q: "On ajoute 90 mL d’eau à 10 mL d’une solution. Quel est le facteur de dilution ?", a: ["10", "9", "0,1", "90"], c: 0, e: "F = V_final / V_prélevé = (10 + 90) / 10 = 10. Piège : prendre le volume d’eau ajouté (90 mL) au lieu du volume final (100 mL)." },
  { d: 3, o: "3.3", q: "Quelle masse de glucose (M = 180 g·mol⁻¹) faut-il peser pour préparer 500 mL d’une solution à 0,20 mol·L⁻¹ ?", a: ["18 g", "36 g", "0,10 g", "180 g"], c: 0, e: "n = C × V = 0,20 × 0,500 = 0,10 mol ; m = n × M = 0,10 × 180 = 18 g. On dissout dans une fiole jaugée de 500 mL et on complète au trait de jauge." },
  { d: 3, o: "3.3", q: "On mélange 200 mL de NaCl à 0,30 mol·L⁻¹ et 200 mL de NaCl à 0,10 mol·L⁻¹. Quelle est la concentration finale en NaCl ?", a: ["0,20 mol·L⁻¹", "0,40 mol·L⁻¹", "0,10 mol·L⁻¹", "0,080 mol·L⁻¹"], c: 0, e: "\\(C = \\dfrac{0{,}30 \\times 0{,}200 + 0{,}10 \\times 0{,}200}{0{,}400} = \\dfrac{0{,}080}{0{,}400} = 0{,}20\\) mol·L⁻¹. Cohérence : la valeur est entre 0,10 et 0,30 ; on n’additionne pas les concentrations." },
  { d: 3, o: "3.3", q: "On dispose d’une solution de sulfate de sodium \\(\\ce{Na2SO4}\\) à 0,10 mol·L⁻¹. Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["\\([\\ce{Na+}] = 0{,}20\\) mol·L⁻¹", "\\([\\ce{SO4^2-}] = 0{,}10\\) mol·L⁻¹", "\\([\\ce{Na+}] = 0{,}10\\) mol·L⁻¹", "La concentration totale en ions vaut 0,20 mol·L⁻¹", "La solution n’est pas électriquement neutre"], c: [0, 1], x: ["Na₂SO₄ → 2 Na⁺ + SO₄²⁻.", "Un ion sulfate par unité.", "Il faut tenir compte de l’indice 2.", "0,20 + 0,10 = 0,30 mol·L⁻¹.", "0,20 × (+1) + 0,10 × (−2) = 0 : neutre."], e: "Les concentrations des ions suivent les indices de la formule du solide ionique." },
  { d: 3, o: "3.3", q: "À propos de la dilution, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["La quantité de matière de soluté se conserve", "On peut écrire \\(C_0 V_0 = C_1 V_1\\)", "La solution fille est plus concentrée que la solution mère", "On prélève la solution mère à l’éprouvette graduée pour une précision maximale", "Le facteur de dilution vaut \\(V_0 / V_1\\)"], c: [0, 1], x: ["On ajoute seulement du solvant.", "Conséquence directe de la conservation.", "Elle est moins concentrée.", "On utilise une pipette jaugée, plus précise.", "F = V₁ / V₀ = C₀ / C₁ (supérieur à 1)."], e: "Dilution : n conservée, concentration divisée par F = V₁/V₀." },
  { d: 3, o: "3.3", q: "On mélange 50 mL de NaCl à 0,20 mol·L⁻¹ et 50 mL de KCl à 0,40 mol·L⁻¹. Quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["\\([\\ce{Na+}] = 0{,}10\\) mol·L⁻¹", "\\([\\ce{K+}] = 0{,}20\\) mol·L⁻¹", "\\([\\ce{Cl-}] = 0{,}60\\) mol·L⁻¹", "\\([\\ce{Cl-}] = 0{,}30\\) mol·L⁻¹", "\\([\\ce{Na+}] = 0{,}20\\) mol·L⁻¹"], c: [0, 1, 3], x: ["0,20 × 50 / 100 = 0,10.", "0,40 × 50 / 100 = 0,20.", "On n’additionne pas des concentrations.", "(0,010 + 0,020) mol / 0,100 L = 0,30.", "Na⁺ est dilué 2 fois dans le volume total."], e: "Sans réaction, chaque ion est dilué dans le volume total ; pour un ion commun, on additionne les quantités de matière." },
  { d: 3, o: "3.3", q: "Une eau oxygénée contient 30 % en masse de \\(\\ce{H2O2}\\) (M = 34 g·mol⁻¹) et a une masse volumique de 1,11 kg·L⁻¹. Quelle est sa concentration molaire ?", a: ["9,8 mol·L⁻¹", "8,8 mol·L⁻¹", "0,98 mol·L⁻¹", "333 mol·L⁻¹"], c: 0, e: "\\(C_m = w \\times \\rho = 0{,}30 \\times 1\\,110 = 333\\) g·L⁻¹ ; \\(C = 333 / 34 \\approx 9{,}8\\) mol·L⁻¹. 8,8 oublie la masse volumique (1 000 au lieu de 1 110 g·L⁻¹) ; 333 est la concentration massique." },
  { d: 3, o: "3.3", q: "Une infirmière doit préparer 100 mL d’une solution à 0,5 mg·mL⁻¹ à partir d’une solution à 10 mg·mL⁻¹. Quel volume de solution concentrée doit-elle prélever ?", a: ["5 mL", "2 mL", "20 mL", "50 mL"], c: 0, e: "\\(V_0 = C_1 V_1 / C_0 = 0{,}5 \\times 100 / 10 = 5\\) mL, à compléter à 100 mL. Facteur de dilution 20." },

  // 3.4 Méthodes
  { d: 3, o: "3.4", q: "Conversion d’unités : à combien de moles correspondent 250 µmol ?", a: ["\\(2{,}5 \\times 10^{-4}\\) mol", "\\(2{,}5 \\times 10^{-1}\\) mol", "\\(2{,}5 \\times 10^{-7}\\) mol", "\\(2{,}5 \\times 10^{8}\\) mol"], c: 0, e: "1 µmol = 10⁻⁶ mol : 250 × 10⁻⁶ = 2,5 × 10² × 10⁻⁶ = 2,5 × 10⁻⁴ mol." },
  { d: 3, o: "3.4", q: "Manipulation des puissances de 10 : combien vaut \\((3 \\times 10^{-4}) \\times (2 \\times 10^{6})\\) ?", a: ["\\(6 \\times 10^{2}\\)", "\\(6 \\times 10^{-24}\\)", "\\(5 \\times 10^{2}\\)", "\\(6 \\times 10^{10}\\)"], c: 0, e: "On multiplie les mantisses (3 × 2 = 6) et on additionne les exposants (−4 + 6 = 2) : 6 × 10²." },
  { d: 3, o: "3.4", q: "Lecture de graphiques : une droite d’étalonnage passant par l’origine donne une absorbance de 0,50 pour une concentration de 2,0 mmol·L⁻¹. Une solution inconnue a une absorbance de 0,75. Quelle est sa concentration ?", a: ["3,0 mmol·L⁻¹", "1,5 mmol·L⁻¹", "2,75 mmol·L⁻¹", "0,375 mmol·L⁻¹"], c: 0, e: "Droite passant par l’origine : absorbance proportionnelle à C, de pente 0,50 / 2,0 = 0,25 L·mmol⁻¹. Résolution d’équation : C = 0,75 / 0,25 = 3,0 mmol·L⁻¹." },
  { d: 3, o: "3.4", q: "Analyse dimensionnelle : quelle expression donne une quantité de matière (en mol) ?", a: ["C (mol·L⁻¹) × V (L)", "m (g) × M (g·mol⁻¹)", "V (L) / C (mol·L⁻¹)", "M (g·mol⁻¹) / m (g)"], c: 0, e: "mol·L⁻¹ × L = mol. Les autres donnent g²·mol⁻¹, L²·mol⁻¹ et mol⁻¹ : l’analyse des unités suffit à éliminer une formule fausse." },
  { d: 3, o: "3.4", q: "Ordres de grandeur : une glycémie de 5,0 mmol·L⁻¹ correspond à quelle concentration massique ? (M(glucose) = 180 g·mol⁻¹)", a: ["0,90 g·L⁻¹", "9,0 g·L⁻¹", "0,028 g·L⁻¹", "900 g·L⁻¹"], c: 0, e: "\\(C_m = 5{,}0 \\times 10^{-3} \\times 180 = 0{,}90\\) g·L⁻¹, valeur normale d’une glycémie à jeun. 900 correspond à une confusion entre mmol et mol." },
  { d: 3, o: "3.4", q: "Vérification de cohérence d’un résultat : après avoir dilué une solution à 0,50 mol·L⁻¹, un étudiant trouve une concentration de 2,5 mol·L⁻¹. Que faut-il conclure ?", a: ["Le calcul est faux : une solution diluée ne peut pas être plus concentrée que la solution mère", "Le résultat est correct si le facteur de dilution vaut 5", "Le résultat est correct si l’on a ajouté beaucoup d’eau", "On ne peut rien conclure sans connaître le soluté"], c: 0, e: "Une dilution divise toujours la concentration. L’étudiant a probablement multiplié par le facteur de dilution (0,50 × 5) au lieu de diviser (0,50 / 5 = 0,10 mol·L⁻¹)." },
  { d: 3, o: "3.4", q: "Calculs logarithmiques : quelles égalités sont exactes ? (Choisissez 3 réponses)", a: ["\\(\\log(2 \\times 10^{-3}) \\approx -2{,}7\\)", "\\(\\log 1\\,000 = 3\\)", "\\(\\ln 2 \\approx 0{,}693\\)", "\\(\\log(a + b) = \\log a + \\log b\\)", "\\(\\log 0{,}01 = 2\\)"], c: [0, 1, 2], x: ["log 2 + log 10⁻³ ≈ 0,30 − 3 = −2,7.", "10³ = 1 000.", "Valeur utile pour les demi-vies.", "C’est log(a × b) qui vaut log a + log b.", "log 10⁻² = −2."], e: "log(ab) = log a + log b ; log 10ⁿ = n ; log 2 ≈ 0,30 ; ln 2 ≈ 0,693." },
  { d: 3, o: "3.4", q: "Interprétation de tableaux : on relève la concentration plasmatique d’un médicament : t = 0 h : 40 mg·L⁻¹ ; 2 h : 20 ; 4 h : 10 ; 6 h : 5. Quelle conclusion est correcte ?", a: ["La concentration est divisée par 2 toutes les 2 heures", "La concentration diminue de 10 mg·L⁻¹ par heure", "La concentration diminue linéairement avec le temps", "La concentration sera nulle à 8 h"], c: 0, e: "40 → 20 → 10 → 5 : rapport constant de ½ toutes les 2 h (décroissance exponentielle, demi-vie de 2 h). La baisse n’est pas constante en valeur absolue (−20, −10, −5) ; à 8 h il restera 2,5 mg·L⁻¹." },
  { d: 3, o: "3.4", q: "Conversions d’unités et calculs de concentrations : quelles égalités sont exactes ? (Choisissez 2 réponses)", a: ["1 mg·mL⁻¹ = 1 g·L⁻¹", "1 mmol·L⁻¹ = \\(10^{-3}\\) mol·L⁻¹", "1 L = 1 m³", "1 µmol = \\(10^{-3}\\) mol", "1 g·L⁻¹ = 10 mg·dL⁻¹"], c: [0, 1], x: ["On multiplie numérateur et dénominateur par 1 000.", "Préfixe milli = 10⁻³.", "1 L = 1 dm³ = 10⁻³ m³.", "1 µmol = 10⁻⁶ mol.", "1 g·L⁻¹ = 1 000 mg / 10 dL = 100 mg·dL⁻¹."], e: "Écrire les unités et convertir numérateur et dénominateur séparément évite la plupart des erreurs." },

  // ===================== Domaine 4 — Thermodynamique (42) =====================
  // 4.1 Notions fondamentales
  { d: 4, o: "4.1", q: "Un tube scellé contenant une solution est chauffé au bain-marie. Quel type de système constitue le contenu du tube ?", a: ["Un système fermé", "Un système isolé", "Un système ouvert", "Un système sans état thermodynamique défini"], c: 0, e: "Le tube scellé n’échange pas de matière mais reçoit de la chaleur : système fermé. Un système isolé n’échange ni matière ni énergie." },
  { d: 4, o: "4.1", q: "Une cellule vivante, qui absorbe des nutriments, rejette des déchets et dégage de la chaleur, est un système :", a: ["Ouvert", "Fermé", "Isolé", "Adiabatique"], c: 0, e: "Elle échange à la fois de la matière et de l’énergie avec son milieu : système ouvert." },
  { d: 4, o: "4.1", q: "Parmi ces variables d’état, laquelle est intensive ?", a: ["La température", "Le volume", "La masse", "La quantité de matière"], c: 0, e: "Une grandeur intensive ne dépend pas de la taille du système : réunir deux systèmes à 37 °C donne un système à 37 °C, mais de volume, masse et quantité de matière doublés (grandeurs extensives)." },
  { d: 4, o: "4.1", q: "Quelle est la température corporelle de 37 °C exprimée en kelvins ?", a: ["310 K", "236 K", "37 K", "273 K"], c: 0, e: "T(K) = θ(°C) + 273,15 = 310,15 K ≈ 310 K. Toutes les formules thermodynamiques (PV = nRT, ΔG = ΔH − TΔS) exigent des kelvins." },
  { d: 4, o: "4.1", q: "Laquelle de ces grandeurs n’est pas une fonction d’état ?", a: ["Le travail W", "L’énergie interne U", "L’enthalpie H", "L’entropie S"], c: 0, e: "Le travail et la chaleur dépendent du chemin suivi : ce sont des modes de transfert, pas des propriétés de l’état du système. U, H, S (et G) sont des fonctions d’état." },
  { d: 4, o: "4.1", q: "Quel volume occupe 1,0 mol de gaz parfait à 273 K sous une pression de \\(1{,}013 \\times 10^5\\) Pa ? (R = 8,314 J·mol⁻¹·K⁻¹)", a: ["22,4 L", "2,24 L", "224 L", "0,0224 L"], c: 0, e: "\\(V = nRT/P = 1{,}0 \\times 8{,}314 \\times 273 / 1{,}013 \\times 10^5 = 0{,}0224\\) m³ = 22,4 L. Piège d’unités : le résultat de la formule est en m³ (0,0224), pas en litres." },
  { d: 4, o: "4.1", q: "À propos des variables d’état, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["La pression et le volume sont des variables d’état", "Le volume est une grandeur extensive", "La température est une grandeur extensive", "En réunissant deux systèmes identiques à 300 K, on obtient un système à 600 K", "La variation d’une fonction d’état dépend du chemin suivi"], c: [0, 1], x: ["Avec T et n, elles décrivent l’état thermodynamique.", "Il double quand on double le système.", "Elle est intensive.", "La température reste 300 K : grandeur intensive.", "Elle ne dépend que des états initial et final."], e: "L’état thermodynamique est fixé par quelques variables d’état (T, P, V, n) ; les fonctions d’état ne dépendent que de cet état." },
  { d: 4, o: "4.1", q: "À propos des transformations et des systèmes, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Une transformation isobare se fait à pression constante", "Une transformation adiabatique se fait sans échange de chaleur", "Une transformation isochore se fait à température constante", "Un système isolé échange de l’énergie mais pas de matière", "Un système ouvert ne peut échanger que de la matière"], c: [0, 1], x: ["Iso-bare : même pression.", "Q = 0.", "Isochore = volume constant ; à température constante, c’est isotherme.", "Un système isolé n’échange rien ; celui qui échange seulement de l’énergie est fermé.", "Il échange matière et énergie."], e: "Isotherme (T), isobare (P), isochore (V), adiabatique (Q = 0)." },

  // 4.2 Énergie
  { d: 4, o: "4.2", q: "Comment s’écrit le premier principe de la thermodynamique pour un système fermé ?", a: ["\\(\\Delta U = W + Q\\)", "\\(\\Delta U = W - Q\\)", "\\(\\Delta H = W + Q\\) dans tous les cas", "\\(\\Delta U = 0\\) dans tous les cas"], c: 0, e: "Avec la convention « reçu = positif », la variation d’énergie interne est la somme du travail et de la chaleur reçus. ΔU = 0 seulement pour un système isolé." },
  { d: 4, o: "4.2", q: "Un système reçoit 200 J de chaleur et fournit 50 J de travail au milieu extérieur. Quelle est la variation de son énergie interne ?", a: ["+150 J", "+250 J", "−150 J", "−250 J"], c: 0, e: "Q = +200 J (reçue) ; W = −50 J (fourni). ΔU = W + Q = −50 + 200 = +150 J." },
  { d: 4, o: "4.2", q: "Pour une transformation à pression constante, à quoi est égale la chaleur échangée ?", a: ["À la variation d’enthalpie \\(\\Delta H\\)", "À la variation d’énergie interne \\(\\Delta U\\)", "Au travail W", "À la variation d’entropie \\(\\Delta S\\)"], c: 0, e: "Par définition H = U + PV, d’où Q_P = ΔH à pression constante. À volume constant, c’est Q_V = ΔU." },
  { d: 4, o: "4.2", q: "Quelle chaleur faut-il fournir pour réchauffer 100 g d’eau de 10 °C ? (c = 4,18 J·g⁻¹·K⁻¹)", a: ["4,18 kJ", "418 J", "41,8 kJ", "0,418 J"], c: 0, e: "\\(Q = m\\,c\\,\\Delta T = 100 \\times 4{,}18 \\times 10 = 4\\,180\\) J = 4,18 kJ. Un écart de 10 °C vaut 10 K." },
  { d: 4, o: "4.2", q: "Un gaz se détend de 1,0 L à 3,0 L contre une pression extérieure constante de \\(1{,}0 \\times 10^5\\) Pa. Quel est le travail reçu par le gaz ?", a: ["−200 J", "+200 J", "−2,0 × 10⁵ J", "−300 J"], c: 0, e: "\\(W = -P_{ext}\\,\\Delta V = -1{,}0 \\times 10^5 \\times 2{,}0 \\times 10^{-3} = -200\\) J. Négatif : le gaz fournit du travail. Ne pas oublier de convertir les litres en m³." },
  { d: 4, o: "4.2", q: "Quelle est la définition de l’enthalpie ?", a: ["\\(H = U + PV\\)", "\\(H = U - TS\\)", "\\(H = G + PV\\)", "\\(H = Q + W\\)"], c: 0, e: "H = U + PV. U − TS est l’énergie libre de Helmholtz (hors programme) ; G = H − TS est l’énergie libre de Gibbs." },
  { d: 4, o: "4.2", q: "Que vaut la variation d’énergie interne d’un système isolé ?", a: ["0", "Elle est toujours positive", "Elle est égale à Q", "Elle est égale à −W"], c: 0, e: "Un système isolé n’échange ni travail ni chaleur : W = Q = 0 donc ΔU = 0. Son énergie interne se conserve." },
  { d: 4, o: "4.2", q: "À propos des conventions de signe et des échanges d’énergie, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Une chaleur reçue par le système est comptée positivement", "Un gaz qui se détend contre l’extérieur reçoit un travail négatif", "Le travail est une fonction d’état", "À volume constant, \\(\\Delta U = Q_P\\)", "L’énergie interne d’un système isolé augmente toujours"], c: [0, 1], x: ["Convention « du banquier ».", "ΔV > 0 donc W = −P ΔV < 0 : il fournit du travail.", "Il dépend du chemin suivi.", "À volume constant, ΔU = Q_V.", "Elle est constante."], e: "Reçu : positif ; fourni : négatif. W et Q dépendent du chemin, U et H non." },
  { d: 4, o: "4.2", q: "À propos de l’énergie interne et de l’enthalpie, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["\\(\\Delta U = Q_V\\) pour une transformation à volume constant", "\\(\\Delta H = \\Delta U + \\Delta n_{gaz} RT\\) pour une réaction mettant en jeu des gaz parfaits", "Pour une réaction ne faisant intervenir que des solides et des liquides, ΔH et ΔU sont très différents", "L’enthalpie ne dépend jamais de la composition du système", "La chaleur échangée est toujours égale à ΔU"], c: [0, 1], x: ["Pas de travail des forces de pression.", "Le terme PV varie surtout avec les gaz.", "Les volumes varient très peu : ΔH ≈ ΔU.", "Elle dépend de la nature et de la quantité des espèces présentes.", "Seulement à volume constant."], e: "L’écart entre ΔH et ΔU vient du travail des forces de pression, notable surtout quand le nombre de moles de gaz change." },
  { d: 4, o: "4.2", q: "Pour la réaction \\(\\ce{C(gr) + O2(g) -> CO2(g)}\\), que peut-on dire de \\(\\Delta_r H\\) et \\(\\Delta_r U\\) ?", a: ["Ils sont égaux, car le nombre de moles de gaz ne varie pas", "\\(\\Delta_r H\\) est bien supérieur à \\(\\Delta_r U\\)", "\\(\\Delta_r H\\) est bien inférieur à \\(\\Delta_r U\\)", "On ne peut pas les comparer"], c: 0, e: "Δn_gaz = 1 − 1 = 0, donc ΔH = ΔU + 0 × RT = ΔU (le carbone solide ne compte pas)." },

  // 4.3 Réactions chimiques
  { d: 4, o: "4.3", q: "Une réaction est dite exothermique lorsque :", a: ["\\(\\Delta_r H \\lt 0\\) : elle libère de la chaleur", "\\(\\Delta_r H \\gt 0\\) : elle absorbe de la chaleur", "\\(\\Delta_r G \\lt 0\\) : elle est spontanée", "\\(\\Delta_r S \\gt 0\\) : le désordre augmente"], c: 0, e: "Exothermique : l’enthalpie du système diminue et la chaleur est cédée à l’extérieur (ΔrH < 0). Ne pas confondre avec exergonique (ΔrG < 0)." },
  { d: 4, o: "4.3", q: "Parmi ces transformations, laquelle est endothermique ?", a: ["La fusion de la glace", "La combustion du glucose", "La neutralisation de HCl par NaOH", "La condensation de la vapeur d’eau"], c: 0, e: "Il faut fournir de la chaleur pour rompre les liaisons hydrogène du solide : fusion endothermique (ΔH ≈ +6 kJ·mol⁻¹). Combustion, neutralisation et condensation libèrent de la chaleur." },
  { d: 4, o: "4.3", q: "Que vaut l’enthalpie standard de formation du dioxygène gazeux \\(\\ce{O2(g)}\\) ?", a: ["0 kJ·mol⁻¹", "−249 kJ·mol⁻¹", "+498 kJ·mol⁻¹", "Elle dépend de la réaction étudiée"], c: 0, e: "Par convention, l’enthalpie standard de formation d’un corps simple dans son état standard de référence est nulle (O₂(g), H₂(g), N₂(g), C graphite)." },
  { d: 4, o: "4.3", q: "La réaction A → B a une enthalpie \\(\\Delta_r H = -50\\) kJ·mol⁻¹. Que vaut l’enthalpie de la réaction B → A ?", a: ["+50 kJ·mol⁻¹", "−50 kJ·mol⁻¹", "0 kJ·mol⁻¹", "−100 kJ·mol⁻¹"], c: 0, e: "Inverser une réaction change le signe de son enthalpie de réaction : si A → B libère 50 kJ, B → A en absorbe 50." },
  { d: 4, o: "4.3", q: "Calculez \\(\\Delta_r H°\\) de \\(\\ce{C2H5OH(l) + 3 O2(g) -> 2 CO2(g) + 3 H2O(l)}\\), sachant que \\(\\Delta_f H°\\) vaut −277,7 (éthanol), −393,5 (\\(\\ce{CO2}\\)) et −285,8 (\\(\\ce{H2O(l)}\\)) kJ·mol⁻¹.", a: ["−1 367 kJ·mol⁻¹", "−1 922 kJ·mol⁻¹", "−402 kJ·mol⁻¹", "+1 367 kJ·mol⁻¹"], c: 0, e: "\\(\\Delta_r H° = [2(-393{,}5) + 3(-285{,}8)] - [-277{,}7 + 0] = -1\\,644{,}4 + 277{,}7 = -1\\,366{,}7\\) kJ·mol⁻¹. −1 922 : on a ajouté au lieu de soustraire l’éthanol ; −402 : on a oublié les coefficients." },
  { d: 4, o: "4.3", q: "Sachant que \\(\\ce{H2 + 1/2 O2 -> H2O(l)}\\) a \\(\\Delta_r H° = -285{,}8\\) kJ·mol⁻¹, que vaut \\(\\Delta_r H°\\) pour \\(\\ce{2 H2O(l) -> 2 H2 + O2}\\) ?", a: ["+571,6 kJ·mol⁻¹", "−571,6 kJ·mol⁻¹", "+285,8 kJ·mol⁻¹", "−142,9 kJ·mol⁻¹"], c: 0, e: "On inverse (changement de signe : +285,8) et on multiplie par 2 : +571,6 kJ·mol⁻¹. L’électrolyse de l’eau est fortement endothermique." },
  { d: 4, o: "4.3", q: "À l’aide des énergies de liaison E(C–H) = 413, E(Cl–Cl) = 243, E(C–Cl) = 339 et E(H–Cl) = 432 kJ·mol⁻¹, estimez \\(\\Delta_r H\\) de \\(\\ce{CH4 + Cl2 -> CH3Cl + HCl}\\).", a: ["−115 kJ·mol⁻¹", "+115 kJ·mol⁻¹", "−656 kJ·mol⁻¹", "−1 427 kJ·mol⁻¹"], c: 0, e: "Liaisons rompues : C–H + Cl–Cl = 413 + 243 = 656. Liaisons formées : C–Cl + H–Cl = 339 + 432 = 771. ΔH ≈ 656 − 771 = −115 kJ·mol⁻¹. Inverser l’ordre donne +115." },
  { d: 4, o: "4.3", q: "On donne : \\(\\ce{C(gr) + O2 -> CO2}\\) (−393,5) ; \\(\\ce{H2 + 1/2 O2 -> H2O(l)}\\) (−285,8) ; \\(\\ce{CH4 + 2 O2 -> CO2 + 2 H2O(l)}\\) (−890,3), en kJ·mol⁻¹. Que vaut \\(\\Delta_f H°(\\ce{CH4})\\) ?", a: ["−74,8 kJ·mol⁻¹", "−1 855,4 kJ·mol⁻¹", "+74,8 kJ·mol⁻¹", "+211,0 kJ·mol⁻¹"], c: 0, e: "Loi de Hess : C + 2 H₂ → CH₄ = (1) + 2 × (2) − (3). ΔfH° = −393,5 + 2(−285,8) − (−890,3) = −393,5 − 571,6 + 890,3 = −74,8 kJ·mol⁻¹." },
  { d: 4, o: "4.3", q: "En mélangeant de l’acide chlorhydrique et de la soude, un étudiant constate que le bécher chauffe. Que peut-on en conclure ?", a: ["La réaction est exothermique : \\(\\Delta_r H \\lt 0\\)", "La réaction est endothermique : \\(\\Delta_r H \\gt 0\\)", "La réaction est athermique", "La réaction absorbe la chaleur du milieu extérieur"], c: 0, e: "La chaleur libérée par la réaction (≈ −57 kJ par mole d’eau formée) réchauffe la solution : réaction exothermique." },
  { d: 4, o: "4.3", q: "À propos des enthalpies standard de formation, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["\\(\\Delta_f H°(\\ce{H2(g)}) = 0\\)", "\\(\\Delta_f H°(\\text{C graphite}) = 0\\)", "\\(\\Delta_f H°(\\ce{H2O(l)}) = 0\\) car l’eau est un corps pur", "\\(\\Delta_f H°(\\ce{O3(g)}) = 0\\)", "\\(\\Delta_f H°(\\ce{H2O(l)})\\) et \\(\\Delta_f H°(\\ce{H2O(g)})\\) sont égales"], c: [0, 1], x: ["Corps simple dans son état standard.", "C’est la forme de référence du carbone.", "L’eau est un corps composé, formé à partir de H₂ et O₂ (−285,8).", "L’ozone n’est pas la forme de référence de l’oxygène.", "−285,8 contre −241,8 kJ·mol⁻¹ : l’état physique compte."], e: "Seuls les corps simples dans leur état standard de référence ont une enthalpie de formation nulle." },
  { d: 4, o: "4.3", q: "À propos de la loi de Hess, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Elle découle du fait que l’enthalpie est une fonction d’état", "Si l’on multiplie une équation par 2, son \\(\\Delta_r H\\) est multiplié par 2", "Inverser une équation ne change pas son \\(\\Delta_r H\\)", "Elle ne s’applique qu’aux réactions exothermiques", "\\(\\Delta_r H\\) dépend des étapes intermédiaires choisies"], c: [0, 1], x: ["ΔH ne dépend que des états initial et final.", "ΔrH est une grandeur extensive rapportée à l’équation écrite.", "Il change de signe.", "Elle s’applique à toute réaction.", "C’est précisément ce que la loi de Hess exclut."], e: "Combiner des équations : on combine leurs ΔrH de la même manière (somme, signe, coefficient)." },
  { d: 4, o: "4.3", q: "Une poche de froid instantané contient du nitrate d’ammonium qui se dissout dans l’eau quand on la presse. Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["La dissolution est endothermique", "L’enthalpie de dissolution est positive", "La poche cède de la chaleur à la peau", "La dissolution est exothermique", "La température de la solution augmente"], c: [0, 1], x: ["Elle absorbe de la chaleur.", "ΔH > 0 pour une transformation endothermique.", "Elle prend de la chaleur à la peau, d’où la sensation de froid.", "Elle serait alors une poche chaude.", "Elle diminue : la chaleur absorbée est prise à la solution elle-même."], e: "Endothermique : ΔH > 0, la chaleur est prélevée au milieu (solution, peau)." },

  // 4.4 Spontanéité
  { d: 4, o: "4.4", q: "Quel est le signe de \\(\\Delta_r S\\) pour \\(\\ce{CaCO3(s) -> CaO(s) + CO2(g)}\\) ?", a: ["Positif", "Négatif", "Nul", "Impossible à prévoir"], c: 0, e: "La réaction forme un gaz à partir d’un solide : le désordre augmente fortement, ΔrS > 0 (+161 J·K⁻¹·mol⁻¹)." },
  { d: 4, o: "4.4", q: "À température et pression constantes, une réaction est spontanée dans le sens écrit si :", a: ["\\(\\Delta_r G \\lt 0\\)", "\\(\\Delta_r H \\lt 0\\)", "\\(\\Delta_r S \\lt 0\\)", "\\(\\Delta_r G \\gt 0\\)"], c: 0, e: "Le critère de spontanéité est le signe de ΔrG. Le signe de ΔrH seul ne suffit pas : une réaction exothermique peut être non spontanée si son entropie diminue beaucoup." },
  { d: 4, o: "4.4", q: "Une réaction a \\(\\Delta_r H = -100\\) kJ·mol⁻¹ et \\(\\Delta_r S = -200\\) J·K⁻¹·mol⁻¹. Que vaut \\(\\Delta_r G\\) à 298 K ?", a: ["−40,4 kJ·mol⁻¹", "−159,6 kJ·mol⁻¹", "+40,4 kJ·mol⁻¹", "+59 500 kJ·mol⁻¹"], c: 0, e: "\\(\\Delta_r G = -100 - 298 \\times (-0{,}200) = -100 + 59{,}6 = -40{,}4\\) kJ·mol⁻¹ : spontanée à 298 K. +59 500 : oubli de conversion des J en kJ ; −159,6 : erreur de signe." },
  { d: 4, o: "4.4", q: "Une réaction a \\(\\Delta_r H = +40\\) kJ·mol⁻¹ et \\(\\Delta_r S = +100\\) J·K⁻¹·mol⁻¹ (supposés constants). À partir de quelle température devient-elle spontanée ?", a: ["Au-dessus de 400 K", "En dessous de 400 K", "Au-dessus de 0,4 K", "À toute température"], c: 0, e: "ΔrG < 0 si T > ΔH / ΔS = 40 000 / 100 = 400 K. ΔH > 0 et ΔS > 0 : spontanée à haute température." },
  { d: 4, o: "4.4", q: "L’entropie molaire standard du dioxygène gazeux vaut 205 J·K⁻¹·mol⁻¹. Pourquoi n’est-elle pas nulle, contrairement à son enthalpie de formation ?", a: ["Les entropies sont absolues : seule celle d’un cristal parfait à 0 K est nulle", "C’est une erreur : l’entropie d’un corps simple est toujours nulle", "Parce que le dioxygène est un composé ionique", "Parce que l’entropie d’un gaz est toujours négative"], c: 0, e: "Le troisième principe fixe l’origine des entropies (S = 0 pour un cristal parfait à 0 K) : les S° sont des valeurs absolues positives. Les ΔfH° sont des grandeurs relatives, nulles par convention pour les corps simples." },
  { d: 4, o: "4.4", q: "Une réaction a \\(\\Delta_r H \\lt 0\\) et \\(\\Delta_r S \\lt 0\\). Quand est-elle spontanée ?", a: ["À basse température", "À haute température", "À toute température", "Jamais"], c: 0, e: "ΔG = ΔH − TΔS : le terme −TΔS est positif et grandit avec T. La réaction est spontanée tant que T < ΔH/ΔS, c’est-à-dire à basse température." },
  { d: 4, o: "4.4", q: "Une réaction a une constante d’équilibre K = 1 000 à 298 K. Quel est le signe de \\(\\Delta_r G°\\) ?", a: ["Négatif", "Positif", "Nul", "Il dépend des concentrations initiales"], c: 0, e: "ΔrG° = −RT ln K ; ln 1 000 > 0 donc ΔrG° < 0. ΔrG° ne dépend pas des concentrations (c’est ΔrG qui en dépend, via Q)." },
  { d: 4, o: "4.4", q: "La transformation du diamant en graphite a un \\(\\Delta_r G° \\lt 0\\), et pourtant les diamants ne se transforment pas. Pourquoi ?", a: ["La réaction est spontanée mais extrêmement lente", "Le \\(\\Delta_r G°\\) positif l’interdit", "La réaction est à l’équilibre", "La réaction est endothermique donc impossible"], c: 0, e: "La thermodynamique dit si une réaction est possible, la cinétique dit à quelle vitesse. Spontané ne veut pas dire rapide : l’énergie d’activation est ici énorme." },
  { d: 4, o: "4.4", q: "À propos de l’entropie, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Pour un même corps, S(gaz) > S(liquide) > S(solide)", "L’entropie d’un corps augmente avec la température", "La vaporisation de l’eau s’accompagne d’une augmentation d’entropie", "L’entropie molaire standard d’un corps simple est nulle", "Une réaction qui diminue le nombre de moles de gaz a en général \\(\\Delta_r S \\gt 0\\)"], c: [0, 1, 2], x: ["Le désordre augmente du solide au gaz.", "L’agitation thermique augmente.", "Liquide → gaz : ΔS > 0.", "C’est l’enthalpie de formation qui est nulle ; S° est absolue et positive.", "Elle a en général ΔrS < 0."], e: "L’entropie mesure le nombre de micro-états accessibles : elle augmente avec T et avec le passage à l’état gazeux." },
  { d: 4, o: "4.4", q: "À propos des critères de spontanéité, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Si ΔH < 0 et ΔS > 0, la réaction est spontanée à toute température", "Si ΔH > 0 et ΔS < 0, la réaction n’est spontanée à aucune température", "Une réaction endothermique n’est jamais spontanée", "Si ΔrG = 0, plus aucune réaction ne se produit", "Une réaction spontanée est forcément rapide"], c: [0, 1], x: ["ΔG = ΔH − TΔS est alors toujours négatif.", "ΔG toujours positif.", "Elle l’est si TΔS > ΔH (fusion de la glace au-dessus de 0 °C).", "ΔrG = 0 : équilibre dynamique, les réactions directe et inverse continuent à la même vitesse.", "La vitesse relève de la cinétique."], e: "Le signe de ΔG = ΔH − TΔS dépend de la compétition entre ΔH et TΔS." },
  { d: 4, o: "4.4", q: "La phosphorylation du glucose (glucose + phosphate → glucose-6-phosphate) a \\(\\Delta G°' = +13{,}8\\) kJ·mol⁻¹. Couplée à l’hydrolyse de l’ATP (\\(\\Delta G°' = -30{,}5\\) kJ·mol⁻¹), quel est le \\(\\Delta G°'\\) global ?", a: ["−16,7 kJ·mol⁻¹", "+44,3 kJ·mol⁻¹", "−44,3 kJ·mol⁻¹", "+16,7 kJ·mol⁻¹"], c: 0, e: "G étant une fonction d’état, les ΔG des réactions couplées s’additionnent : 13,8 − 30,5 = −16,7 kJ·mol⁻¹. La réaction globale devient spontanée : c’est le principe du couplage énergétique." },
  { d: 4, o: "4.4", q: "On considère la fusion de la glace à 25 °C sous 1 bar. Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["\\(\\Delta H \\gt 0\\)", "\\(\\Delta S \\gt 0\\)", "\\(\\Delta G \\gt 0\\) à 25 °C", "Elle est spontanée à toute température", "Elle est exothermique"], c: [0, 1], x: ["Il faut fournir de la chaleur.", "Le liquide est plus désordonné que le solide.", "À 25 °C, T > 273 K : TΔS > ΔH, ΔG < 0, la glace fond spontanément.", "En dessous de 0 °C, elle n’est pas spontanée.", "Elle est endothermique."], e: "ΔH > 0 et ΔS > 0 : spontanée au-dessus de la température de fusion (273 K), pas en dessous." },

  // ===================== Domaine 5 — Équilibres et acido-basique (63) =====================
  // 5.1 Équilibre
  { d: 5, o: "5.1", q: "Quelle est l’expression de la constante d’équilibre de \\(\\ce{N2(g) + 3 H2(g) <=> 2 NH3(g)}\\) (pressions rapportées à P°) ?", a: ["\\(K = \\dfrac{P_{NH_3}^2}{P_{N_2}\\,P_{H_2}^3}\\)", "\\(K = \\dfrac{2\\,P_{NH_3}}{P_{N_2} + 3\\,P_{H_2}}\\)", "\\(K = \\dfrac{P_{N_2}\\,P_{H_2}^3}{P_{NH_3}^2}\\)", "\\(K = \\dfrac{P_{NH_3}}{P_{N_2}\\,P_{H_2}}\\)"], c: 0, e: "Produits au numérateur, réactifs au dénominateur, chacun élevé à la puissance de son coefficient stœchiométrique. La troisième expression est la constante de la réaction inverse." },
  { d: 5, o: "5.1", q: "Dans un système, le quotient réactionnel Q est inférieur à la constante d’équilibre K. Comment évolue-t-il ?", a: ["Dans le sens direct (formation des produits)", "Dans le sens inverse", "Il n’évolue pas", "Cela dépend de la température uniquement"], c: 0, e: "Q < K : il n’y a « pas assez » de produits ; le système en forme jusqu’à ce que Q atteigne K. Q > K : sens inverse ; Q = K : équilibre." },
  { d: 5, o: "5.1", q: "De quoi dépend la valeur de la constante d’équilibre K d’une réaction donnée ?", a: ["Uniquement de la température", "Des concentrations initiales", "De la présence d’un catalyseur", "De la pression totale"], c: 0, e: "K est caractéristique de la réaction et ne dépend que de T. Concentrations et pression modifient Q, pas K ; un catalyseur ne modifie ni l’un ni l’autre." },
  { d: 5, o: "5.1", q: "Quelle est l’expression de K pour \\(\\ce{CaCO3(s) <=> CaO(s) + CO2(g)}\\) ?", a: ["\\(K = P_{CO_2}/P°\\)", "\\(K = \\dfrac{[\\ce{CaO}]\\,P_{CO_2}}{[\\ce{CaCO3}]}\\)", "\\(K = \\dfrac{[\\ce{CaCO3}]}{[\\ce{CaO}]}\\)", "\\(K = 1\\)"], c: 0, e: "Les solides purs ont une activité égale à 1 : ils n’apparaissent pas dans K. Seul le gaz CO₂ intervient." },
  { d: 5, o: "5.1", q: "La réaction A ⇌ B a une constante K = 4 à une température donnée. Que vaut la constante de la réaction B ⇌ A à la même température ?", a: ["0,25", "4", "−4", "16"], c: 0, e: "La constante de la réaction inverse est l’inverse : K′ = 1/K = 1/4 = 0,25." },
  { d: 5, o: "5.1", q: "Une réaction a pour constante \\(K = 10^3\\). Que vaut la constante de la même réaction dont tous les coefficients sont multipliés par 2 ?", a: ["\\(10^6\\)", "\\(2 \\times 10^3\\)", "\\(10^{3/2}\\)", "\\(10^3\\)"], c: 0, e: "Multiplier les coefficients par n élève K à la puissance n : K′ = (10³)² = 10⁶." },
  { d: 5, o: "5.1", q: "Pour \\(\\ce{A + B <=> C}\\) (K = 10), on a à un instant donné [A] = 0,10, [B] = 0,20 et [C] = 0,50 mol·L⁻¹. Dans quel sens le système évolue-t-il ?", a: ["Dans le sens inverse, car Q = 25 > K", "Dans le sens direct, car Q = 25 > K", "Dans le sens direct, car Q = 0,04 < K", "Il est à l’équilibre"], c: 0, e: "\\(Q = \\dfrac{0{,}50}{0{,}10 \\times 0{,}20} = 25\\). Q > K : trop de produit, le système évolue dans le sens inverse jusqu’à Q = 10." },
  { d: 5, o: "5.1", q: "À propos de l’état d’équilibre chimique, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Les vitesses des réactions directe et inverse sont égales", "La composition du système n’évolue plus", "Les réactions directe et inverse se sont arrêtées", "Les concentrations des réactifs et des produits sont égales", "Un équilibre ne peut être atteint qu’en partant des réactifs"], c: [0, 1], x: ["C’est la définition cinétique de l’équilibre.", "Composition constante à l’échelle macroscopique.", "Équilibre dynamique : elles continuent au même rythme.", "Elles sont liées par K, pas égales.", "On l’atteint aussi en partant des produits (réaction réversible)."], e: "L’équilibre est dynamique : deux réactions opposées à la même vitesse." },
  { d: 5, o: "5.1", q: "À propos de la constante d’équilibre et du quotient réactionnel, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Si \\(K \\gt 10^4\\), la réaction peut être considérée comme quasi totale", "Si Q = K, le système n’évolue pas", "K dépend des concentrations initiales", "L’eau solvant figure dans l’expression de K", "Un catalyseur augmente K"], c: [0, 1], x: ["L’équilibre est très déplacé vers les produits.", "Il est à l’équilibre.", "K ne dépend que de T.", "Le solvant a une activité égale à 1.", "Il accélère les deux sens également : K inchangée."], e: "Q décrit l’état actuel, K l’état d’équilibre ; la comparaison des deux donne le sens d’évolution." },
  { d: 5, o: "5.1", q: "À propos des réactions réversibles, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Pour une réaction limitée, le taux d’avancement final est inférieur à 1", "Si Q < K, alors \\(\\Delta_r G \\lt 0\\)", "Une réaction totale a toujours K < 1", "Q ne dépend pas de la composition du système", "À l’équilibre, \\(\\Delta_r G° = 0\\)"], c: [0, 1], x: ["τ = x_f / x_max < 1.", "ΔrG = RT ln(Q/K) et ln(Q/K) < 0.", "Une réaction quasi totale a K très grand.", "Q est calculé avec les concentrations actuelles.", "C’est ΔrG qui est nul à l’équilibre ; ΔrG° = −RT ln K n’est nul que si K = 1."], e: "Ne pas confondre ΔrG (dépend de Q, nul à l’équilibre) et ΔrG° (constante liée à K)." },

  // 5.2 Le Châtelier
  { d: 5, o: "5.2", q: "On ajoute un réactif à un système à l’équilibre (température constante). Que se passe-t-il ?", a: ["L’équilibre se déplace dans le sens direct", "L’équilibre se déplace dans le sens inverse", "K augmente", "Rien, car K est constante"], c: 0, e: "L’ajout de réactif fait diminuer Q (Q < K) : le système consomme une partie du réactif ajouté en formant des produits. K ne change pas." },
  { d: 5, o: "5.2", q: "Pour \\(\\ce{N2(g) + 3 H2(g) <=> 2 NH3(g)}\\), quel est l’effet d’une augmentation de pression (par diminution du volume) ?", a: ["Déplacement vers la formation de \\(\\ce{NH3}\\)", "Déplacement vers la formation de \\(\\ce{N2}\\) et \\(\\ce{H2}\\)", "Aucun effet", "Augmentation de K"], c: 0, e: "4 moles de gaz à gauche, 2 à droite. Une hausse de pression favorise le sens qui diminue le nombre de moles de gaz, donc la formation de NH₃." },
  { d: 5, o: "5.2", q: "Une réaction exothermique est à l’équilibre. On augmente la température. Que se passe-t-il ?", a: ["L’équilibre se déplace dans le sens inverse et K diminue", "L’équilibre se déplace dans le sens direct et K augmente", "L’équilibre ne bouge pas mais K diminue", "L’équilibre se déplace dans le sens direct et K diminue"], c: 0, e: "Une hausse de T favorise le sens endothermique, ici le sens inverse. La température est le seul facteur qui modifie K : pour ΔrH° < 0, K diminue quand T augmente." },
  { d: 5, o: "5.2", q: "Pour \\(\\ce{H2(g) + I2(g) <=> 2 HI(g)}\\), quel est l’effet d’une augmentation de pression ?", a: ["Aucun, car le nombre de moles de gaz est le même de chaque côté", "Déplacement vers HI", "Déplacement vers H₂ et I₂", "Augmentation de K"], c: 0, e: "2 moles de gaz de chaque côté (Δn_gaz = 0) : la pression n’a pas d’influence sur la position de cet équilibre." },
  { d: 5, o: "5.2", q: "Quel est l’effet de l’ajout d’un catalyseur sur un système à l’équilibre ?", a: ["Aucun déplacement : l’équilibre est seulement atteint plus vite", "Déplacement dans le sens direct", "Déplacement dans le sens inverse", "Augmentation de K"], c: 0, e: "Le catalyseur accélère autant la réaction directe que l’inverse : ni K ni la composition d’équilibre ne changent." },
  { d: 5, o: "5.2", q: "Un patient anxieux hyperventile et élimine beaucoup de \\(\\ce{CO2}\\). Sachant que \\(\\ce{CO2 + H2O <=> H2CO3 <=> HCO3- + H+}\\), quelle est la conséquence ?", a: ["L’équilibre se déplace vers la gauche, [H⁺] diminue et le pH sanguin augmente (alcalose)", "L’équilibre se déplace vers la droite et le pH diminue (acidose)", "Le pH ne change pas grâce aux tampons", "La concentration en \\(\\ce{HCO3-}\\) augmente"], c: 0, e: "Retirer CO₂ (réactif) déplace les équilibres vers la gauche : H⁺ et HCO₃⁻ sont consommés, le pH monte : alcalose respiratoire." },
  { d: 5, o: "5.2", q: "On considère \\(\\ce{N2O4(g) <=> 2 NO2(g)}\\) avec \\(\\Delta_r H° \\gt 0\\). Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Une augmentation de température favorise la formation de \\(\\ce{NO2}\\)", "Une augmentation de pression favorise la formation de \\(\\ce{N2O4}\\)", "Une augmentation de température diminue K", "L’ajout d’un catalyseur favorise la formation de \\(\\ce{NO2}\\)", "L’ajout de \\(\\ce{NO2}\\) déplace l’équilibre vers la formation de \\(\\ce{NO2}\\)"], c: [0, 1], x: ["Le sens direct est endothermique.", "Sens qui réduit le nombre de moles de gaz (2 → 1).", "Réaction endothermique : K augmente avec T.", "Un catalyseur ne déplace pas l’équilibre.", "Ajouter un produit déplace l’équilibre vers les réactifs."], e: "Le système s’oppose à la perturbation : il consomme la chaleur apportée, réduit le nombre de moles de gaz sous pression, consomme l’espèce ajoutée." },
  { d: 5, o: "5.2", q: "À propos du principe de Le Châtelier, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Retirer un produit déplace l’équilibre dans le sens direct", "Parmi concentration, pression et température, seule la température modifie K", "L’ajout d’un gaz inerte à volume constant ne déplace pas l’équilibre", "Une augmentation de pression déplace toujours l’équilibre", "Le système annule complètement la perturbation"], c: [0, 1, 2], x: ["Q diminue, le système reforme du produit.", "Les autres facteurs modifient Q.", "Les pressions partielles des constituants ne changent pas.", "Sans effet si Δn_gaz = 0.", "Il la modère seulement."], e: "Le Châtelier donne le sens de l’évolution, qui modère sans annuler la perturbation." },

  // 5.3 Acides et bases
  { d: 5, o: "5.3", q: "Selon Brønsted, qu’est-ce qu’un acide ?", a: ["Une espèce capable de céder un proton \\(\\ce{H+}\\)", "Une espèce capable de capter un proton", "Une espèce capable de céder un électron", "Une espèce qui libère des ions \\(\\ce{HO-}\\) dans l’eau"], c: 0, e: "Acide de Brønsted : donneur de proton ; base : accepteur de proton. Céder un électron caractérise un réducteur ; libérer HO⁻ est la définition d’une base selon Arrhenius." },
  { d: 5, o: "5.3", q: "Quelle est la base conjuguée de l’ion ammonium \\(\\ce{NH4+}\\) ?", a: ["\\(\\ce{NH3}\\)", "\\(\\ce{NH2-}\\)", "\\(\\ce{NH4OH}\\)", "\\(\\ce{H3O+}\\)"], c: 0, e: "NH₄⁺ ⇌ NH₃ + H⁺ : la base conjuguée s’obtient en retirant un proton à l’acide." },
  { d: 5, o: "5.3", q: "Quel est l’acide conjugué de l’ion hydrogénocarbonate \\(\\ce{HCO3-}\\) ?", a: ["\\(\\ce{H2CO3}\\)", "\\(\\ce{CO3^2-}\\)", "\\(\\ce{CO2}\\)", "\\(\\ce{H3O+}\\)"], c: 0, e: "L’acide conjugué possède un proton de plus : H₂CO₃. CO₃²⁻ est sa base conjuguée : HCO₃⁻ est un ampholyte." },
  { d: 5, o: "5.3", q: "Parmi ces espèces, laquelle est un ampholyte ?", a: ["\\(\\ce{HCO3-}\\)", "\\(\\ce{Cl-}\\)", "\\(\\ce{Na+}\\)", "\\(\\ce{NH4+}\\)"], c: 0, e: "HCO₃⁻ est la base du couple H₂CO₃/HCO₃⁻ et l’acide du couple HCO₃⁻/CO₃²⁻. NH₄⁺ n’est qu’un acide ; Cl⁻ et Na⁺ sont indifférents dans l’eau." },
  { d: 5, o: "5.3", q: "Dans la réaction \\(\\ce{CH3COOH + NH3 -> CH3COO- + NH4+}\\), quels sont les deux couples acide/base mis en jeu ?", a: ["\\(\\ce{CH3COOH}/\\ce{CH3COO-}\\) et \\(\\ce{NH4+}/\\ce{NH3}\\)", "\\(\\ce{CH3COOH}/\\ce{NH3}\\) et \\(\\ce{NH4+}/\\ce{CH3COO-}\\)", "\\(\\ce{CH3COO-}/\\ce{CH3COOH}\\) et \\(\\ce{NH3}/\\ce{NH4+}\\)", "\\(\\ce{H3O+}/\\ce{H2O}\\) et \\(\\ce{H2O}/\\ce{HO-}\\)"], c: 0, e: "L’acide éthanoïque cède son proton (couple CH₃COOH/CH₃COO⁻) à l’ammoniac qui le capte (couple NH₄⁺/NH₃). Un couple s’écrit acide/base." },
  { d: 5, o: "5.3", q: "Lequel de ces couples n’est pas un couple acide/base ?", a: ["\\(\\ce{H2O}/\\ce{H2}\\)", "\\(\\ce{H3O+}/\\ce{H2O}\\)", "\\(\\ce{CH3COOH}/\\ce{CH3COO-}\\)", "\\(\\ce{NH4+}/\\ce{NH3}\\)"], c: 0, e: "H₂O et H₂ ne diffèrent pas d’un proton H⁺ : c’est un couple d’oxydoréduction (H₂O/H₂, écrit aussi H⁺/H₂)." },
  { d: 5, o: "5.3", q: "À propos des couples de l’eau, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["L’eau est la base du couple \\(\\ce{H3O+}/\\ce{H2O}\\)", "L’eau est l’acide du couple \\(\\ce{H2O}/\\ce{HO-}\\)", "\\(\\ce{HO-}\\) est l’acide conjugué de l’eau", "\\(\\ce{Cl-}\\) est l’acide conjugué de HCl", "Un acide de Brønsted capte un proton"], c: [0, 1], x: ["Elle capte un proton pour donner H₃O⁺.", "Elle cède un proton pour donner HO⁻.", "HO⁻ est la base conjuguée de l’eau.", "Cl⁻ est la base conjuguée de HCl.", "Il le cède."], e: "L’eau est un ampholyte : base face à un acide, acide face à une base." },
  { d: 5, o: "5.3", q: "À propos de la réaction \\(\\ce{CH3COOH + HO- -> CH3COO- + H2O}\\), quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["C’est un transfert de proton", "L’ion hydroxyde joue le rôle de base", "\\(\\ce{CH3COO-}\\) est l’acide conjugué de \\(\\ce{CH3COOH}\\)", "Des électrons sont transférés : c’est une réaction d’oxydoréduction", "L’eau formée est la base conjuguée de \\(\\ce{HO-}\\)"], c: [0, 1], x: ["Réaction acido-basique de Brønsted.", "Il capte le proton de l’acide.", "C’est sa base conjuguée.", "Aucun nombre d’oxydation ne change.", "L’eau est l’acide conjugué de HO⁻ (elle a un proton de plus)."], e: "Une réaction acido-basique échange un proton entre deux couples : acide₁ + base₂ → base₁ + acide₂." },
  { d: 5, o: "5.3", q: "Parmi ces espèces, laquelle peut jouer le rôle de base de Brønsted ?", a: ["\\(\\ce{NH3}\\)", "\\(\\ce{NH4+}\\)", "\\(\\ce{H3O+}\\)", "\\(\\ce{CH4}\\)"], c: 0, e: "Une base de Brønsted capte un proton grâce à un doublet non liant : c’est le cas de l’azote de NH₃. NH₄⁺ et H₃O⁺ sont des acides ; CH₄ n’a ni doublet libre ni proton labile." },

  // 5.4 pH
  { d: 5, o: "5.4", q: "Quel est le pH d’une solution d’acide chlorhydrique à \\(1{,}0 \\times 10^{-3}\\) mol·L⁻¹ ?", a: ["3", "11", "−3", "1,5"], c: 0, e: "Acide fort totalement dissocié : [H₃O⁺] = C = 10⁻³ mol·L⁻¹, pH = −log 10⁻³ = 3." },
  { d: 5, o: "5.4", q: "Quel est le pH d’une solution de soude (NaOH) à \\(1{,}0 \\times 10^{-2}\\) mol·L⁻¹ à 25 °C ?", a: ["12", "2", "7", "14"], c: 0, e: "Base forte : [HO⁻] = 10⁻² mol·L⁻¹, pOH = 2, pH = 14 − 2 = 12." },
  { d: 5, o: "5.4", q: "Quelle est la concentration en ions oxonium d’un sang de pH 7,4 ?", a: ["\\(4{,}0 \\times 10^{-8}\\) mol·L⁻¹", "\\(7{,}4 \\times 10^{-8}\\) mol·L⁻¹", "\\(2{,}5 \\times 10^{-7}\\) mol·L⁻¹", "\\(10^{-7}\\) mol·L⁻¹"], c: 0, e: "\\([\\ce{H3O+}] = 10^{-7{,}4} = 10^{0{,}6} \\times 10^{-8} \\approx 4{,}0 \\times 10^{-8}\\) mol·L⁻¹ (10^0,6 ≈ 4)." },
  { d: 5, o: "5.4", q: "Une solution a un pH de 3 à 25 °C. Quel est son pOH ?", a: ["11", "3", "7", "−3"], c: 0, e: "À 25 °C, pH + pOH = pKe = 14, donc pOH = 14 − 3 = 11." },
  { d: 5, o: "5.4", q: "Quelle est la valeur du produit ionique de l’eau à 25 °C ?", a: ["\\(K_e = 10^{-14}\\)", "\\(K_e = 10^{-7}\\)", "\\(K_e = 14\\)", "\\(K_e = 10^{14}\\)"], c: 0, e: "Ke = [H₃O⁺][HO⁻] = 10⁻¹⁴ à 25 °C (pKe = 14). Dans l’eau pure, [H₃O⁺] = [HO⁻] = 10⁻⁷ mol·L⁻¹." },
  { d: 5, o: "5.4", q: "Quel est le pH d’une solution d’acide chlorhydrique à \\(1{,}0 \\times 10^{-8}\\) mol·L⁻¹ ?", a: ["Légèrement inférieur à 7", "8", "Exactement 7", "Légèrement supérieur à 7"], c: 0, e: "Une solution d’acide ne peut pas être basique. À une concentration aussi faible, les ions H₃O⁺ issus de l’autoprotolyse de l’eau (10⁻⁷) ne sont plus négligeables : pH ≈ 6,98. La formule pH = −log C n’est valable que pour C supérieure à environ 10⁻⁶ mol·L⁻¹." },
  { d: 5, o: "5.4", q: "Combien de fois une solution de pH 4 est-elle plus concentrée en \\(\\ce{H3O+}\\) qu’une solution de pH 6 ?", a: ["100 fois", "2 fois", "1,5 fois", "20 fois"], c: 0, e: "10⁻⁴ / 10⁻⁶ = 10² = 100. L’échelle de pH est logarithmique : chaque unité correspond à un facteur 10." },
  { d: 5, o: "5.4", q: "On dilue 10 fois une solution d’acide chlorhydrique de pH 2. Quel est le nouveau pH ?", a: ["3", "1", "2", "12"], c: 0, e: "[H₃O⁺] passe de 10⁻² à 10⁻³ mol·L⁻¹ : le pH augmente d’une unité. Diluer un acide rapproche son pH de 7 sans le dépasser." },
  { d: 5, o: "5.4", q: "À 25 °C, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Une solution de pH 9 est basique", "\\([\\ce{H3O+}][\\ce{HO-}] = 10^{-14}\\) dans toute solution aqueuse diluée", "pH + pOH = 14", "Une solution neutre a un pH de 7 quelle que soit la température", "Dans une solution de pH 9, \\([\\ce{HO-}] = 10^{-9}\\) mol·L⁻¹"], c: [0, 1, 2], x: ["pH > 7 à 25 °C.", "C’est le produit ionique de l’eau.", "Conséquence du produit ionique.", "À 37 °C, pKe ≈ 13,6 et le pH neutre vaut ≈ 6,8.", "[H₃O⁺] = 10⁻⁹, donc [HO⁻] = 10⁻⁵ mol·L⁻¹."], e: "pH = −log[H₃O⁺] ; pOH = −log[HO⁻] ; à 25 °C, pH + pOH = 14." },
  { d: 5, o: "5.4", q: "On prépare une solution d’hydroxyde de baryum \\(\\ce{Ba(OH)2}\\), base forte, à \\(5{,}0 \\times 10^{-3}\\) mol·L⁻¹ (25 °C). Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["\\([\\ce{HO-}] = 1{,}0 \\times 10^{-2}\\) mol·L⁻¹", "Le pH vaut 12", "Le pH vaut 11,7", "Le pOH vaut 12", "Le pH vaut 2"], c: [0, 1], x: ["Chaque Ba(OH)₂ libère 2 HO⁻ : 2 × 5,0 × 10⁻³.", "pOH = 2, pH = 14 − 2 = 12.", "Résultat obtenu en oubliant le facteur 2 (14 + log 5 × 10⁻³).", "pOH = 2.", "C’est le pOH, pas le pH."], e: "Pour une polybase forte, [HO⁻] = (nombre de HO⁻ libérés) × C." },

  // 5.5 Acides et bases faibles
  { d: 5, o: "5.5", q: "L’acide éthanoïque a une constante d’acidité \\(K_a = 1{,}8 \\times 10^{-5}\\). Quel est son pKa ?", a: ["4,74", "5,26", "−4,74", "1,8"], c: 0, e: "\\(pK_a = -\\log(1{,}8 \\times 10^{-5}) = 5 - \\log 1{,}8 \\approx 5 - 0{,}26 = 4{,}74\\)." },
  { d: 5, o: "5.5", q: "Parmi ces acides, lequel est le plus fort ?", a: ["Acide lactique (pKa = 3,9)", "Acide éthanoïque (pKa = 4,8)", "Acide carbonique (pKa = 6,4)", "Ion ammonium (pKa = 9,2)"], c: 0, e: "Plus le pKa est petit (Ka grand), plus l’acide est fort, c’est-à-dire plus il cède facilement son proton." },
  { d: 5, o: "5.5", q: "Quel est le pH d’une solution d’acide éthanoïque à \\(1{,}0 \\times 10^{-2}\\) mol·L⁻¹ (pKa = 4,8) ?", a: ["3,4", "2,0", "6,8", "4,8"], c: 0, e: "\\(\\mathrm{pH} = \\tfrac{1}{2}(pK_a - \\log C) = \\tfrac{1}{2}(4{,}8 + 2) = 3{,}4\\). Validité : 3,4 ≤ pKa − 1 = 3,8 : l’acide est bien peu dissocié. 2,0 serait le pH d’un acide fort." },
  { d: 5, o: "5.5", q: "Quel est le pH d’une solution d’ammoniac à \\(1{,}0 \\times 10^{-2}\\) mol·L⁻¹ (pKa(\\(\\ce{NH4+}/\\ce{NH3}\\)) = 9,2) ?", a: ["10,6", "12,0", "5,6", "9,2"], c: 0, e: "\\(\\mathrm{pH} = 7 + \\tfrac{1}{2}(pK_a + \\log C) = 7 + \\tfrac{1}{2}(9{,}2 - 2) = 10{,}6\\). Validité : 10,6 ≥ pKa + 1 = 10,2. 12 serait le pH d’une base forte de même concentration." },
  { d: 5, o: "5.5", q: "L’acide lactique (pKa = 3,9) est produit par les muscles en effort. Sous quelle forme se trouve-t-il majoritairement dans le sang (pH 7,4) ?", a: ["Sous forme de lactate (base conjuguée)", "Sous forme d’acide lactique", "Moitié acide, moitié lactate", "Sous forme neutre et chargée positivement"], c: 0, e: "pH > pKa : la forme basique prédomine. Avec pH − pKa = 3,5, le rapport lactate/acide vaut 10^3,5 ≈ 3 000." },
  { d: 5, o: "5.5", q: "Quel est le pKb de l’ammoniac, sachant que le pKa du couple \\(\\ce{NH4+}/\\ce{NH3}\\) vaut 9,2 (25 °C) ?", a: ["4,8", "9,2", "23,2", "−9,2"], c: 0, e: "pKa + pKb = pKe = 14 à 25 °C, donc pKb = 14 − 9,2 = 4,8." },
  { d: 5, o: "5.5", q: "Pour un couple AH/A⁻, quel est le rapport \\([\\ce{A-}]/[\\ce{AH}]\\) lorsque pH = pKa + 2 ?", a: ["100", "2", "0,01", "20"], c: 0, e: "pH = pKa + log([A⁻]/[AH]) ⇒ log([A⁻]/[AH]) = 2 ⇒ rapport = 10² = 100." },
  { d: 5, o: "5.5", q: "À propos de la formule \\(\\mathrm{pH} = \\tfrac{1}{2}(pK_a - \\log C)\\), quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Elle suppose l’acide faible peu dissocié", "On vérifie a posteriori que pH ≤ pKa − 1", "Elle s’applique à tous les acides quelle que soit leur concentration", "Elle s’applique aux acides forts", "Elle s’applique à un acide « faible » au sens de « dilué »"], c: [0, 1], x: ["Approximation : [AH] ≈ C.", "Condition de validité de l’approximation.", "Si l’acide est très dilué ou assez fort, elle devient fausse.", "Pour un acide fort, pH = −log C.", "Faible = partiellement dissocié, pas peu concentré."], e: "Toute formule approchée s’accompagne d’un domaine de validité à vérifier." },
  { d: 5, o: "5.5", q: "On considère le couple \\(\\ce{NH4+}/\\ce{NH3}\\) (pKa = 9,2). Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["À pH 7,4, la forme \\(\\ce{NH4+}\\) prédomine", "À pH 9,2, \\([\\ce{NH4+}] = [\\ce{NH3}]\\)", "À pH 11, la forme \\(\\ce{NH4+}\\) prédomine", "\\(K_a = 10^{9{,}2}\\)", "\\(\\ce{NH3}\\) est un acide plus fort que \\(\\ce{NH4+}\\)"], c: [0, 1], x: ["pH < pKa : forme acide majoritaire.", "pH = pKa : les deux formes à égalité.", "pH > pKa : NH₃ prédomine.", "Ka = 10⁻⁹·² ≈ 6 × 10⁻¹⁰.", "NH₃ est la base du couple."], e: "Diagramme de prédominance : acide sous le pKa, base au-dessus." },
  { d: 5, o: "5.5", q: "À propos de Ka et pKa, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Plus le Ka est grand, plus l’acide est fort", "pKa + pKb = 14 à 25 °C", "Plus un acide est fort, plus sa base conjuguée est faible", "Diluer un acide faible diminue son coefficient de dissociation", "\\(pK_a = \\log K_a\\)"], c: [0, 1, 2], x: ["Il est plus dissocié.", "Car Ka × Kb = Ke.", "Conséquence de Ka × Kb = Ke.", "Il l’augmente (loi de dilution d’Ostwald).", "pKa = −log Ka."], e: "Ka × Kb = Ke : force de l’acide et force de sa base conjuguée varient en sens inverse." },

  // 5.6 Solutions tampons
  { d: 5, o: "5.6", q: "Quel mélange constitue une solution tampon ?", a: ["Acide éthanoïque + éthanoate de sodium en quantités voisines", "Acide chlorhydrique + chlorure de sodium", "Soude + chlorure de sodium", "Acide chlorhydrique + soude en quantités égales"], c: 0, e: "Un tampon associe un acide faible et sa base conjuguée. HCl/Cl⁻ n’en est pas un (Cl⁻ est une base indifférente) ; HCl + NaOH en quantités égales donne de l’eau salée neutre." },
  { d: 5, o: "5.6", q: "Un tampon contient un acide faible (pKa = 4,8) et sa base conjuguée dans le rapport [base]/[acide] = 10. Quel est son pH ?", a: ["5,8", "3,8", "4,8", "14,8"], c: 0, e: "Henderson-Hasselbalch : pH = 4,8 + log 10 = 5,8." },
  { d: 5, o: "5.6", q: "Chez un patient, \\([\\ce{HCO3-}] = 12\\) mmol·L⁻¹ et \\(P_{CO_2} = 40\\) mmHg. Avec \\(\\mathrm{pH} = 6{,}1 + \\log\\dfrac{[\\ce{HCO3-}]}{0{,}03 \\times P_{CO_2}}\\), quel est son pH sanguin ?", a: ["7,1 : acidose", "7,4 : pH normal", "7,7 : alcalose", "6,1"], c: 0, e: "0,03 × 40 = 1,2 mmol·L⁻¹ ; rapport 12 / 1,2 = 10 ; pH = 6,1 + 1 = 7,1 < 7,35 : acidose (ici métabolique, par baisse des bicarbonates)." },
  { d: 5, o: "5.6", q: "Pour quelle valeur de pH le pouvoir tampon d’un couple AH/A⁻ est-il maximal ?", a: ["pH = pKa", "pH = 7", "pH = pKa + 2", "pH = 14 − pKa"], c: 0, e: "Le pouvoir tampon est maximal quand [AH] = [A⁻], soit pH = pKa ; la zone efficace s’étend environ de pKa − 1 à pKa + 1." },
  { d: 5, o: "5.6", q: "On ajoute un peu d’acide chlorhydrique à un tampon éthanoïque. Quelle réaction limite la variation de pH ?", a: ["\\(\\ce{CH3COO- + H3O+ -> CH3COOH + H2O}\\)", "\\(\\ce{CH3COOH + HO- -> CH3COO- + H2O}\\)", "\\(\\ce{H3O+ + Cl- -> HCl + H2O}\\)", "\\(\\ce{2 H2O -> H3O+ + HO-}\\)"], c: 0, e: "La base du tampon capte les H₃O⁺ ajoutés. La deuxième réaction intervient lors d’un ajout de base." },
  { d: 5, o: "5.6", q: "Un tampon contient 0,20 mol d’ammoniac et 0,10 mol de chlorure d’ammonium dans 1 L (pKa = 9,2). Quel est son pH ?", a: ["9,5", "8,9", "9,2", "11,1"], c: 0, e: "pH = pKa + log([NH₃]/[NH₄⁺]) = 9,2 + log 2 = 9,2 + 0,3 = 9,5. 8,9 correspond au rapport inversé." },
  { d: 5, o: "5.6", q: "À propos des solutions tampons, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Le pH d’un tampon dépend du rapport [base]/[acide]", "Le pouvoir tampon augmente avec la concentration totale du tampon", "Un tampon a toujours un pH de 7", "Diluer un tampon 10 fois fait varier son pH d’une unité", "Un mélange HCl + NaCl constitue un tampon"], c: [0, 1], x: ["Henderson-Hasselbalch.", "Plus d’acide et de base disponibles pour neutraliser les ajouts.", "Son pH est voisin du pKa du couple.", "Le rapport ne change pas : le pH varie très peu.", "HCl est un acide fort et Cl⁻ une base indifférente."], e: "pH fixé par le rapport ; capacité fixée par la concentration." },
  { d: 5, o: "5.6", q: "À propos du tampon bicarbonate sanguin, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["C’est le principal tampon du plasma", "Les poumons régulent la \\(P_{CO_2}\\)", "Une hyperventilation provoque une acidose", "Le pH sanguin normal vaut 6,1", "Les reins n’interviennent pas dans son fonctionnement"], c: [0, 1], x: ["Couple CO₂ dissous/HCO₃⁻.", "Par la ventilation.", "Elle élimine du CO₂ : alcalose.", "6,1 est le pKa ; le pH normal est 7,35 à 7,45.", "Ils régulent la concentration en HCO₃⁻."], e: "Système ouvert : ventilation (CO₂) et reins (HCO₃⁻) maintiennent le rapport HCO₃⁻/CO₂ proche de 20." },

  // 5.7 Dosages
  { d: 5, o: "5.7", q: "On titre 10,0 mL d’acide chlorhydrique par de la soude à 0,10 mol·L⁻¹ ; l’équivalence est atteinte pour 12,0 mL. Quelle est la concentration de l’acide ?", a: ["0,12 mol·L⁻¹", "0,083 mol·L⁻¹", "1,2 mol·L⁻¹", "0,012 mol·L⁻¹"], c: 0, e: "À l’équivalence : \\(C_A V_A = C_B V_E\\) ⇒ \\(C_A = 0{,}10 \\times 12{,}0 / 10{,}0 = 0{,}12\\) mol·L⁻¹. 0,083 correspond au rapport des volumes inversé." },
  { d: 5, o: "5.7", q: "Lors du titrage d’un acide faible par une base forte, que vaut le pH à l’équivalence ?", a: ["Il est supérieur à 7", "Il vaut exactement 7", "Il est inférieur à 7", "Il est égal au pKa"], c: 0, e: "À l’équivalence, la solution contient la base conjuguée de l’acide faible (A⁻), qui rend le milieu basique. pH = pKa correspond à la demi-équivalence." },
  { d: 5, o: "5.7", q: "Lors du titrage d’un acide faible par la soude, \\(V_E = 20{,}0\\) mL et le pH vaut 3,9 pour un volume versé de 10,0 mL. Que peut-on en déduire ?", a: ["Le pKa de l’acide vaut 3,9", "L’acide est un acide fort", "Le pH à l’équivalence vaut 3,9", "La concentration de l’acide vaut \\(10^{-3{,}9}\\) mol·L⁻¹"], c: 0, e: "10,0 mL = V_E/2 : demi-équivalence, où [AH] = [A⁻] et donc pH = pKa = 3,9 (c’est la valeur de l’acide lactique)." },
  { d: 5, o: "5.7", q: "On titre de l’acide éthanoïque par la soude (pH à l’équivalence ≈ 8,5). Quel indicateur coloré choisir ?", a: ["La phénolphtaléine (zone de virage 8,2 à 10)", "L’hélianthine (3,1 à 4,4)", "Le bleu de bromothymol (6,0 à 7,6)", "Aucun indicateur ne convient"], c: 0, e: "La zone de virage doit contenir le pH à l’équivalence : 8,5 est dans la zone de la phénolphtaléine." },
  { d: 5, o: "5.7", q: "On titre 10,0 mL d’acide sulfurique \\(\\ce{H2SO4}\\) par de la soude à 0,10 mol·L⁻¹ ; \\(V_E = 15{,}0\\) mL. Quelle est la concentration de l’acide ?", a: ["0,075 mol·L⁻¹", "0,15 mol·L⁻¹", "0,30 mol·L⁻¹", "0,067 mol·L⁻¹"], c: 0, e: "\\(\\ce{H2SO4 + 2 HO- -> SO4^2- + 2 H2O}\\) : à l’équivalence, \\(n(\\ce{HO-}) = 2\\,n(\\ce{H2SO4})\\). \\(C_A = \\dfrac{0{,}10 \\times 15{,}0}{2 \\times 10{,}0} = 0{,}075\\) mol·L⁻¹. Oublier le facteur 2 donne 0,15." },
  { d: 5, o: "5.7", q: "Au point d’équivalence du titrage de l’acide chlorhydrique par la soude, à 25 °C, quel est le pH ?", a: ["7", "Inférieur à 7", "Supérieur à 7", "Égal au pKa de HCl"], c: 0, e: "Titrage fort/fort : à l’équivalence, il ne reste que Na⁺ et Cl⁻, ions indifférents : la solution est neutre, pH = 7." },
  { d: 5, o: "5.7", q: "À propos de la courbe de titrage d’un acide faible par une base forte, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["À la demi-équivalence, pH = pKa", "Le pH à l’équivalence est supérieur à 7", "Avant l’équivalence, le mélange se comporte comme un tampon", "Le volume équivalent dépend du pKa de l’acide", "Le pH initial vaut −log C"], c: [0, 1, 2], x: ["[AH] = [A⁻].", "Présence de la base conjuguée A⁻.", "AH et A⁻ coexistent : le pH varie lentement.", "V_E ne dépend que de la quantité d’acide.", "C’est le cas d’un acide fort ; pour un acide faible, pH = ½(pKa − log C)."], e: "La demi-équivalence donne le pKa ; l’équivalence donne la concentration." },
  { d: 5, o: "5.7", q: "On titre une solution d’ammoniac (pKa = 9,2) par l’acide chlorhydrique. Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Le pH à l’équivalence est inférieur à 7", "À la demi-équivalence, le pH vaut 9,2", "La phénolphtaléine est l’indicateur le plus adapté", "Le pH augmente au cours du titrage", "À l’équivalence, l’espèce majoritaire est \\(\\ce{NH3}\\)"], c: [0, 1], x: ["À l’équivalence, il reste l’acide faible NH₄⁺.", "[NH₃] = [NH₄⁺], donc pH = pKa.", "Sa zone de virage (8,2 à 10) est loin du pH à l’équivalence (acide).", "On ajoute un acide : le pH diminue.", "NH₃ a été transformé en NH₄⁺."], e: "Base faible titrée par un acide fort : courbe descendante, pH à l’équivalence < 7, pH = pKa à la demi-équivalence." },

  // ===================== Domaine 6 — Oxydo-réduction (42) =====================
  // 6.1 Réactions redox
  { d: 6, o: "6.1", q: "Qu’est-ce qu’une oxydation ?", a: ["Une perte d’électrons", "Un gain d’électrons", "Une perte de protons", "Un gain d’atomes d’hydrogène"], c: 0, e: "Oxydation = perte d’électrons (le nombre d’oxydation augmente) ; réduction = gain d’électrons. La perte d’un proton relève de l’acido-basique." },
  { d: 6, o: "6.1", q: "Dans la réaction \\(\\ce{Zn + Cu^2+ -> Zn^2+ + Cu}\\), quelle espèce est l’oxydant ?", a: ["\\(\\ce{Cu^2+}\\)", "\\(\\ce{Zn}\\)", "\\(\\ce{Zn^2+}\\)", "\\(\\ce{Cu}\\)"], c: 0, e: "Cu²⁺ capte 2 électrons pour devenir Cu : c’est l’oxydant, et il est réduit. Le zinc cède ses électrons : c’est le réducteur, il est oxydé." },
  { d: 6, o: "6.1", q: "Qu’est-ce qu’un réducteur ?", a: ["Une espèce capable de céder des électrons", "Une espèce capable de capter des électrons", "Une espèce qui est réduite au cours de la réaction", "Une espèce capable de céder un proton"], c: 0, e: "Le réducteur cède des électrons et est donc oxydé au cours de la réaction. Céder un proton définit un acide." },
  { d: 6, o: "6.1", q: "Quelle est la demi-équation électronique du couple \\(\\ce{Fe^3+}/\\ce{Fe^2+}\\) ?", a: ["\\(\\ce{Fe^3+ + e- = Fe^2+}\\)", "\\(\\ce{Fe^2+ + e- = Fe^3+}\\)", "\\(\\ce{Fe^3+ = Fe^2+ + e-}\\)", "\\(\\ce{Fe^3+ + 2 e- = Fe^2+}\\)"], c: 0, e: "Ox + n e⁻ = Red : l’oxydant Fe³⁺ gagne un électron pour donner Fe²⁺. Les charges : +3 − 1 = +2." },
  { d: 6, o: "6.1", q: "Lequel de ces couples est un couple d’oxydoréduction ?", a: ["\\(\\ce{Cu^2+}/\\ce{Cu}\\)", "\\(\\ce{NH4+}/\\ce{NH3}\\)", "\\(\\ce{H2CO3}/\\ce{HCO3-}\\)", "\\(\\ce{CH3COOH}/\\ce{CH3COO-}\\)"], c: 0, e: "Cu²⁺ et Cu diffèrent de 2 électrons : couple redox. Les trois autres diffèrent d’un proton : couples acide/base." },
  { d: 6, o: "6.1", q: "Dans le couple \\(\\ce{NAD+}/\\ce{NADH}\\), impliqué dans le métabolisme, quel est le rôle de \\(\\ce{NAD+}\\) ?", a: ["C’est l’oxydant du couple : il capte des électrons", "C’est le réducteur du couple : il cède des électrons", "C’est l’acide du couple", "C’est un catalyseur qui n’échange pas d’électrons"], c: 0, e: "NAD⁺ + H⁺ + 2 e⁻ = NADH : NAD⁺ est la forme oxydée qui capte les électrons (lors de l’oxydation de l’éthanol ou du glucose par exemple) ; NADH est la forme réduite." },
  { d: 6, o: "6.1", q: "La décomposition \\(\\ce{2 H2O2 -> 2 H2O + O2}\\) est une dismutation. Qu’est-ce que cela signifie ?", a: ["La même espèce est à la fois oxydée et réduite", "Deux espèces différentes échangent des protons", "L’eau oxygénée est seulement oxydée", "Il n’y a aucun transfert d’électrons"], c: 0, e: "L’oxygène de H₂O₂ (n.o. −I) est en partie réduit en H₂O (−II) et en partie oxydé en O₂ (0) : H₂O₂ joue les deux rôles." },
  { d: 6, o: "6.1", q: "À propos de la réaction \\(\\ce{Zn + Cu^2+ -> Zn^2+ + Cu}\\), quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Le zinc est oxydé", "Les ions \\(\\ce{Cu^2+}\\) sont réduits", "Le zinc est l’oxydant", "Les ions \\(\\ce{Cu^2+}\\) cèdent des électrons", "Deux électrons passent du cuivre au zinc"], c: [0, 1], x: ["Zn → Zn²⁺ + 2 e⁻.", "Cu²⁺ + 2 e⁻ → Cu.", "C’est le réducteur.", "Ils en captent.", "Les électrons passent du zinc au cuivre(II)."], e: "Le réducteur (Zn) cède ses électrons à l’oxydant (Cu²⁺)." },
  { d: 6, o: "6.1", q: "À propos des oxydants et des réducteurs, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Un oxydant est une espèce capable de capter des électrons", "Au cours d’une réaction, l’oxydant est réduit", "Une réduction est un gain d’électrons", "Un réducteur est réduit au cours de la réaction", "Une oxydation fait diminuer le nombre d’oxydation"], c: [0, 1, 2], x: ["Définition.", "« L’oxydant est réduit, le réducteur est oxydé ».", "Définition.", "Il est oxydé.", "Elle le fait augmenter."], e: "Oxydant → capte e⁻ → subit une réduction ; réducteur → cède e⁻ → subit une oxydation." },
  { d: 6, o: "6.1", q: "La vitamine C (acide ascorbique) protège les cellules en réagissant avec des espèces oxydantes. Quel est son rôle chimique ?", a: ["C’est un réducteur : elle cède des électrons et est oxydée", "C’est un oxydant : elle capte des électrons", "C’est une base : elle capte des protons", "C’est un catalyseur : elle n’est pas modifiée"], c: 0, e: "Un antioxydant neutralise les oxydants en leur cédant des électrons : c’est un réducteur, qui s’oxyde à leur place (en acide déshydroascorbique pour la vitamine C)." },

  // 6.2 Nombres d’oxydation
  { d: 6, o: "6.2", q: "Quel est le nombre d’oxydation du manganèse dans l’ion permanganate \\(\\ce{MnO4-}\\) ?", a: ["+VII", "+VIII", "+II", "−I"], c: 0, e: "x + 4 × (−2) = −1 ⇒ x = +7. Ne pas oublier la charge de l’ion (−1) : sans elle, on trouverait +VIII." },
  { d: 6, o: "6.2", q: "Quel est le nombre d’oxydation du chrome dans l’ion dichromate \\(\\ce{Cr2O7^2-}\\) ?", a: ["+VI", "+XII", "+III", "+VII"], c: 0, e: "2x + 7 × (−2) = −2 ⇒ 2x = 12 ⇒ x = +6 pour chaque atome de chrome. +XII est la somme des deux." },
  { d: 6, o: "6.2", q: "Quel est le nombre d’oxydation de l’oxygène dans l’eau oxygénée \\(\\ce{H2O2}\\) ?", a: ["−I", "−II", "0", "+I"], c: 0, e: "Dans un peroxyde, la liaison O–O est entre atomes identiques : 2 × (+1) + 2x = 0 ⇒ x = −1. C’est une exception à la règle O = −II." },
  { d: 6, o: "6.2", q: "Quel est le nombre d’oxydation de l’azote dans l’ion nitrate \\(\\ce{NO3-}\\) ?", a: ["+V", "+III", "−III", "+VI"], c: 0, e: "x + 3 × (−2) = −1 ⇒ x = +5. Dans l’ion nitrite NO₂⁻, il vaut +III ; dans NH₃, −III." },
  { d: 6, o: "6.2", q: "Quel est le nombre d’oxydation du carbone dans le méthane \\(\\ce{CH4}\\) ?", a: ["−IV", "+IV", "0", "−I"], c: 0, e: "x + 4 × (+1) = 0 ⇒ x = −4 : c’est l’état le plus réduit du carbone. Dans CO₂, il vaut +IV (le plus oxydé)." },
  { d: 6, o: "6.2", q: "Quel est le nombre d’oxydation du soufre dans l’ion sulfate \\(\\ce{SO4^2-}\\) ?", a: ["+VI", "+IV", "−II", "+VIII"], c: 0, e: "x + 4 × (−2) = −2 ⇒ x = +6." },
  { d: 6, o: "6.2", q: "On considère \\(\\ce{2 Fe^3+ + 2 I- -> 2 Fe^2+ + I2}\\). Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Le nombre d’oxydation du fer passe de +III à +II", "Le nombre d’oxydation de l’iode passe de −I à 0", "Les ions \\(\\ce{Fe^3+}\\) sont oxydés", "L’iode est réduit", "Aucun nombre d’oxydation ne varie"], c: [0, 1], x: ["Il diminue : le fer est réduit.", "Il augmente : l’iodure est oxydé.", "Ils sont réduits (n.o. diminue).", "Il est oxydé (n.o. augmente).", "C’est une réaction redox : les n.o. varient."], e: "Variation totale : 2 × (−1) pour le fer, 2 × (+1) pour l’iode : les électrons échangés se compensent." },
  { d: 6, o: "6.2", q: "À propos des règles de détermination des nombres d’oxydation, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Le nombre d’oxydation d’un atome dans un corps simple est 0", "La somme des nombres d’oxydation dans \\(\\ce{NH4+}\\) vaut +1", "L’hydrogène a un nombre d’oxydation de +I dans l’hydrure de sodium NaH", "L’oxygène a toujours un nombre d’oxydation de −II", "Le chlore a un nombre d’oxydation de +I dans l’ion \\(\\ce{Cl-}\\)"], c: [0, 1], x: ["O₂, Fe, H₂… : n.o. = 0.", "Somme = charge de l’ion : −3 + 4 × (+1) = +1.", "Dans un hydrure métallique, H vaut −I.", "Sauf peroxydes (−I) et combinaisons avec le fluor.", "Ion monoatomique : n.o. = charge = −I."], e: "Somme des n.o. = charge de l’espèce ; attention aux exceptions (peroxydes, hydrures)." },
  { d: 6, o: "6.2", q: "Lors de l’oxydation du méthanol \\(\\ce{CH3OH}\\) en méthanal \\(\\ce{HCHO}\\), comment évolue le nombre d’oxydation du carbone ?", a: ["Il passe de −II à 0", "Il passe de 0 à −II", "Il passe de −IV à +IV", "Il reste inchangé"], c: 0, e: "CH₃OH : x + 4 × (+1) − 2 = 0 ⇒ −II. HCHO : x + 2 − 2 = 0 ⇒ 0. Le n.o. augmente : c’est bien une oxydation. L’oxydation suivante en acide méthanoïque le porte à +II." },

  // 6.3 Équilibrage
  { d: 6, o: "6.3", q: "Combien d’électrons figurent dans la demi-équation du couple \\(\\ce{MnO4-}/\\ce{Mn^2+}\\) en milieu acide ?", a: ["5", "7", "2", "8"], c: 0, e: "\\(\\ce{MnO4- + 8 H+ + 5 e- = Mn^2+ + 4 H2O}\\). Vérifications : Mn passe de +VII à +II (5 électrons) ; charges : −1 + 8 − 5 = +2." },
  { d: 6, o: "6.3", q: "Combien d’ions \\(\\ce{H+}\\) faut-il dans la demi-équation du couple \\(\\ce{Cr2O7^2-}/\\ce{Cr^3+}\\) en milieu acide ?", a: ["14", "7", "6", "12"], c: 0, e: "\\(\\ce{Cr2O7^2- + 14 H+ + 6 e- = 2 Cr^3+ + 7 H2O}\\) : 7 O donnent 7 H₂O, soit 14 H à apporter par 14 H⁺." },
  { d: 6, o: "6.3", q: "Quelle est la demi-équation correcte du couple \\(\\ce{O2}/\\ce{H2O}\\) en milieu acide ?", a: ["\\(\\ce{O2 + 4 H+ + 4 e- = 2 H2O}\\)", "\\(\\ce{O2 + 2 H+ + 2 e- = H2O}\\)", "\\(\\ce{O2 + 4 e- = 2 H2O}\\)", "\\(\\ce{O2 + 4 H+ = 2 H2O + 4 e-}\\)"], c: 0, e: "2 O → 2 H₂O ; 4 H apportés par 4 H⁺ ; charges : +4 à gauche compensées par 4 e⁻. Les électrons se placent du côté de l’oxydant (O₂). C’est la réaction finale de la chaîne respiratoire." },
  { d: 6, o: "6.3", q: "Dans l’équation équilibrée de l’oxydation des ions \\(\\ce{Fe^2+}\\) par les ions permanganate en milieu acide, quel est le coefficient de \\(\\ce{Fe^2+}\\) pour un ion \\(\\ce{MnO4-}\\) ?", a: ["5", "1", "2", "8"], c: 0, e: "MnO₄⁻ capte 5 e⁻, chaque Fe²⁺ en cède 1 : il faut 5 Fe²⁺. \\(\\ce{MnO4- + 5 Fe^2+ + 8 H+ -> Mn^2+ + 5 Fe^3+ + 4 H2O}\\)." },
  { d: 6, o: "6.3", q: "Dans une équation d’oxydoréduction bilan correctement écrite, les électrons :", a: ["N’apparaissent pas", "Apparaissent du côté des réactifs", "Apparaissent du côté des produits", "Apparaissent des deux côtés"], c: 0, e: "On combine les demi-équations de sorte que les électrons cédés égalent les électrons captés : ils s’éliminent. Des électrons libres ne peuvent pas exister en solution." },
  { d: 6, o: "6.3", q: "Dans l’éthylotest, l’éthanol est oxydé en acide éthanoïque : \\(\\ce{CH3COOH + 4 H+ + 4 e- = CH3CH2OH + H2O}\\). Combien d’ions dichromate faut-il pour oxyder 3 molécules d’éthanol ?", a: ["2", "3", "1", "6"], c: 0, e: "3 éthanol cèdent 3 × 4 = 12 électrons ; chaque dichromate en capte 6 : 12 / 6 = 2. Bilan : \\(\\ce{2 Cr2O7^2- + 3 CH3CH2OH + 16 H+ -> 4 Cr^3+ + 3 CH3COOH + 11 H2O}\\)." },
  { d: 6, o: "6.3", q: "On titre 20,0 mL d’une solution de \\(\\ce{Fe^2+}\\) par du permanganate à 0,010 mol·L⁻¹ ; l’équivalence est obtenue pour 16,0 mL. Quelle est la concentration en \\(\\ce{Fe^2+}\\) ?", a: ["0,040 mol·L⁻¹", "0,0080 mol·L⁻¹", "0,0016 mol·L⁻¹", "0,20 mol·L⁻¹"], c: 0, e: "n(MnO₄⁻) = 0,010 × 16,0 × 10⁻³ = 1,6 × 10⁻⁴ mol ; n(Fe²⁺) = 5 × 1,6 × 10⁻⁴ = 8,0 × 10⁻⁴ mol ; C = 8,0 × 10⁻⁴ / 0,0200 = 0,040 mol·L⁻¹. Oublier le facteur 5 donne 0,0080." },
  { d: 6, o: "6.3", q: "À propos de la méthode d’écriture des demi-équations électroniques en milieu acide, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["On équilibre l’oxygène avec des molécules d’eau", "On équilibre l’hydrogène avec des ions \\(\\ce{H+}\\)", "Les électrons se placent du côté de l’oxydant", "On équilibre les charges en ajoutant des molécules d’eau", "En milieu basique, on conserve les \\(\\ce{H+}\\) dans l’équation finale"], c: [0, 1, 2], x: ["Étape 3.", "Étape 4.", "Ox + n e⁻ = Red.", "Les charges s’équilibrent avec les électrons ; l’eau est neutre.", "On les neutralise par des HO⁻ (H⁺ + HO⁻ → H₂O)."], e: "Ordre : élément principal, O (H₂O), H (H⁺), charges (e⁻)." },
  { d: 6, o: "6.3", q: "On considère \\(\\ce{Cr2O7^2- + 6 I- + 14 H+ -> 2 Cr^3+ + 3 I2 + 7 H2O}\\). Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["L’équation est équilibrée en charges (+6 de chaque côté)", "6 électrons sont échangés", "Les ions iodure sont réduits", "Le chrome passe du nombre d’oxydation +III à +VI", "La réaction se déroule en milieu basique"], c: [0, 1], x: ["−2 − 6 + 14 = +6 ; 2 × (+3) = +6.", "Le dichromate capte 6 e⁻, 6 I⁻ en cèdent 6.", "Ils sont oxydés (−I → 0).", "Il passe de +VI à +III (réduction).", "La présence de H⁺ indique un milieu acide."], e: "Vérifier une équation redox : éléments, charges et électrons échangés." },
  { d: 6, o: "6.3", q: "Quelle est l’équation équilibrée de l’oxydation des ions iodure par l’eau oxygénée en milieu acide ?", a: ["\\(\\ce{H2O2 + 2 I- + 2 H+ -> I2 + 2 H2O}\\)", "\\(\\ce{H2O2 + I- + H+ -> I2 + H2O}\\)", "\\(\\ce{H2O2 + 2 I- -> I2 + 2 H2O}\\)", "\\(\\ce{2 H2O2 + 2 I- -> I2 + 2 H2O + O2}\\)"], c: 0, e: "\\(\\ce{H2O2 + 2 H+ + 2 e- = 2 H2O}\\) et \\(\\ce{2 I- = I2 + 2 e-}\\) ; on additionne. Vérification des charges : −2 + 2 = 0 à gauche, 0 à droite. La troisième équation n’équilibre ni H ni les charges." },

  // 6.4 Électrochimie
  { d: 6, o: "6.4", q: "Dans une pile, qu’est-ce que l’anode ?", a: ["L’électrode où se produit l’oxydation ; c’est le pôle −", "L’électrode où se produit la réduction ; c’est le pôle +", "L’électrode où se produit l’oxydation ; c’est le pôle +", "Le pont salin"], c: 0, e: "Anode = oxydation (moyen mnémotechnique : deux voyelles). Dans une pile, elle libère des électrons dans le circuit : c’est le pôle négatif." },
  { d: 6, o: "6.4", q: "Quelle est la force électromotrice standard de la pile Daniell (E°(Cu²⁺/Cu) = +0,34 V ; E°(Zn²⁺/Zn) = −0,76 V) ?", a: ["1,10 V", "0,42 V", "−1,10 V", "0,26 V"], c: 0, e: "e° = E°₊ − E°₋ = 0,34 − (−0,76) = 1,10 V. La fem d’une pile qui débite est positive ; 0,42 correspond à une erreur de signe." },
  { d: 6, o: "6.4", q: "Avec les potentiels standard suivants : MnO₄⁻/Mn²⁺ +1,51 V ; Fe³⁺/Fe²⁺ +0,77 V ; Cu²⁺/Cu +0,34 V ; Zn²⁺/Zn −0,76 V, quel est l’oxydant le plus fort ?", a: ["\\(\\ce{MnO4-}\\)", "\\(\\ce{Fe^3+}\\)", "\\(\\ce{Cu^2+}\\)", "\\(\\ce{Zn}\\)"], c: 0, e: "L’oxydant le plus fort est celui du couple de plus haut potentiel. Zn n’est pas un oxydant mais le réducteur le plus fort de la liste." },
  { d: 6, o: "6.4", q: "Avec E°(Fe³⁺/Fe²⁺) = +0,77 V, E°(I₂/I⁻) = +0,54 V, E°(Cu²⁺/Cu) = +0,34 V, E°(Zn²⁺/Zn) = −0,76 V et E°(H⁺/H₂) = 0 V, quelle réaction est spontanée dans les conditions standard ?", a: ["\\(\\ce{2 Fe^3+ + 2 I- -> 2 Fe^2+ + I2}\\)", "\\(\\ce{Cu + Zn^2+ -> Cu^2+ + Zn}\\)", "\\(\\ce{2 Fe^2+ + I2 -> 2 Fe^3+ + 2 I-}\\)", "\\(\\ce{Cu + 2 H+ -> Cu^2+ + H2}\\)"], c: 0, e: "Règle du gamma : l’oxydant le plus fort réagit avec le réducteur le plus fort. Fe³⁺ (0,77 V) oxyde I⁻ (0,54 V). Le cuivre (0,34 V) ne peut réduire ni Zn²⁺ ni H⁺ (potentiels plus bas)." },
  { d: 6, o: "6.4", q: "Quel est le potentiel à 25 °C d’une électrode de cuivre plongeant dans une solution où \\([\\ce{Cu^2+}] = 1{,}0 \\times 10^{-3}\\) mol·L⁻¹ ? (E° = 0,34 V)", a: ["0,25 V", "0,43 V", "0,34 V", "0,16 V"], c: 0, e: "\\(E = 0{,}34 + \\dfrac{0{,}059}{2}\\log(10^{-3}) = 0{,}34 - 0{,}089 \\approx 0{,}25\\) V. Oublier le n = 2 donne 0,16 V ; une erreur de signe 0,43 V. Le métal solide n’apparaît pas." },
  { d: 6, o: "6.4", q: "Quelle est l’enthalpie libre standard de la réaction d’une pile Daniell (n = 2, e° = 1,10 V, F = 96 485 C·mol⁻¹) ?", a: ["−212 kJ·mol⁻¹", "+212 kJ·mol⁻¹", "−106 kJ·mol⁻¹", "−212 J·mol⁻¹"], c: 0, e: "\\(\\Delta_r G° = -nFe° = -2 \\times 96\\,485 \\times 1{,}10 \\approx -212\\,000\\) J·mol⁻¹ = −212 kJ·mol⁻¹. Négatif : réaction spontanée. −106 oublie le n = 2." },
  { d: 6, o: "6.4", q: "Quel est le rôle du pont salin dans une pile ?", a: ["Assurer la neutralité électrique des solutions en permettant la circulation des ions", "Faire circuler les électrons entre les deux compartiments", "Catalyser la réaction d’oxydoréduction", "Fournir les électrons de la réaction"], c: 0, e: "Les électrons circulent dans le circuit extérieur ; dans la pile, le courant est assuré par des ions qui migrent dans le pont salin et compensent l’apparition ou la disparition de charges." },
  { d: 6, o: "6.4", q: "Quelle électrode sert de référence pour mesurer les potentiels standard ?", a: ["L’électrode standard à hydrogène, de potentiel 0,00 V par convention", "L’électrode de cuivre, de potentiel 0,34 V", "L’électrode de verre, de potentiel 7,00 V", "L’électrode de zinc, de potentiel 0,00 V"], c: 0, e: "On mesure la différence de potentiel entre l’électrode étudiée et l’électrode standard à hydrogène (couple H⁺/H₂), dont le potentiel standard est fixé à 0 V." },
  { d: 6, o: "6.4", q: "À propos de la pile Daniell \\(\\ce{Zn | Zn^2+ || Cu^2+ | Cu}\\) en fonctionnement, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["L’électrode de zinc est l’anode", "Dans le circuit extérieur, les électrons vont du zinc vers le cuivre", "L’électrode de cuivre est le pôle −", "La masse de l’électrode de cuivre diminue", "La fem augmente au fur et à mesure que la pile débite"], c: [0, 1], x: ["Le zinc y est oxydé.", "De l’anode (−) vers la cathode (+).", "C’est le pôle + (cathode, réduction).", "Du cuivre s’y dépose : sa masse augmente.", "Elle diminue jusqu’à 0 quand l’équilibre est atteint."], e: "Anode (Zn) : Zn → Zn²⁺ + 2 e⁻ ; cathode (Cu) : Cu²⁺ + 2 e⁻ → Cu." },
  { d: 6, o: "6.4", q: "À propos de l’équation de Nernst, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["À 25 °C, \\(E = E° + \\dfrac{0{,}059}{n}\\log\\dfrac{[\\ce{Ox}]}{[\\ce{Red}]}\\)", "Le potentiel du couple \\(\\ce{MnO4-}/\\ce{Mn^2+}\\) dépend du pH", "Les solides figurent dans le terme logarithmique", "Multiplier [Ox] par 10 augmente E de 0,059 V quel que soit n", "Quand une pile Daniell est usée, sa fem vaut encore 1,10 V"], c: [0, 1], x: ["Forme usuelle à 25 °C.", "Les H⁺ apparaissent avec la puissance 8.", "Leur activité vaut 1.", "L’augmentation vaut 0,059/n V.", "À l’équilibre, la fem est nulle."], e: "Nernst relie le potentiel aux concentrations (et au pH quand des H⁺ interviennent)." },
  { d: 6, o: "6.4", q: "Dans la chaîne respiratoire mitochondriale, dans quel sens les électrons sont-ils transférés ?", a: ["Du NADH (E°′ = −0,32 V) vers le dioxygène (E°′ = +0,82 V)", "Du dioxygène vers le NADH", "De l’eau vers le \\(\\ce{NAD+}\\)", "Il n’y a pas de transfert d’électrons"], c: 0, e: "Les électrons vont spontanément du couple de plus bas potentiel (réducteur NADH) vers le couple de plus haut potentiel (oxydant O₂). ΔE°′ = 1,14 V, soit ΔG°′ ≈ −220 kJ·mol⁻¹, énergie utilisée pour produire de l’ATP." },
  { d: 6, o: "6.4", q: "À propos des applications biologiques et médicales de l’électrochimie, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Le potentiel d’équilibre d’un ion à travers une membrane se calcule avec l’équation de Nernst", "Beaucoup de glucomètres utilisent une électrode enzymatique à glucose oxydase", "Dans la chaîne respiratoire, le dioxygène est le réducteur final", "Le NADH est un oxydant fort", "Le pH-mètre mesure le pH grâce à une électrode de cuivre"], c: [0, 1], x: ["E_ion = (RT/zF) ln([ion]ext/[ion]int).", "L’oxydation du glucose produit un signal électrique proportionnel à la glycémie.", "O₂ est l’accepteur final d’électrons : l’oxydant final.", "C’est un réducteur (E°′ très bas).", "Il utilise une électrode de verre."], e: "Nernst sert aussi bien pour les piles que pour les potentiels membranaires et les capteurs." },
  { d: 6, o: "6.4", q: "Une lame de fer (E°(Fe²⁺/Fe) = −0,44 V) est plongée dans de l’acide chlorhydrique (E°(H⁺/H₂) = 0 V). Que se passe-t-il ?", a: ["Le fer est oxydé en \\(\\ce{Fe^2+}\\) avec dégagement de dihydrogène", "Rien, car le fer est un métal", "Les ions \\(\\ce{H+}\\) sont oxydés en \\(\\ce{H2}\\)", "Les ions \\(\\ce{Fe^2+}\\) sont réduits en fer"], c: 0, e: "H⁺ (0 V) est un oxydant plus fort que Fe²⁺ (−0,44 V) : H⁺ oxyde Fe. \\(\\ce{Fe + 2 H+ -> Fe^2+ + H2}\\). Les H⁺ sont réduits (et non oxydés) en H₂." },

  // ===================== Domaine 7 — Chimie organique (84) =====================
  // 7.1 Structure du carbone
  { d: 7, o: "7.1", q: "Quelle est l’hybridation du carbone dans le méthane \\(\\ce{CH4}\\) ?", a: ["sp³", "sp²", "sp", "Aucune"], c: 0, e: "4 liaisons σ et aucun doublet non liant : 4 domaines → sp³, géométrie tétraédrique (109,5°)." },
  { d: 7, o: "7.1", q: "Quelle est l’hybridation des carbones de l’éthène \\(\\ce{CH2=CH2}\\) ?", a: ["sp²", "sp³", "sp", "sp³d"], c: 0, e: "Chaque carbone forme 3 liaisons σ (2 C–H, 1 C–C) et une liaison π avec une orbitale p non hybridée : sp², trigonal plan." },
  { d: 7, o: "7.1", q: "Quelle est l’hybridation des carbones de l’éthyne \\(\\ce{HC#CH}\\) ?", a: ["sp", "sp²", "sp³", "Ils ne sont pas hybridés"], c: 0, e: "Triple liaison : 2 domaines σ par carbone (C–H et C–C) + 2 liaisons π : sp, linéaire (180°)." },
  { d: 7, o: "7.1", q: "Quel angle de liaison est associé à un carbone hybridé sp² ?", a: ["120°", "109,5°", "180°", "90°"], c: 0, e: "3 orbitales hybrides dans un plan, à 120° les unes des autres. 109,5° : sp³ ; 180° : sp." },
  { d: 7, o: "7.1", q: "Quelle est l’hybridation de l’atome de carbone du groupe C=O de la propanone \\(\\ce{CH3COCH3}\\) ?", a: ["sp²", "sp³", "sp", "sp³ car il est lié à deux méthyles"], c: 0, e: "Le carbone du carbonyle forme 3 liaisons σ et une liaison π avec l’oxygène : sp². Les deux carbones des méthyles, eux, sont sp³." },
  { d: 7, o: "7.1", q: "De quoi est constituée une liaison triple C≡C ?", a: ["Une liaison σ et deux liaisons π", "Trois liaisons σ", "Deux liaisons σ et une liaison π", "Trois liaisons π"], c: 0, e: "Il ne peut y avoir qu’une liaison σ (recouvrement axial) entre deux atomes ; les deux autres sont des liaisons π (recouvrements latéraux perpendiculaires)." },
  { d: 7, o: "7.1", q: "Autour de quel type de liaison la libre rotation est-elle possible à température ambiante ?", a: ["Une liaison simple C–C", "Une liaison double C=C", "Une liaison triple C≡C", "Autour de toutes les liaisons"], c: 0, e: "La liaison σ est symétrique autour de son axe : la rotation ne la rompt pas. La liaison π d’une double liaison serait rompue par une rotation, qui est donc bloquée (origine de l’isomérie Z/E)." },
  { d: 7, o: "7.1", q: "Une formule topologique est une ligne brisée de 4 segments (5 sommets), sans hétéroatome ni liaison multiple. Quelle molécule représente-t-elle ?", a: ["Le pentane \\(\\ce{C5H12}\\)", "Le butane \\(\\ce{C4H10}\\)", "Le pentène \\(\\ce{C5H10}\\)", "Le cyclopentane \\(\\ce{C5H10}\\)"], c: 0, e: "Chaque sommet et chaque extrémité est un carbone : 5 carbones. Les H sont implicites (4 liaisons par C) : chaîne ouverte saturée → C₅H₁₂." },
  { d: 7, o: "7.1", q: "À propos du carbone dans les molécules organiques, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Il forme 4 liaisons covalentes : il est tétravalent", "Il possède 4 électrons de valence", "Il porte deux doublets non liants dans le méthane", "Il ne peut pas se lier à un autre atome de carbone", "Le carbone d’un alcane est hybridé sp²"], c: [0, 1], x: ["Il complète ainsi son octet.", "Configuration 2s² 2p².", "Ses 4 doublets sont tous liants.", "Au contraire, il forme des chaînes et des cycles.", "Il est sp³ (liaisons simples uniquement)."], e: "Carbone : 4 électrons de valence, 4 liaisons, pas de doublet non liant dans les molécules neutres usuelles." },
  { d: 7, o: "7.1", q: "À propos des représentations moléculaires, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["En représentation de Cram, un triangle plein indique une liaison dirigée vers l’avant", "En projection de Fischer, les liaisons horizontales pointent vers l’observateur", "La projection de Newman permet de visualiser les conformations", "En formule topologique, les atomes H liés aux oxygènes sont omis", "Deux conformations sont deux molécules différentes que l’on peut isoler"], c: [0, 1, 2], x: ["Le triangle hachuré indique l’arrière.", "Les verticales pointent vers l’arrière.", "Décalée, éclipsée… vues selon l’axe C–C.", "Seuls les H portés par les carbones sont omis ; on écrit OH.", "Elles s’interconvertissent par simple rotation."], e: "Cram, Newman, Fischer et formule topologique : quatre façons de représenter la même molécule." },
  { d: 7, o: "7.1", q: "À propos des liaisons simples et multiples, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Une liaison π résulte du recouvrement latéral d’orbitales p", "La double liaison C=C bloque la rotation", "Une double liaison C=C est exactement deux fois plus forte qu’une simple C–C", "Un carbone hybridé sp³ est plan", "La liaison σ est plus faible que la liaison π"], c: [0, 1], x: ["Recouvrement de part et d’autre de l’axe.", "Tourner romprait la liaison π.", "≈ 614 contre 2 × 347 = 694 kJ·mol⁻¹ : moins du double.", "Il est tétraédrique.", "C’est l’inverse : la π est plus faible, donc plus réactive."], e: "Double liaison = σ + π ; la liaison π, plus faible, est le site réactif des alcènes." },
  { d: 7, o: "7.1", q: "À propos des longueurs et énergies des liaisons carbone-carbone, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["La liaison C≡C est plus courte que la liaison C=C", "La liaison C=C est plus courte que la liaison C–C", "La liaison C–C est la plus courte des trois", "Les trois liaisons ont la même longueur", "Une liaison triple est plus faible qu’une liaison double"], c: [0, 1], x: ["120 pm contre 134 pm.", "134 pm contre 154 pm.", "C’est la plus longue (154 pm).", "Plus il y a de liaisons, plus les atomes sont rapprochés.", "Elle est plus forte (≈ 839 contre 614 kJ·mol⁻¹)."], e: "Plus l’ordre de liaison est élevé, plus la liaison est courte et forte." },

  // 7.2 Fonctions organiques
  { d: 7, o: "7.2", q: "À quelle famille appartient \\(\\ce{CH3-CH2-OH}\\) ?", a: ["Alcool", "Éther", "Aldéhyde", "Acide carboxylique"], c: 0, e: "Groupe hydroxyle –OH porté par un carbone sp³ : alcool (éthanol)." },
  { d: 7, o: "7.2", q: "À quelle famille appartient l’éthanal \\(\\ce{CH3-CHO}\\) ?", a: ["Aldéhyde", "Cétone", "Alcool", "Ester"], c: 0, e: "Groupe carbonyle en bout de chaîne, le carbone fonctionnel portant un H : aldéhyde." },
  { d: 7, o: "7.2", q: "À quelle famille appartient la propanone \\(\\ce{CH3-CO-CH3}\\) ?", a: ["Cétone", "Aldéhyde", "Éther", "Ester"], c: 0, e: "Groupe carbonyle entre deux atomes de carbone : cétone (l’acétone)." },
  { d: 7, o: "7.2", q: "À quelle famille appartient \\(\\ce{CH3-COO-CH3}\\) ?", a: ["Ester", "Éther", "Acide carboxylique", "Cétone"], c: 0, e: "Un carbonyle lié à un oxygène lui-même lié à un carbone (–COO–C) : ester (éthanoate de méthyle)." },
  { d: 7, o: "7.2", q: "À quelle famille appartient \\(\\ce{CH3-O-CH2-CH3}\\) ?", a: ["Éther", "Ester", "Alcool", "Cétone"], c: 0, e: "Un oxygène entre deux carbones, sans carbonyle : éther (méthoxyéthane)." },
  { d: 7, o: "7.2", q: "À quelle famille appartient \\(\\ce{CH3-CO-NH2}\\) ?", a: ["Amide", "Amine", "Cétone", "Ester"], c: 0, e: "Carbonyle lié directement à un azote : amide (éthanamide). C’est la fonction de la liaison peptidique." },
  { d: 7, o: "7.2", q: "À quelle famille appartient \\(\\ce{CH3-CH2-NH2}\\) ?", a: ["Amine", "Amide", "Nitrile", "Alcool"], c: 0, e: "Azote lié à des carbones sp³, sans carbonyle voisin : amine primaire (éthanamine)." },
  { d: 7, o: "7.2", q: "Quel groupe caractéristique possède l’acide acétique \\(\\ce{CH3COOH}\\) ?", a: ["Un groupe carboxyle", "Un groupe ester", "Un groupe hydroxyle d’alcool seulement", "Un groupe carbonyle de cétone"], c: 0, e: "–COOH : groupe carboxyle (C=O et OH sur le même carbone), caractéristique des acides carboxyliques, acides faibles (pKa ≈ 4,8 pour l’acide acétique)." },
  { d: 7, o: "7.2", q: "Quelle formule brute correspond à un alcane non cyclique à 6 carbones ?", a: ["\\(\\ce{C6H14}\\)", "\\(\\ce{C6H12}\\)", "\\(\\ce{C6H10}\\)", "\\(\\ce{C6H6}\\)"], c: 0, e: "Alcane : CₙH₂ₙ₊₂ → C₆H₁₄. C₆H₁₂ correspond à un alcène ou un cycloalcane, C₆H₁₀ à un alcyne." },
  { d: 7, o: "7.2", q: "Quelle est la formule générale d’un alcyne non cyclique comportant une seule triple liaison ?", a: ["\\(\\ce{C_nH_{2n-2}}\\)", "\\(\\ce{C_nH_{2n+2}}\\)", "\\(\\ce{C_nH_{2n}}\\)", "\\(\\ce{C_nH_n}\\)"], c: 0, e: "Chaque liaison π supplémentaire retire 2 H par rapport à l’alcane : alcène CₙH₂ₙ, alcyne CₙH₂ₙ₋₂." },
  { d: 7, o: "7.2", q: "Parmi ces composés, lequel est un alcène ?", a: ["\\(\\ce{CH2=CH-CH3}\\)", "\\(\\ce{CH3-CH2-CH3}\\)", "\\(\\ce{HC#C-CH3}\\)", "\\(\\ce{CH3-CO-CH3}\\)"], c: 0, e: "Le propène possède une double liaison C=C. Les autres sont un alcane (propane), un alcyne (propyne) et une cétone (propanone)." },
  { d: 7, o: "7.2", q: "À propos de la classe des alcools et des amines, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Le propan-2-ol est un alcool secondaire", "\\(\\ce{(CH3)2NH}\\) est une amine secondaire", "\\(\\ce{(CH3)3C-NH2}\\) est une amine tertiaire", "\\(\\ce{(CH3)3C-OH}\\) est un alcool primaire", "Le méthanol est un alcool tertiaire"], c: [0, 1], x: ["Le carbone porteur du OH est lié à 2 carbones.", "L’azote porte 2 carbones.", "L’azote ne porte qu’un carbone : amine primaire.", "Le carbone porteur du OH est lié à 3 carbones : tertiaire.", "Le carbone du méthanol n’est lié à aucun autre carbone ; on le range avec les primaires."], e: "Alcool : on compte les carbones liés au carbone fonctionnel ; amine : les carbones liés à l’azote." },
  { d: 7, o: "7.2", q: "Quelle est la classe de l’amine \\(\\ce{(CH3)3C-NH2}\\) (tert-butylamine) ?", a: ["Primaire", "Secondaire", "Tertiaire", "Quaternaire"], c: 0, e: "Pour une amine, on compte les carbones liés à l’azote : un seul ici, donc amine primaire, même si ce carbone est lui-même tertiaire. Piège classique avec la classe des alcools." },
  { d: 7, o: "7.2", q: "Parmi ces composés, lequel a des propriétés basiques marquées en solution aqueuse ?", a: ["La méthylamine \\(\\ce{CH3NH2}\\)", "L’éthanamide \\(\\ce{CH3CONH2}\\)", "L’éthanol \\(\\ce{CH3CH2OH}\\)", "L’acide éthanoïque \\(\\ce{CH3COOH}\\)"], c: 0, e: "Le doublet non liant de l’azote d’une amine capte un proton (pKa de CH₃NH₃⁺ ≈ 10,6). Dans un amide, ce doublet est délocalisé vers C=O : pas de basicité notable." },
  { d: 7, o: "7.2", q: "Quels groupes caractéristiques la molécule \\(\\ce{HO-CH2-CH2-COOH}\\) contient-elle ? (Choisissez 2 réponses)", a: ["Un groupe alcool", "Un groupe acide carboxylique", "Un groupe ester", "Un groupe aldéhyde", "Un groupe cétone"], c: [0, 1], x: ["HO–CH₂– : hydroxyle sur un carbone sp³.", "–COOH en bout de chaîne.", "Aucun enchaînement –COO–C.", "Pas de –CHO.", "Pas de carbonyle entre deux carbones."], e: "C’est l’acide 3-hydroxypropanoïque : fonctions alcool et acide carboxylique." },
  { d: 7, o: "7.2", q: "Quels groupes caractéristiques la molécule \\(\\ce{CH3-CO-NH-CH2-CH2-NH2}\\) contient-elle ? (Choisissez 2 réponses)", a: ["Un groupe amide", "Un groupe amine primaire", "Un groupe cétone", "Un groupe ester", "Un groupe amine tertiaire"], c: [0, 1], x: ["CH₃–CO–NH– : carbonyle lié à N.", "–CH₂–NH₂ : N lié à un seul carbone.", "Le carbonyle est lié à N : c’est un amide, pas une cétone.", "Pas d’enchaînement –COO–.", "Aucun azote n’est lié à trois carbones."], e: "Un carbonyle lié à un azote définit un amide ; un azote sans carbonyle voisin, une amine." },
  { d: 7, o: "7.2", q: "Quelles familles de composés contiennent un groupe carbonyle C=O ? (Choisissez 3 réponses)", a: ["Les aldéhydes", "Les esters", "Les amides", "Les éthers", "Les amines"], c: [0, 1, 2], x: ["R–CHO.", "R–COO–R′.", "R–CO–NH₂.", "R–O–R′ : pas de C=O.", "R–NH₂ : pas de C=O."], e: "C=O : aldéhydes, cétones, acides carboxyliques, esters, amides." },
  { d: 7, o: "7.2", q: "À quels composés peut correspondre la formule brute \\(\\ce{C3H6O}\\) ? (Choisissez 2 réponses)", a: ["Au propanal", "À la propanone", "Au propan-1-ol", "À l’acide propanoïque", "Au méthoxyéthane"], c: [0, 1], x: ["CH₃CH₂CHO : C₃H₆O.", "CH₃COCH₃ : C₃H₆O.", "CH₃CH₂CH₂OH : C₃H₈O.", "CH₃CH₂COOH : C₃H₆O₂.", "CH₃OCH₂CH₃ : C₃H₈O."], e: "Aldéhydes et cétones de même nombre de carbones sont isomères de fonction." },

  // 7.3 Nomenclature
  { d: 7, o: "7.3", q: "Quel est le nom de \\(\\ce{CH3-CH2-CH2-CH3}\\) ?", a: ["Butane", "Propane", "Butène", "Méthylpropane"], c: 0, e: "4 carbones (racine but-), uniquement des liaisons simples (suffixe -ane) : butane." },
  { d: 7, o: "7.3", q: "Quel est le nom de \\(\\ce{CH3-CH(CH3)-CH2-CH3}\\) ?", a: ["2-méthylbutane", "3-méthylbutane", "Pentane", "2-éthylpropane"], c: 0, e: "Chaîne principale de 4 carbones, méthyle en position 2 en numérotant par l’extrémité la plus proche (et non 3). « 2-éthylpropane » ne choisit pas la chaîne la plus longue." },
  { d: 7, o: "7.3", q: "Quel est le nom de \\(\\ce{CH3-CH(OH)-CH3}\\) ?", a: ["Propan-2-ol", "Propan-1-ol", "Propanone", "2-hydroxypropane"], c: 0, e: "3 carbones, fonction alcool (suffixe -ol) sur le carbone 2 : propan-2-ol. La fonction principale se nomme en suffixe, pas en préfixe." },
  { d: 7, o: "7.3", q: "Quel est le nom de \\(\\ce{CH3-CH2-CO-CH2-CH3}\\) ?", a: ["Pentan-3-one", "Pentan-2-one", "Pentanal", "Pentan-3-ol"], c: 0, e: "5 carbones, groupe carbonyle entre deux carbones (cétone, -one) sur le carbone 3 quel que soit le sens de numérotation." },
  { d: 7, o: "7.3", q: "Quel est le nom de \\(\\ce{CH3-CO-CH2-CH3}\\) ?", a: ["Butanone", "Butanal", "Propanone", "Butan-3-one"], c: 0, e: "4 carbones, cétone en position 2 (plus petit indice) : butan-2-one, souvent appelée simplement butanone car aucune autre position n’est possible pour une cétone à 4 carbones." },
  { d: 7, o: "7.3", q: "Quel est le nom de \\(\\ce{CH3-CH2-COOH}\\) ?", a: ["Acide propanoïque", "Acide éthanoïque", "Propanal", "Propanoate"], c: 0, e: "3 carbones en comptant celui du COOH (C1) : acide propanoïque." },
  { d: 7, o: "7.3", q: "Quel est le nom de l’ester \\(\\ce{HCOO-CH2-CH3}\\) ?", a: ["Méthanoate d’éthyle", "Éthanoate de méthyle", "Propanoate", "Éthoxyméthanal"], c: 0, e: "Partie acide HCOO– (1 carbone) → méthanoate ; partie alcool –CH₂CH₃ → éthyle. Méthanoate d’éthyle." },
  { d: 7, o: "7.3", q: "Quel est le nom de \\(\\ce{CH3-CH2-CH2-NH2}\\) ?", a: ["Propan-1-amine", "Propanamide", "Propan-2-amine", "Aminopropanal"], c: 0, e: "3 carbones, groupe amine sur le carbone 1 : propan-1-amine (propylamine). Propanamide serait CH₃CH₂CONH₂." },
  { d: 7, o: "7.3", q: "Quel est le nom de \\(\\ce{CH2=CH-CH2-CH3}\\) ?", a: ["But-1-ène", "But-3-ène", "But-2-ène", "Butane"], c: 0, e: "On numérote pour donner le plus petit indice à la double liaison : elle part du carbone 1." },
  { d: 7, o: "7.3", q: "Quel est le nom correct de \\(\\ce{CH3-CH(CH3)-CH(C2H5)-CH2-CH3}\\) ?", a: ["3-éthyl-2-méthylpentane", "2-méthyl-3-éthylpentane", "3-éthyl-4-méthylpentane", "2-méthyl-3-propylbutane"], c: 0, e: "Chaîne principale de 5 carbones ; substituants en 2 et 3 (et non 3 et 4) ; ordre alphabétique : éthyl avant méthyl. « 2-méthyl-3-éthyl » respecte les indices mais pas l’ordre alphabétique." },
  { d: 7, o: "7.3", q: "Quel est le nom de l’ester \\(\\ce{CH3-COO-CH3}\\) ?", a: ["Éthanoate de méthyle", "Méthanoate d’éthyle", "Méthoxyéthanone", "Propanoate"], c: 0, e: "Partie acide CH₃COO– (2 carbones) → éthanoate ; partie alcool –CH₃ → méthyle. Inverser les deux parties est le piège classique." },
  { d: 7, o: "7.3", q: "On considère \\(\\ce{CH3-CH2-CH(CH3)-CH2-OH}\\). Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["La chaîne principale compte 4 carbones", "Son nom est 2-méthylbutan-1-ol", "Son nom est 3-méthylbutan-1-ol", "C’est un alcool secondaire", "Son nom est 2-méthylbutan-4-ol"], c: [0, 1], x: ["C1 (CH₂OH) à C4 (CH₃).", "On numérote depuis le carbone porteur du OH ; méthyle en 2.", "Le méthyle est sur le carbone voisin de CH₂OH : position 2.", "Le carbone porteur du OH n’est lié qu’à un carbone : primaire.", "Le groupe principal doit avoir le plus petit indice."], e: "La fonction principale fixe le sens de numérotation." },
  { d: 7, o: "7.3", q: "À propos des règles de nomenclature, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Le carbone d’un aldéhyde porte toujours le numéro 1, sans qu’on l’indique", "Les substituants se citent par ordre alphabétique, sans tenir compte de di-, tri-", "On attribue le plus petit indice au groupe caractéristique principal", "La chaîne principale est celle écrite horizontalement", "Dans le nom d’un ester, on cite d’abord la partie alcool"], c: [0, 1, 2], x: ["Propanal, et non propan-1-al.", "3-éthyl-2,2-diméthyl… : é avant m.", "Avant les insaturations et les substituants.", "C’est la plus longue qui porte la fonction principale, quel que soit le dessin.", "On cite d’abord la partie acide (…-oate), puis l’alcool (…-yle)."], e: "Chaîne principale, numérotation, puis ordre alphabétique des substituants." },
  { d: 7, o: "7.3", q: "Quels couples formule/nom sont corrects ? (Choisissez 3 réponses)", a: ["\\(\\ce{CH3CH2CHO}\\) : propanal", "\\(\\ce{CH3COCH3}\\) : propanone", "\\(\\ce{CH3CH2OCH3}\\) : méthoxyéthane", "\\(\\ce{CH3CH2COOCH3}\\) : méthanoate de propyle", "\\(\\ce{CH3CH(NH2)CH3}\\) : propan-1-amine"], c: [0, 1, 2], x: ["Aldéhyde à 3 carbones.", "Cétone à 3 carbones.", "Groupe méthoxy sur une chaîne à 2 carbones.", "C’est le propanoate de méthyle (acide à 3 C, alcool à 1 C).", "L’amine est sur le carbone 2 : propan-2-amine."], e: "Suffixes : -al, -one, -oate de …-yle, -amine ; éthers : alcoxyalcane." },

  // 7.4 Isomérie
  { d: 7, o: "7.4", q: "Quel type d’isomérie relie le butane et le 2-méthylpropane (\\(\\ce{C4H10}\\)) ?", a: ["Isomérie de constitution de chaîne", "Isomérie de position", "Isomérie de fonction", "Énantiomérie"], c: 0, e: "Même formule brute, squelettes carbonés différents (linéaire contre ramifié) : isomères de constitution de chaîne." },
  { d: 7, o: "7.4", q: "Quel type d’isomérie relie le propan-1-ol et le propan-2-ol ?", a: ["Isomérie de constitution de position", "Isomérie de constitution de fonction", "Stéréoisomérie Z/E", "Énantiomérie"], c: 0, e: "Même squelette, même fonction alcool, mais placée sur un carbone différent : isomérie de position." },
  { d: 7, o: "7.4", q: "Quel type d’isomérie relie l’éthanol \\(\\ce{CH3CH2OH}\\) et le méthoxyméthane \\(\\ce{CH3OCH3}\\) ?", a: ["Isomérie de constitution de fonction", "Isomérie de chaîne", "Diastéréoisomérie", "Aucune, ils n’ont pas la même formule brute"], c: 0, e: "Tous deux ont pour formule C₂H₆O, mais l’un est un alcool et l’autre un éther : isomères de fonction." },
  { d: 7, o: "7.4", q: "Qu’est-ce qu’un carbone asymétrique ?", a: ["Un carbone tétraédrique lié à quatre substituants tous différents", "Un carbone engagé dans une double liaison", "Un carbone lié à quatre atomes d’hydrogène", "Un carbone lié à au moins un hétéroatome"], c: 0, e: "Le carbone asymétrique (stéréocentre) est sp³ et porte 4 groupes différents : il n’est pas superposable à son image dans un miroir." },
  { d: 7, o: "7.4", q: "Parmi ces molécules, laquelle possède un carbone asymétrique ?", a: ["Le butan-2-ol", "Le propan-2-ol", "L’éthanol", "Le 2-méthylpropane"], c: 0, e: "Dans le butan-2-ol, C2 porte H, OH, CH₃ et C₂H₅ : 4 groupes différents. Dans le propan-2-ol, C2 porte deux CH₃ identiques." },
  { d: 7, o: "7.4", q: "Combien de stéréoisomères de configuration une molécule à deux carbones asymétriques peut-elle posséder au maximum ?", a: ["4", "2", "3", "8"], c: 0, e: "Au plus 2ⁿ = 2² = 4 stéréoisomères. On en trouve moins (3) s’il existe une forme méso." },
  { d: 7, o: "7.4", q: "Qu’ont en commun deux énantiomères ?", a: ["Les mêmes températures de fusion et d’ébullition, mais des pouvoirs rotatoires opposés", "Des températures de fusion différentes et le même pouvoir rotatoire", "Les mêmes propriétés biologiques dans tous les cas", "Des propriétés chimiques différentes vis-à-vis de tous les réactifs"], c: 0, e: "Deux énantiomères ont les mêmes propriétés physiques et chimiques (face à des réactifs non chiraux), sauf le signe du pouvoir rotatoire. Face à des récepteurs chiraux, leurs effets biologiques peuvent différer." },
  { d: 7, o: "7.4", q: "À propos d’un mélange racémique, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Il contient les deux énantiomères en proportions égales", "Il est optiquement inactif", "C’est un composé méso", "Il contient deux diastéréoisomères", "Il dévie la lumière polarisée vers la droite"], c: [0, 1], x: ["Mélange 50/50.", "Les pouvoirs rotatoires opposés se compensent.", "Un composé méso est une molécule unique achirale ; le racémique est un mélange.", "Il contient deux énantiomères.", "Aucune déviation globale."], e: "Racémique : mélange équimolaire d’énantiomères, sans activité optique." },
  { d: 7, o: "7.4", q: "Qu’est-ce que des diastéréoisomères ?", a: ["Des stéréoisomères qui ne sont pas images l’un de l’autre dans un miroir", "Des stéréoisomères images l’un de l’autre dans un miroir", "Des isomères de constitution", "Deux conformations d’une même molécule"], c: 0, e: "Stéréoisomères non énantiomères : ils ont des propriétés physiques et chimiques différentes (isomères Z/E, molécules à plusieurs C* dont une partie seulement des configurations diffère)." },
  { d: 7, o: "7.4", q: "Quelle relation lie les stéréoisomères (2R,3R) et (2S,3S) d’une molécule non méso ?", a: ["Ce sont des énantiomères", "Ce sont des diastéréoisomères", "C’est la même molécule", "Ce sont des isomères de constitution"], c: 0, e: "Tous les centres sont inversés : l’un est l’image de l’autre dans un miroir. Énantiomères." },
  { d: 7, o: "7.4", q: "Quelle relation lie les stéréoisomères (2R,3R) et (2R,3S) d’une même molécule ?", a: ["Ce sont des diastéréoisomères", "Ce sont des énantiomères", "Ce sont des conformères", "Ce sont des isomères de position"], c: 0, e: "Un seul des deux centres est inversé : ce ne sont pas des images miroir. Diastéréoisomères (ici épimères)." },
  { d: 7, o: "7.4", q: "Selon les règles de Cahn-Ingold-Prelog, quel est le substituant prioritaire parmi –OH, –NH₂, –CH₃ et –COOH ?", a: ["–OH", "–COOH", "–NH₂", "–CH₃"], c: 0, e: "On compare le numéro atomique de l’atome directement lié : O (8) > N (7) > C (6). –COOH est lié par un carbone : il passe après –OH et –NH₂, malgré sa masse." },
  { d: 7, o: "7.4", q: "Le substituant de priorité 4 pointe vers l’arrière et l’on parcourt 1 → 2 → 3 dans le sens des aiguilles d’une montre. Quelle est la configuration du carbone asymétrique ?", a: ["R", "S", "Z", "E"], c: 0, e: "Groupe 4 à l’arrière et sens horaire : R (rectus). Z et E concernent les doubles liaisons." },
  { d: 7, o: "7.4", q: "Sur une projection de Fischer, le substituant de priorité 4 est sur un trait horizontal et le sens 1 → 2 → 3 est horaire. Quelle est la configuration ?", a: ["S", "R", "On ne peut pas conclure", "Méso"], c: 0, e: "Les traits horizontaux pointent vers l’avant : le groupe 4 est vers l’observateur. Il faut inverser la lecture : horaire → S." },
  { d: 7, o: "7.4", q: "Laquelle de ces molécules présente une isomérie Z/E ?", a: ["Le but-2-ène \\(\\ce{CH3-CH=CH-CH3}\\)", "Le but-1-ène \\(\\ce{CH2=CH-CH2-CH3}\\)", "Le 2-méthylpropène \\(\\ce{(CH3)2C=CH2}\\)", "L’éthène \\(\\ce{CH2=CH2}\\)"], c: 0, e: "Il faut que chaque carbone de la double liaison porte deux groupes différents. Dans le but-2-ène, chaque carbone porte H et CH₃. Dans les autres, au moins un carbone porte deux groupes identiques." },
  { d: 7, o: "7.4", q: "Quelle est la configuration absolue de la L-cystéine ?", a: ["R", "S", "Elle n’a pas de carbone asymétrique", "Méso"], c: 0, e: "Les acides aminés L sont en général S. Dans la cystéine, le groupe –CH₂SH (C lié à S, Z = 16) est prioritaire sur –COOH (C lié à O, O, O) : l’ordre des priorités change et la L-cystéine est R." },
  { d: 7, o: "7.4", q: "À propos de la chiralité, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Une molécule qui possède un seul carbone asymétrique est chirale", "Un carbone hybridé sp² ne peut pas être asymétrique", "Toute molécule qui possède deux carbones asymétriques est chirale", "Le signe (+) du pouvoir rotatoire correspond toujours à la configuration R", "Un groupe \\(\\ce{CH2}\\) peut être un carbone asymétrique"], c: [0, 1], x: ["Elle ne peut pas avoir de plan de symétrie.", "Il ne porte que 3 substituants.", "Une forme méso possède deux C* mais est achirale.", "Aucun lien entre (+)/(−) et R/S.", "Il porte deux H identiques."], e: "Un seul C* : chirale à coup sûr ; plusieurs C* : vérifier l’absence de symétrie interne (méso)." },
  { d: 7, o: "7.4", q: "À propos des épimères, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Le D-glucose et le D-galactose sont épimères en C4", "Des épimères sont des diastéréoisomères", "Le D-glucose et le D-mannose sont énantiomères", "Des épimères ont les mêmes propriétés physiques", "Le D-glucose et le L-glucose sont épimères"], c: [0, 1], x: ["Ils ne diffèrent que par la configuration du C4.", "Stéréoisomères non images miroir.", "Ils sont épimères en C2.", "Diastéréoisomères : propriétés différentes.", "Tous les C* sont inversés : ce sont des énantiomères."], e: "Épimères : diastéréoisomères qui ne diffèrent que par un seul centre asymétrique." },
  { d: 7, o: "7.4", q: "À propos de l’acide tartrique, qui possède deux carbones asymétriques identiquement substitués, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Sa forme méso possède un plan de symétrie interne", "Il existe sous 3 stéréoisomères", "Sa forme méso est chirale", "Sa forme méso a un pouvoir rotatoire non nul", "Il existe sous 4 stéréoisomères distincts"], c: [0, 1], x: ["C’est ce qui la rend achirale.", "Deux énantiomères (R,R) et (S,S) + la forme méso.", "Elle est achirale malgré ses deux C*.", "Achirale : pouvoir rotatoire nul.", "(R,S) et (S,R) sont la même molécule méso."], e: "Une forme méso réduit le nombre de stéréoisomères sous 2ⁿ." },
  { d: 7, o: "7.4", q: "À propos des énantiomères en biologie et en pharmacologie, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Deux énantiomères peuvent avoir des effets biologiques différents", "Les acides aminés des protéines appartiennent à la série L", "Les oses naturels appartiennent majoritairement à la série D", "Deux énantiomères ont des températures de fusion différentes", "Un mélange racémique dévie la lumière polarisée"], c: [0, 1, 2], x: ["Récepteurs et enzymes sont chiraux (thalidomide, ibuprofène).", "L-acides aminés.", "D-glucose, D-ribose…", "Elles sont identiques.", "Les deux énantiomères se compensent."], e: "Le vivant est chiral : il distingue les énantiomères." },

  // 7.5 Réactivité
  { d: 7, o: "7.5", q: "Parmi ces espèces, laquelle est un nucléophile ?", a: ["L’ion hydroxyde \\(\\ce{HO-}\\)", "L’ion \\(\\ce{H+}\\)", "Un carbocation", "Le carbone d’un groupe C=O"], c: 0, e: "Un nucléophile est riche en électrons : HO⁻ porte une charge négative et des doublets non liants. Les trois autres sont pauvres en électrons : électrophiles." },
  { d: 7, o: "7.5", q: "Dans un aldéhyde, quel atome est le site électrophile ?", a: ["Le carbone du groupe C=O", "L’oxygène du groupe C=O", "L’hydrogène lié au carbonyle", "Aucun"], c: 0, e: "L’oxygène, plus électronégatif, attire les électrons de la double liaison : le carbone porte δ+, il est attaqué par les nucléophiles (addition nucléophile)." },
  { d: 7, o: "7.5", q: "Quel est le produit majoritaire de l’addition de HBr sur le propène \\(\\ce{CH2=CH-CH3}\\) ?", a: ["Le 2-bromopropane", "Le 1-bromopropane", "Le 1,2-dibromopropane", "Le propane"], c: 0, e: "Règle de Markovnikov : H se fixe sur le carbone le plus hydrogéné (CH₂), le carbocation le plus stable se forme sur C2, où se fixe Br." },
  { d: 7, o: "7.5", q: "Quel est le produit de l’hydrogénation catalytique (H₂, Ni) du but-1-ène ?", a: ["Le butane", "Le butan-1-ol", "Le but-1-yne", "Le butanal"], c: 0, e: "H₂ s’additionne sur la double liaison, qui devient simple : alcane. C’est une addition, et aussi une réduction." },
  { d: 7, o: "7.5", q: "Quel produit obtient-on par oxydation ménagée de l’éthanol avec un excès de dichromate en milieu acide ?", a: ["L’acide éthanoïque", "L’éthanal uniquement", "La propanone", "L’éthène"], c: 0, e: "Un alcool primaire s’oxyde en aldéhyde, puis, en présence d’un excès d’oxydant, en acide carboxylique." },
  { d: 7, o: "7.5", q: "Quel produit donne l’oxydation ménagée du propan-2-ol ?", a: ["La propanone", "Le propanal", "L’acide propanoïque", "Le propène"], c: 0, e: "Un alcool secondaire s’oxyde en cétone ; l’oxydation s’arrête là." },
  { d: 7, o: "7.5", q: "Que se passe-t-il si l’on traite le 2-méthylpropan-2-ol (alcool tertiaire) par du permanganate en conditions douces ?", a: ["Pas d’oxydation ménagée", "Formation d’un aldéhyde", "Formation d’une cétone", "Formation d’un acide carboxylique"], c: 0, e: "Le carbone porteur du OH n’a pas d’hydrogène : l’oxydation ménagée est impossible sans rupture du squelette carboné." },
  { d: 7, o: "7.5", q: "Quels sont les produits de l’estérification de l’acide éthanoïque par l’éthanol ?", a: ["Éthanoate d’éthyle et eau", "Éthanoate d’éthyle et dihydrogène", "Éthoxyéthane et eau", "Éthanal et éthanol"], c: 0, e: "Acide + alcool ⇌ ester + eau : CH₃COOH + CH₃CH₂OH ⇌ CH₃COOCH₂CH₃ + H₂O." },
  { d: 7, o: "7.5", q: "Quels sont les produits de la saponification de l’éthanoate d’éthyle par la soude ?", a: ["Ion éthanoate et éthanol, réaction totale", "Acide éthanoïque et éthanol, réaction limitée", "Éthanal et méthanol", "Éthène et acide éthanoïque"], c: 0, e: "Ester + HO⁻ → carboxylate + alcool. L’ion carboxylate ne réagit pas avec l’alcool : la réaction est totale, contrairement à l’hydrolyse acide." },
  { d: 7, o: "7.5", q: "Quel produit forme la déshydratation de l’éthanol (acide sulfurique, chauffage) ?", a: ["L’éthène", "L’éthanal", "L’éthane", "L’acide éthanoïque"], c: 0, e: "Élimination d’une molécule d’eau (OH et H portés par deux carbones voisins) avec formation d’une double liaison C=C." },
  { d: 7, o: "7.5", q: "Quel est le produit majoritaire de la déshydratation du butan-2-ol ?", a: ["Le but-2-ène", "Le but-1-ène", "La butanone", "Le butane"], c: 0, e: "Règle de Zaïtsev : l’alcène le plus substitué, donc le plus stable, est majoritaire. Le but-1-ène est le produit minoritaire." },
  { d: 7, o: "7.5", q: "À propos de la substitution nucléophile SN2, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Elle se fait en une seule étape", "Elle s’accompagne d’une inversion de configuration", "Elle passe par un carbocation", "Elle est favorisée sur un carbone tertiaire", "Sa vitesse ne dépend que de la concentration en halogénoalcane"], c: [0, 1], x: ["Réaction concertée.", "Inversion de Walden : le nucléophile attaque à l’opposé du groupe partant.", "C’est la SN1.", "Elle est favorisée sur un carbone primaire (peu encombré).", "v = k[RX][Nu] : elle dépend aussi du nucléophile."], e: "SN2 : une étape, bimoléculaire, inversion ; SN1 : deux étapes, carbocation, racémisation." },
  { d: 7, o: "7.5", q: "Quelle caractéristique est propre à la substitution nucléophile SN1 ?", a: ["Elle passe par un carbocation et conduit à une racémisation", "Elle se fait en une seule étape concertée", "Elle est favorisée sur les carbones primaires", "Sa vitesse dépend de la concentration du nucléophile"], c: 0, e: "SN1 : départ du groupe partant (étape lente) → carbocation plan, attaqué des deux côtés → racémisation. Favorisée sur les carbones tertiaires ; v = k[RX]." },
  { d: 7, o: "7.5", q: "Quel produit donne la réduction du propanal (par \\(\\ce{NaBH4}\\) par exemple) ?", a: ["Le propan-1-ol", "Le propan-2-ol", "L’acide propanoïque", "La propanone"], c: 0, e: "La réduction d’un aldéhyde donne un alcool primaire ; celle d’une cétone, un alcool secondaire. L’acide propanoïque serait un produit d’oxydation." },
  { d: 7, o: "7.5", q: "Quels sont les produits de l’hydrolyse de l’éthanoate de méthyle ?", a: ["Acide éthanoïque et méthanol", "Acide méthanoïque et éthanol", "Éthanal et méthanol", "Méthoxyméthane et eau"], c: 0, e: "L’hydrolyse est l’inverse de l’estérification : la partie « éthanoate » redonne l’acide éthanoïque, la partie « méthyle » le méthanol. Elle est lente et limitée." },
  { d: 7, o: "7.5", q: "La réaction \\(\\ce{CH3CH2Br + HO- -> CH3CH2OH + Br-}\\) est :", a: ["Une substitution nucléophile", "Une addition électrophile", "Une élimination", "Une estérification"], c: 0, e: "Le groupe –Br est remplacé par –OH : substitution. Le réactif qui attaque (HO⁻) est un nucléophile ; le carbone lié au brome est électrophile." },
  { d: 7, o: "7.5", q: "À propos de l’estérification, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Elle est lente", "Elle est limitée", "Elle est catalysée par les ions \\(\\ce{H+}\\)", "Elle est totale", "Un catalyseur permet d’augmenter son rendement"], c: [0, 1, 2], x: ["Il faut chauffer longtemps.", "≈ 67 % pour un mélange équimolaire acide + alcool primaire.", "L’acide sulfurique est souvent utilisé.", "Elle est limitée par l’hydrolyse inverse.", "Il accélère sans déplacer l’équilibre ; on augmente le rendement avec un excès de réactif ou en éliminant l’eau."], e: "Estérification : lente, limitée, athermique, catalysée par H⁺." },
  { d: 7, o: "7.5", q: "Parmi ces espèces, lesquelles sont des nucléophiles ? (Choisissez 2 réponses)", a: ["L’ammoniac \\(\\ce{NH3}\\)", "L’eau \\(\\ce{H2O}\\)", "L’ion \\(\\ce{H+}\\)", "Un carbocation \\(\\ce{R3C+}\\)", "Le carbone d’un groupe C=O"], c: [0, 1], x: ["Doublet non liant sur N.", "Doublets non liants sur O.", "Il n’a aucun électron : électrophile.", "Lacune électronique : électrophile.", "Il porte δ+ : électrophile."], e: "Nucléophile : doublet disponible ; électrophile : lacune ou charge +/δ+." },
  { d: 7, o: "7.5", q: "Quelles associations réaction/type sont correctes ? (Choisissez 2 réponses)", a: ["\\(\\ce{CH2=CH2 + H2O -> CH3CH2OH}\\) : addition", "\\(\\ce{CH3CH2OH -> CH2=CH2 + H2O}\\) : élimination", "\\(\\ce{CH3CH2Cl + HO- -> CH3CH2OH + Cl-}\\) : addition", "La saponification d’un ester : élimination", "L’hydrogénation d’un alcène : oxydation"], c: [0, 1], x: ["Hydratation d’un alcène.", "Déshydratation d’un alcool.", "Substitution : Cl remplacé par OH.", "C’est une hydrolyse en milieu basique.", "C’est une réduction (gain d’hydrogène)."], e: "Addition : deux réactifs → un produit sur une liaison multiple ; élimination : l’inverse ; substitution : échange de groupes." },
  { d: 7, o: "7.5", q: "Dans le foie, l’éthanol est oxydé par l’alcool déshydrogénase en présence de \\(\\ce{NAD+}\\). Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["L’éthanol est oxydé en éthanal", "Le \\(\\ce{NAD+}\\) est réduit en NADH", "L’éthanal est ensuite réduit en acide acétique", "L’éthanol est un alcool secondaire", "Le NADH joue le rôle d’oxydant dans cette étape"], c: [0, 1], x: ["Alcool primaire → aldéhyde.", "Il capte les électrons (et un H⁺).", "L’éthanal est oxydé (et non réduit) en acide acétique.", "Le carbone porteur du OH est lié à un seul carbone : primaire.", "L’oxydant est NAD⁺ ; NADH est le produit réduit."], e: "Éthanol → éthanal → acétate : deux oxydations successives couplées à la réduction de NAD⁺." },

  // ===================== Domaine 8 — Chimie du vivant (42) =====================
  // 8.1 Acides aminés
  { d: 8, o: "8.1", q: "Quel est le seul des 20 acides aminés standard à ne pas être chiral ?", a: ["La glycine", "L’alanine", "La proline", "La cystéine"], c: 0, e: "Dans la glycine, la chaîne latérale R est un H : le carbone α porte deux H et n’est pas asymétrique." },
  { d: 8, o: "8.1", q: "L’alanine a pour pKa 2,34 (α-COOH) et 9,69 (α-NH₃⁺). Quel est son point isoélectrique ?", a: ["6,0", "12,0", "7,4", "3,7"], c: 0, e: "Chaîne latérale non ionisable : pHi = (2,34 + 9,69) / 2 ≈ 6,0. 12,0 est la somme sans division ; 7,4 est le pH sanguin." },
  { d: 8, o: "8.1", q: "Sous quelle forme se trouve majoritairement l’alanine à pH 7 ?", a: ["\\(\\ce{H3N+-CH(CH3)-COO-}\\) (zwitterion)", "\\(\\ce{H2N-CH(CH3)-COOH}\\) (forme neutre non ionisée)", "\\(\\ce{H3N+-CH(CH3)-COOH}\\) (cation)", "\\(\\ce{H2N-CH(CH3)-COO-}\\) (anion)"], c: 0, e: "À pH 7, pH > pKa(COOH) ≈ 2 donc COO⁻ ; pH < pKa(NH₃⁺) ≈ 9,7 donc NH₃⁺. Forme zwitterionique de charge nette nulle. La forme neutre non ionisée est ultra-minoritaire en solution." },
  { d: 8, o: "8.1", q: "Quelle est la charge nette de la glycine à pH 1 ?", a: ["+1", "0", "−1", "+2"], c: 0, e: "pH 1 < pKa(COOH) ≈ 2,3 : le carboxyle est protoné (COOH, neutre) ; l’amine est protonée (NH₃⁺) : charge +1." },
  { d: 8, o: "8.1", q: "Lors d’une électrophorèse à pH 8,6, vers quelle électrode migre la glycine (pHi ≈ 6,0) ?", a: ["Vers l’anode (+)", "Vers la cathode (−)", "Elle ne migre pas", "Elle migre alternativement vers les deux"], c: 0, e: "pH > pHi : la molécule a perdu des protons, sa charge nette est négative : elle migre vers l’anode (pôle +)." },
  { d: 8, o: "8.1", q: "Parmi ces acides aminés, lequel est chargé positivement à pH 7 ?", a: ["La lysine", "L’acide aspartique", "La leucine", "La sérine"], c: 0, e: "La lysine est un acide aminé basique : sa chaîne latérale –NH₃⁺ (pKa ≈ 10,5) est protonée à pH 7. L’aspartate est acide (chargé −), la leucine apolaire, la sérine polaire non chargée." },
  { d: 8, o: "8.1", q: "Combien de dipeptides différents peut-on former avec une glycine et une alanine (chacune utilisée une fois) ?", a: ["2", "1", "4", "3"], c: 0, e: "Gly-Ala et Ala-Gly sont deux dipeptides différents : un peptide est orienté, de l’extrémité N-terminale vers l’extrémité C-terminale." },
  { d: 8, o: "8.1", q: "À propos des acides aminés, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Les acides aminés des protéines appartiennent à la série L", "Le carbone α porte un groupe carboxyle, un groupe amine, un H et une chaîne latérale", "Les 20 acides aminés standard sont tous chiraux", "La lysine est un acide aminé acide", "La proline possède une fonction amine primaire"], c: [0, 1], x: ["Série L en projection de Fischer.", "Structure générale des α-acides aminés.", "La glycine ne l’est pas.", "C’est un acide aminé basique.", "Son azote est engagé dans un cycle : amine secondaire."], e: "Structure générale : H₂N–CHR–COOH ; la chaîne R fixe la classification." },
  { d: 8, o: "8.1", q: "L’acide aspartique a pour pKa 1,88 (α-COOH), 3,65 (chaîne latérale) et 9,60 (α-NH₃⁺). Quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Son pHi vaut environ 2,77", "À pH 7, sa charge nette est d’environ −1", "Son pHi vaut (1,88 + 9,60) / 2 = 5,74", "À pH 7, il migre vers la cathode", "À pH 7, sa chaîne latérale est protonée et neutre"], c: [0, 1], x: ["Acide aminé acide : moyenne des deux pKa les plus bas, (1,88 + 3,65) / 2.", "Deux COO⁻ et un NH₃⁺ : −2 + 1 = −1.", "On ne prend pas les deux pKa extrêmes pour un acide aminé acide.", "Chargé négativement, il migre vers l’anode.", "pH 7 > 3,65 : la chaîne latérale est sous forme COO⁻."], e: "Pour le pHi, on encadre la forme neutre : les deux pKa qui l’entourent." },
  { d: 8, o: "8.1", q: "À propos de la liaison peptidique, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Elle est plane", "Elle a un caractère partiel de double liaison", "Un tripeptide contient deux liaisons peptidiques", "La rotation est libre autour de la liaison C–N peptidique", "Elle se forme par réaction entre deux groupes carboxyle"], c: [0, 1, 2], x: ["Les 6 atomes du groupe amide sont coplanaires.", "Délocalisation du doublet de N vers C=O.", "n acides aminés → n − 1 liaisons.", "Elle est bloquée (caractère de double liaison).", "Entre le COOH d’un acide aminé et le NH₂ du suivant, avec perte d’eau."], e: "Liaison peptidique : fonction amide plane et rigide, formée par condensation." },

  // 8.2 Peptides et protéines
  { d: 8, o: "8.2", q: "Qu’appelle-t-on la structure primaire d’une protéine ?", a: ["La séquence de ses acides aminés", "Son repliement en hélice α et en feuillets β", "Son repliement tridimensionnel complet", "L’association de plusieurs sous-unités"], c: 0, e: "Structure primaire = enchaînement des acides aminés reliés par des liaisons peptidiques, de N-terminal à C-terminal. Les autres propositions décrivent les structures secondaire, tertiaire et quaternaire." },
  { d: 8, o: "8.2", q: "Quelles interactions stabilisent principalement l’hélice α ?", a: ["Des liaisons hydrogène entre les groupes C=O et N–H du squelette peptidique", "Des ponts disulfure entre cystéines", "Des interactions hydrophobes entre chaînes latérales", "Des liaisons ioniques entre extrémités N- et C-terminales"], c: 0, e: "Dans l’hélice α, le C=O du résidu n forme une liaison hydrogène avec le N–H du résidu n + 4 : ce sont des groupes de la chaîne principale, pas des chaînes latérales." },
  { d: 8, o: "8.2", q: "Qu’est-ce qu’un pont disulfure ?", a: ["Une liaison covalente S–S entre deux cystéines", "Une liaison hydrogène entre deux méthionines", "Une interaction ionique entre deux groupes soufrés", "Une liaison peptidique particulière"], c: 0, e: "Deux groupes –SH de cystéines s’oxydent en –S–S– : c’est la seule interaction covalente parmi celles qui stabilisent la structure tertiaire. Un agent réducteur la rompt." },
  { d: 8, o: "8.2", q: "Laquelle de ces protéines possède une structure quaternaire ?", a: ["L’hémoglobine", "La myoglobine", "Une chaîne polypeptidique isolée", "Un dipeptide"], c: 0, e: "L’hémoglobine est un tétramère α₂β₂ : l’association de ses 4 sous-unités constitue sa structure quaternaire. La myoglobine n’a qu’une seule chaîne." },
  { d: 8, o: "8.2", q: "Après chauffage, une enzyme a perdu son activité. Quelle structure est conservée ?", a: ["La structure primaire", "La structure secondaire", "La structure tertiaire", "Aucune structure n’est conservée"], c: 0, e: "La dénaturation détruit les structures secondaire, tertiaire (et quaternaire), faites d’interactions faibles, mais ne rompt pas les liaisons peptidiques covalentes : la séquence reste intacte." },
  { d: 8, o: "8.2", q: "Quelles interactions participent à la stabilisation de la structure tertiaire d’une protéine ? (Choisissez 3 réponses)", a: ["Les liaisons hydrogène", "Les interactions hydrophobes", "Les ponts disulfure", "Les liaisons phosphodiester", "Les liaisons glycosidiques"], c: [0, 1, 2], x: ["Entre chaînes latérales polaires ou avec le squelette.", "Les résidus apolaires se regroupent au cœur de la protéine.", "Liaisons covalentes entre cystéines.", "Elles relient les nucléotides des acides nucléiques.", "Elles relient les oses."], e: "Liaisons H, effet hydrophobe, ponts salins, Van der Waals, ponts disulfure." },
  { d: 8, o: "8.2", q: "À propos de la dénaturation des protéines, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["La chaleur, les pH extrêmes et l’urée sont des agents dénaturants", "L’expérience d’Anfinsen montre que la séquence détermine le repliement", "La dénaturation rompt les liaisons peptidiques", "La dénaturation est toujours irréversible", "La dénaturation augmente l’activité d’une enzyme"], c: [0, 1], x: ["Ils rompent les interactions faibles.", "La ribonucléase renaturée retrouve son activité.", "C’est l’hydrolyse qui les rompt.", "Elle est parfois réversible.", "Elle lui fait perdre sa fonction."], e: "Dénaturation = perte de la conformation native, structure primaire conservée." },
  { d: 8, o: "8.2", q: "À propos de la structure secondaire des protéines, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["L’hélice α compte 3,6 résidus par tour", "Les feuillets β peuvent être parallèles ou antiparallèles", "Elle est stabilisée principalement par des ponts disulfure", "La proline stabilise l’hélice α", "Dans l’hélice α, les liaisons hydrogène s’établissent entre chaînes latérales"], c: [0, 1], x: ["Hélice droite, pas de 0,54 nm.", "Selon l’orientation relative des brins.", "Ce sont des liaisons hydrogène du squelette.", "Elle la déstabilise (cycle rigide, pas de N–H).", "Entre C=O et N–H du squelette ; les chaînes latérales pointent vers l’extérieur."], e: "Structure secondaire : repliements locaux du squelette, liaisons H C=O···H–N." },

  // 8.3 Glucides
  { d: 8, o: "8.3", q: "Comment classe-t-on le glucose ?", a: ["Aldohexose", "Cétohexose", "Aldopentose", "Disaccharide"], c: 0, e: "Le glucose a 6 carbones (hexose) et une fonction aldéhyde en C1 (aldose)." },
  { d: 8, o: "8.3", q: "Comment classe-t-on le fructose ?", a: ["Cétohexose", "Aldohexose", "Cétopentose", "Polysaccharide"], c: 0, e: "Le fructose a 6 carbones et une fonction cétone en C2 : c’est un cétose, isomère de fonction du glucose (même formule C₆H₁₂O₆)." },
  { d: 8, o: "8.3", q: "Parmi ces glucides, lequel n’est pas réducteur ?", a: ["Le saccharose", "Le maltose", "Le lactose", "Le glucose"], c: 0, e: "Dans le saccharose, la liaison glycosidique engage les deux carbones anomériques (C1 du glucose et C2 du fructose) : aucun OH anomérique libre, pas de pouvoir réducteur." },
  { d: 8, o: "8.3", q: "Quel type de liaison glycosidique relie les glucoses de la cellulose ?", a: ["β(1→4)", "α(1→4)", "α(1→6)", "α(1→2)β"], c: 0, e: "Cellulose : Glc β(1→4), chaînes linéaires rigides. L’amidon et le glycogène utilisent α(1→4) et α(1→6)." },
  { d: 8, o: "8.3", q: "Sous quelle forme le glucose est-il stocké dans le foie et les muscles ?", a: ["Le glycogène", "L’amidon", "La cellulose", "Le saccharose"], c: 0, e: "Le glycogène est la réserve de glucose animale ; il est plus ramifié (α(1→6) plus fréquentes) que l’amylopectine de l’amidon, réserve végétale." },
  { d: 8, o: "8.3", q: "À propos des disaccharides, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Le lactose est formé de galactose et de glucose unis par une liaison β(1→4)", "Le maltose provient de l’hydrolyse de l’amidon", "Le saccharose est un sucre réducteur", "La lactase hydrolyse le saccharose", "Le maltose contient du fructose"], c: [0, 1], x: ["Gal β(1→4) Glc, sucre du lait.", "Glc α(1→4) Glc.", "Il n’est pas réducteur (deux C anomériques engagés).", "Elle hydrolyse le lactose ; la saccharase hydrolyse le saccharose.", "Deux glucoses."], e: "Maltose (Glc-Glc), lactose (Gal-Glc), saccharose (Glc-Fru, non réducteur)." },
  { d: 8, o: "8.3", q: "Combien d’aldohexoses stéréoisomères existe-t-il (série D et L confondues) ?", a: ["16", "8", "4", "32"], c: 0, e: "La forme ouverte d’un aldohexose possède 4 carbones asymétriques (C2 à C5) : 2⁴ = 16 stéréoisomères (8 D et 8 L)." },
  { d: 8, o: "8.3", q: "À propos de la cyclisation des oses, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Le glucose forme majoritairement un cycle à 6 atomes (pyranose)", "La cyclisation crée un nouveau carbone asymétrique, le carbone anomérique", "Les anomères α et β sont des énantiomères", "Le fructose ne forme que des cycles à 6 atomes", "La cyclisation est une estérification"], c: [0, 1], x: ["OH du C5 sur le C1.", "C1 du glucose, C2 du fructose.", "Ils ne diffèrent que par un carbone : ce sont des diastéréoisomères (anomères).", "Il forme un furanose (cycle à 5) dans le saccharose, par exemple.", "C’est la formation d’un hémiacétal (addition nucléophile d’un alcool sur un carbonyle)."], e: "Cyclisation = hémiacétal intramoléculaire → anomères α et β en équilibre (mutarotation)." },
  { d: 8, o: "8.3", q: "À propos des polysaccharides, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Amidon, glycogène et cellulose sont des polymères du glucose", "L’être humain ne digère pas la cellulose, faute d’enzyme hydrolysant les liaisons β(1→4) du glucose", "Le glycogène est une réserve végétale", "L’amylose est très ramifiée par des liaisons α(1→6)", "La cellulose contient des liaisons α(1→4)"], c: [0, 1], x: ["Homopolysaccharides de glucose.", "C’est une fibre alimentaire.", "C’est la réserve animale.", "L’amylose est linéaire ; c’est l’amylopectine qui est ramifiée.", "Elle contient des liaisons β(1→4)."], e: "C’est le type de liaison (α ou β) qui distingue réserve digestible et fibre de structure." },

  // 8.4 Lipides
  { d: 8, o: "8.4", q: "Qu’est-ce qu’un triglycéride ?", a: ["Un triester du glycérol et de trois acides gras", "Un polymère de trois glucoses", "Un phospholipide à trois chaînes", "Un acide gras à trois doubles liaisons"], c: 0, e: "Triacylglycérol : les trois fonctions alcool du glycérol (propane-1,2,3-triol) sont estérifiées par des acides gras. Principale réserve énergétique." },
  { d: 8, o: "8.4", q: "Quelle est la configuration habituelle des doubles liaisons des acides gras insaturés naturels ?", a: ["Cis (Z)", "Trans (E)", "Moitié cis, moitié trans", "Elles n’ont pas de configuration"], c: 0, e: "Les acides gras naturels sont surtout cis : chaque double liaison crée un coude dans la chaîne. Les acides gras trans proviennent surtout de l’hydrogénation partielle industrielle." },
  { d: 8, o: "8.4", q: "Parmi ces acides gras, lequel a la température de fusion la plus élevée ?", a: ["Acide stéarique (C18:0)", "Acide oléique (C18:1)", "Acide linoléique (C18:2)", "Acide palmitoléique (C16:1)"], c: 0, e: "À longueur égale, un acide gras saturé fond plus haut : ses chaînes droites s’empilent mieux. Chaque double liaison cis abaisse la température de fusion." },
  { d: 8, o: "8.4", q: "Pourquoi les phospholipides forment-ils spontanément des bicouches dans l’eau ?", a: ["Ils sont amphiphiles : tête polaire et queues hydrophobes", "Ils sont totalement hydrophobes", "Ils sont totalement hydrophiles", "Ils forment des liaisons covalentes entre eux"], c: 0, e: "Les têtes polaires (phosphate + alcool) se tournent vers l’eau ; les deux queues d’acides gras se regroupent à l’abri de l’eau : bicouche, base des membranes biologiques." },
  { d: 8, o: "8.4", q: "Lequel de ces acides gras est un oméga-3 ?", a: ["L’acide α-linolénique (C18:3)", "L’acide linoléique (C18:2)", "L’acide oléique (C18:1)", "L’acide palmitique (C16:0)"], c: 0, e: "L’acide α-linolénique a sa dernière double liaison en position ω3 (3ᵉ carbone à partir du méthyle terminal). L’acide linoléique est un ω6, l’oléique un ω9 ; le palmitique est saturé." },
  { d: 8, o: "8.4", q: "À propos des membranes biologiques, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Elles sont constituées d’une bicouche de phospholipides", "Elles sont décrites par le modèle de la mosaïque fluide", "Le cholestérol module leur fluidité", "Elles sont imperméables au dioxygène", "Les ions les traversent librement par diffusion simple"], c: [0, 1, 2], x: ["Têtes vers l’eau, queues au centre.", "Singer et Nicolson, 1972.", "Il s’insère entre les phospholipides.", "Les petites molécules apolaires (O₂, CO₂) diffusent facilement.", "Les ions passent par des canaux et des transporteurs."], e: "Bicouche lipidique fluide où flottent des protéines : barrière sélective." },
  { d: 8, o: "8.4", q: "À propos des acides gras saturés et insaturés, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["La température de fusion augmente avec la longueur de la chaîne", "Les doubles liaisons cis créent un coude dans la chaîne", "Les huiles végétales liquides sont riches en acides gras saturés", "Les acides gras trans sont les plus abondants à l’état naturel", "Un acide gras saturé contient au moins une double liaison"], c: [0, 1], x: ["Plus d’interactions de Van der Waals.", "D’où un empilement moins compact.", "Elles sont riches en insaturés, d’où leur état liquide.", "Les naturels sont surtout cis.", "Saturé = aucune double liaison C=C."], e: "Longueur ↑ → Tf ↑ ; insaturations cis ↑ → Tf ↓." },
  { d: 8, o: "8.4", q: "Quel apport énergétique approximatif fournit 1 g de lipides ?", a: ["Environ 9 kcal (37 kJ)", "Environ 4 kcal (17 kJ)", "Environ 1 kcal (4 kJ)", "Environ 20 kcal (84 kJ)"], c: 0, e: "Les lipides fournissent environ 9 kcal·g⁻¹, soit plus du double des glucides et des protéines (≈ 4 kcal·g⁻¹) : ce sont des réserves très denses en énergie." },

  // 8.5 Nucléotides
  { d: 8, o: "8.5", q: "Quelles sont les bases puriques ?", a: ["Adénine et guanine", "Cytosine et thymine", "Cytosine et uracile", "Adénine et thymine"], c: 0, e: "Les purines (deux cycles accolés) sont A et G ; les pyrimidines (un cycle) sont C, T et U." },
  { d: 8, o: "8.5", q: "Quelle base azotée trouve-t-on dans l’ARN mais pas dans l’ADN ?", a: ["L’uracile", "La thymine", "L’adénine", "La cytosine"], c: 0, e: "L’ARN contient l’uracile à la place de la thymine (qui est une uracile méthylée). A, G et C sont communes aux deux." },
  { d: 8, o: "8.5", q: "Un ADN double brin contient 20 % d’adénine. Quelle est sa proportion de guanine ?", a: ["30 %", "20 %", "40 %", "60 %"], c: 0, e: "Chargaff : A = T = 20 %, donc G + C = 60 %, et G = C = 30 %." },
  { d: 8, o: "8.5", q: "À propos des nucléosides et des nucléotides, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Un nucléoside est formé d’une base azotée et d’un pentose", "Un nucléotide est un nucléoside portant un ou plusieurs groupes phosphate", "L’adénosine est un nucléotide", "La liaison entre la base et le sucre est une liaison phosphodiester", "La thymidine de l’ADN contient du ribose"], c: [0, 1], x: ["Liaison N-glycosidique sur le C1′.", "Phosphate(s) estérifiant le OH en 5′.", "C’est un nucléoside (sans phosphate) ; l’AMP est le nucléotide.", "C’est une liaison N-glycosidique.", "Elle contient du 2′-désoxyribose."], e: "Base + sucre = nucléoside ; + phosphate = nucléotide." },
  { d: 8, o: "8.5", q: "Quelle liaison relie deux nucléotides successifs dans un brin d’ADN ?", a: ["Une liaison phosphodiester entre le 3′ d’un nucléotide et le 5′ du suivant", "Une liaison peptidique", "Une liaison hydrogène entre bases", "Une liaison glycosidique α(1→4)"], c: 0, e: "Le squelette sucre-phosphate est formé de liaisons phosphodiester 3′→5′ (covalentes). Les liaisons hydrogène relient les bases des deux brins." },
  { d: 8, o: "8.5", q: "À propos de l’ADN et de l’ARN, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["L’ADN contient du 2′-désoxyribose", "L’ARN contient de l’uracile", "L’ADN est formé de deux brins antiparallèles", "L’ARN contient de la thymine", "Le désoxyribose n’a pas de OH en 3′"], c: [0, 1, 2], x: ["Pas de OH en 2′.", "À la place de la thymine.", "Double hélice, brins complémentaires orientés en sens inverse.", "Il contient de l’uracile.", "Il lui manque le OH en 2′ ; le OH en 3′ sert à l’allongement."], e: "ADN : désoxyribose, thymine, double brin ; ARN : ribose, uracile, simple brin." },
  { d: 8, o: "8.5", q: "À propos de l’ATP, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["C’est un nucléotide", "Il contient du ribose et de l’adénine", "C’est un nucléoside", "Il contient du désoxyribose", "Il ne contient qu’un seul groupe phosphate"], c: [0, 1], x: ["Adénosine triphosphate.", "Adénosine = adénine + ribose.", "Il porte des phosphates : nucléotide.", "C’est l’ATP ; le dATP contient du désoxyribose.", "Il en contient trois."], e: "ATP = adénine + ribose + 3 phosphates, reliés par des liaisons phosphoanhydride riches en énergie." },

  // ===================== Domaine 9 — Cinétique (21) =====================
  // 9.1 Vitesse de réaction
  { d: 9, o: "9.1", q: "Pour \\(\\ce{2 N2O5 -> 4 NO2 + O2}\\), la vitesse de disparition de \\(\\ce{N2O5}\\) vaut 0,10 mol·L⁻¹·s⁻¹. Quelle est la vitesse de formation de \\(\\ce{O2}\\) ?", a: ["0,050 mol·L⁻¹·s⁻¹", "0,10 mol·L⁻¹·s⁻¹", "0,20 mol·L⁻¹·s⁻¹", "0,025 mol·L⁻¹·s⁻¹"], c: 0, e: "\\(v = -\\tfrac{1}{2}\\dfrac{\\mathrm{d}[\\ce{N2O5}]}{\\mathrm{d}t} = \\dfrac{\\mathrm{d}[\\ce{O2}]}{\\mathrm{d}t}\\) : il se forme 1 O₂ pour 2 N₂O₅ consommés, soit 0,10 / 2 = 0,050 mol·L⁻¹·s⁻¹." },
  { d: 9, o: "9.1", q: "Pour \\(\\ce{N2 + 3 H2 -> 2 NH3}\\), le dihydrogène disparaît à la vitesse de 0,30 mol·L⁻¹·min⁻¹. Quelle est la vitesse de formation de l’ammoniac ?", a: ["0,20 mol·L⁻¹·min⁻¹", "0,30 mol·L⁻¹·min⁻¹", "0,45 mol·L⁻¹·min⁻¹", "0,10 mol·L⁻¹·min⁻¹"], c: 0, e: "Vitesse de réaction v = 0,30 / 3 = 0,10 ; vitesse de formation de NH₃ = 2 × 0,10 = 0,20 mol·L⁻¹·min⁻¹. 0,10 est la vitesse de disparition de N₂." },
  { d: 9, o: "9.1", q: "Sur la courbe [A] = f(t) d’un réactif, comment détermine-t-on la vitesse de disparition à un instant t ?", a: ["Par la valeur absolue de la pente de la tangente à la courbe en t", "Par la valeur de [A] à l’instant t", "Par l’aire sous la courbe entre 0 et t", "Par le rapport [A]₀ / t"], c: 0, e: "La vitesse instantanée est la dérivée −d[A]/dt, soit l’opposé de la pente de la tangente. [A]₀ / t serait une vitesse moyenne (et encore, seulement si A était épuisé)." },
  { d: 9, o: "9.1", q: "Quel est en général l’effet d’une augmentation de température sur la vitesse d’une réaction ?", a: ["Elle l’augmente, car davantage de molécules franchissent la barrière d’énergie d’activation", "Elle la diminue", "Elle ne change rien", "Elle modifie l’équation bilan"], c: 0, e: "Loi d’Arrhenius \\(k = A\\,e^{-E_a/RT}\\) : k augmente avec T. C’est pourquoi on chauffe les milieux réactionnels et pourquoi on conserve les aliments au froid." },
  { d: 9, o: "9.1", q: "À propos des facteurs influençant la vitesse d’une réaction, quelles affirmations sont exactes ? (Choisissez 3 réponses)", a: ["Augmenter la concentration des réactifs accélère généralement la réaction", "Élever la température accélère généralement la réaction", "Un catalyseur accélère la réaction", "La vitesse d’une réaction est constante du début à la fin", "Diviser finement un réactif solide ralentit la réaction"], c: [0, 1, 2], x: ["Plus de rencontres efficaces.", "Plus de molécules au-delà de Ea.", "Il abaisse Ea.", "Elle diminue en général à mesure que les réactifs sont consommés.", "Elle augmente la surface de contact et accélère la réaction."], e: "Facteurs cinétiques : concentrations, température, catalyseur, surface de contact." },

  // 9.2 Ordre des réactions
  { d: 9, o: "9.2", q: "Quelle est l’unité de la constante de vitesse k d’une réaction d’ordre 1 ?", a: ["s⁻¹", "mol·L⁻¹·s⁻¹", "L·mol⁻¹·s⁻¹", "Elle est sans unité"], c: 0, e: "v = k[A] : (mol·L⁻¹·s⁻¹) = k × (mol·L⁻¹) ⇒ k en s⁻¹. Ordre 0 : mol·L⁻¹·s⁻¹ ; ordre 2 : L·mol⁻¹·s⁻¹." },
  { d: 9, o: "9.2", q: "Pour une réaction d’ordre 0, comment évolue la concentration du réactif au cours du temps ?", a: ["Elle décroît linéairement", "Elle décroît exponentiellement", "Elle reste constante", "Elle décroît comme 1/t"], c: 0, e: "v = k constante : [A] = [A]₀ − kt, une droite de pente −k. C’est le cas de l’élimination de l’éthanol par un foie dont l’enzyme est saturée." },
  { d: 9, o: "9.2", q: "Pour une réaction \\(\\ce{2 A -> produits}\\) d’ordre 2, quelle représentation graphique donne une droite ?", a: ["1/[A] en fonction du temps", "[A] en fonction du temps", "ln[A] en fonction du temps", "[A]² en fonction du temps"], c: 0, e: "Ordre 2 : 1/[A] = 1/[A]₀ + kt (droite de pente k). Ordre 0 : [A] linéaire ; ordre 1 : ln[A] linéaire." },
  { d: 9, o: "9.2", q: "À propos d’une réaction d’ordre 1, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["ln[A] décroît linéairement avec le temps", "Son temps de demi-réaction est indépendant de la concentration initiale", "[A] décroît linéairement avec le temps", "Sa constante k s’exprime en mol·L⁻¹·s⁻¹", "Son temps de demi-réaction vaut [A]₀ / 2k"], c: [0, 1], x: ["ln[A] = ln[A]₀ − kt.", "t½ = ln 2 / k.", "C’est le cas de l’ordre 0 ; ici la décroissance est exponentielle.", "k s’exprime en s⁻¹.", "C’est la formule de l’ordre 0."], e: "Ordre 1 : [A] = [A]₀ e^(−kt), t½ = ln 2 / k, constant." },
  { d: 9, o: "9.2", q: "À propos de la loi de vitesse \\(v = k[\\ce{A}]^\\alpha[\\ce{B}]^\\beta\\), quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Les ordres partiels α et β se déterminent expérimentalement", "L’ordre global vaut α + β", "Les ordres sont toujours égaux aux coefficients stœchiométriques", "Pour une réaction d’ordre 0, la vitesse est proportionnelle à [A]", "La constante k ne dépend pas de la température"], c: [0, 1], x: ["On les mesure ; ils ne se lisent pas sur l’équation bilan.", "Définition de l’ordre global.", "Seulement pour un acte élémentaire.", "Elle est constante, indépendante de [A].", "k augmente avec T (Arrhenius)."], e: "Loi de vitesse : k (fonction de T) et ordres expérimentaux." },

  // 9.3 Demi-vie
  { d: 9, o: "9.3", q: "Une réaction d’ordre 1 a une constante de vitesse k = 0,0693 h⁻¹. Quel est son temps de demi-réaction ?", a: ["10 h", "0,1 h", "14,4 h", "6,93 h"], c: 0, e: "\\(t_{1/2} = \\ln 2 / k = 0{,}693 / 0{,}0693 = 10\\) h. 14,4 h correspond à 1/k." },
  { d: 9, o: "9.3", q: "Pour une réaction d’ordre 1, quelle fraction du réactif reste-t-il après 3 temps de demi-réaction ?", a: ["12,5 %", "33 %", "25 %", "0 %"], c: 0, e: "Après n demi-vies, il reste (½)ⁿ : (½)³ = 1/8 = 12,5 %. La décroissance est exponentielle, jamais exactement nulle." },
  { d: 9, o: "9.3", q: "Un médicament éliminé selon une cinétique d’ordre 1 a une demi-vie plasmatique de 6 h. Sa concentration initiale est 64 mg·L⁻¹. Quelle est sa concentration 24 h plus tard ?", a: ["4 mg·L⁻¹", "16 mg·L⁻¹", "0 mg·L⁻¹", "8 mg·L⁻¹"], c: 0, e: "24 h = 4 demi-vies : 64 / 2⁴ = 64 / 16 = 4 mg·L⁻¹. Une décroissance linéaire (16 mg·L⁻¹ perdus toutes les 6 h) donnerait 0, ce qui est faux pour l’ordre 1." },
  { d: 9, o: "9.3", q: "Un échantillon archéologique ne contient plus que 25 % du carbone 14 initial (\\(t_{1/2}\\) ≈ 5 730 ans). Quel est son âge approximatif ?", a: ["11 460 ans", "5 730 ans", "22 920 ans", "1 432 ans"], c: 0, e: "25 % = (½)² : deux demi-vies se sont écoulées, soit 2 × 5 730 = 11 460 ans." },
  { d: 9, o: "9.3", q: "À propos du temps de demi-réaction et de ses applications, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Après 5 demi-vies d’un processus d’ordre 1, il reste environ 3 % du réactif", "Pour une réaction d’ordre 0, le temps de demi-réaction dépend de la concentration initiale", "Après 2 demi-vies, tout le réactif a disparu", "L’iode 131 a une demi-vie d’environ 8 ans", "Pour une réaction d’ordre 1, doubler la concentration initiale double le temps de demi-réaction"], c: [0, 1], x: ["(½)⁵ = 1/32 ≈ 3 %.", "t½ = [A]₀ / 2k.", "Il en reste un quart.", "Environ 8 jours.", "Pour l’ordre 1, t½ = ln 2 / k ne dépend pas de [A]₀."], e: "La demi-vie constante est la signature de l’ordre 1 (radioactivité, élimination de la plupart des médicaments)." },

  // 9.4 Catalyse
  { d: 9, o: "9.4", q: "Comment un catalyseur accélère-t-il une réaction ?", a: ["En ouvrant un chemin réactionnel d’énergie d’activation plus faible", "En augmentant la température du milieu", "En augmentant la constante d’équilibre", "En rendant la réaction plus exothermique"], c: 0, e: "Le catalyseur participe au mécanisme (intermédiaires) et abaisse la barrière d’énergie ; il est régénéré. Il ne modifie ni ΔrH ni K." },
  { d: 9, o: "9.4", q: "À propos de l’influence d’un catalyseur, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Il ne modifie pas la constante d’équilibre", "Il accélère autant la réaction directe que la réaction inverse", "Il augmente le rendement final d’une réaction limitée", "Il modifie l’enthalpie de réaction", "Il est consommé au cours de la réaction"], c: [0, 1], x: ["K ne dépend que de T.", "L’équilibre est atteint plus vite, sans être déplacé.", "La composition finale à l’équilibre est inchangée.", "Il ne change ni les réactifs ni les produits, donc ni ΔrH ni ΔrG.", "Il est régénéré en fin de réaction."], e: "Un catalyseur agit sur la vitesse (cinétique), jamais sur l’état final (thermodynamique)." },
  { d: 9, o: "9.4", q: "Le pot catalytique d’une voiture transforme des gaz polluants au contact de platine, palladium et rhodium solides. De quel type de catalyse s’agit-il ?", a: ["Catalyse hétérogène", "Catalyse homogène", "Catalyse enzymatique", "Ce n’est pas une catalyse"], c: 0, e: "Catalyseur solide, réactifs gazeux : phases différentes, la réaction a lieu à la surface du métal. C’est une catalyse hétérogène." },
  { d: 9, o: "9.4", q: "Lors d’une estérification, on ajoute quelques gouttes d’acide sulfurique concentré dans le mélange liquide acide + alcool. De quel type de catalyse s’agit-il ?", a: ["Catalyse homogène", "Catalyse hétérogène", "Catalyse enzymatique", "Aucune, l’acide est un réactif"], c: 0, e: "Les ions H⁺ sont dans la même phase liquide que les réactifs : catalyse homogène. Ils sont régénérés et n’apparaissent pas dans l’équation bilan." },
  { d: 9, o: "9.4", q: "Pour une enzyme saturée par une très forte concentration de substrat, quel est l’ordre de la réaction par rapport au substrat ?", a: ["0", "1", "2", "Il est négatif"], c: 0, e: "Quand tous les sites actifs sont occupés, la vitesse plafonne à Vmax et ne dépend plus de [S] : ordre 0. À faible [S], la vitesse est proportionnelle à [S] (ordre 1)." },
  { d: 9, o: "9.4", q: "À propos de la catalyse enzymatique, quelles affirmations sont exactes ? (Choisissez 2 réponses)", a: ["Les enzymes sont très spécifiques de leur substrat", "La pepsine gastrique a un pH optimal voisin de 2", "L’activité d’une enzyme augmente indéfiniment avec la température", "Les enzymes sont consommées au cours de la réaction", "Une enzyme rend spontanée une réaction de \\(\\Delta_r G \\gt 0\\) sans couplage"], c: [0, 1], x: ["Grâce à la forme du site actif.", "Adaptée à l’acidité de l’estomac.", "Au-delà de l’optimum, l’enzyme se dénature et l’activité chute.", "Ce sont des catalyseurs : elles sont régénérées.", "Un catalyseur ne change pas ΔrG ; il faut coupler la réaction à une réaction favorable."], e: "Enzymes : catalyseurs protéiques, efficaces, spécifiques, sensibles à la température et au pH." },
];
